
import { createClient } from '@supabase/supabase-js';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
dotenv.config({ path: path.join(__dirname, '../../../.env') });

const supabase = createClient(
  process.env.SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

const portraits: Record<string, string> = {
  "abdoul-kamardine": "Natif de Mayotte, Abdoul Kamardine a exercé la profession d'enseignant et a été cadre au sein de l'administration territoriale. Conseiller départemental de Mayotte depuis 2015, il est membre du parti Les Républicains. Il est élu député de la 2e circonscription de Mayotte lors des élections législatives de juin 2024.",
  "abel-boyer": "Natif de la Réunion, Abel Boyer a exercé des fonctions de cadre au sein du secteur privé, notamment dans le domaine du commerce et de la gestion. Membre du groupe de la Droite républicaine et engagé dans la vie locale réunionnaise, il s'est investi sur les thématiques de développement économique insulaire. Il est élu député de la 3e circonscription de La Réunion lors des législatives de juillet 2024.",
  "adrien-clouet": "Natif d'Aix-en-Provence et docteur en sociologie, Adrien Clouet a mené une carrière de chercheur postdoctoral au CNRS et d'enseignant universitaire. Spécialiste des questions liées au travail et à l'emploi, il est engagé au sein de La France insoumise. Il est élu député de la 1re circonscription de la Haute-Garonne lors des élections législatives de juin 2022 et réélu en 2024.",
  "adrien-quatennens": "Natif de Lille, Adrien Quatennens a exercé comme conseiller clientèle au sein de l'entreprise EDF après des études en économie et social. Membre de La France insoumise et ancien coordinateur du mouvement, il est spécialisé dans les thématiques liées au droit du travail. Il est élu député de la 1re circonscription du Nord en juin 2017 et réélu lors du scrutin législatif de juin 2022.",
  "agnes-carel": "Native de Paris, Agnès Carel a mené une carrière de cadre dirigeant dans le secteur du tourisme et de l'hôtellerie avant de se consacrer à la vie publique. Adjointe au maire de sa commune d'adoption et membre du parti Renaissance, elle s'est investie dans les politiques de développement local. Elle rejoint l'Assemblée nationale en tant que députée de la 4e circonscription de la Seine-Maritime en janvier 2024.",
  "agnes-firmin-le-bodo": "Native du Havre, Agnès Firmin-Le Bodo exerce la profession de pharmacienne, ayant dirigé sa propre officine pendant de nombreuses années. Ancienne ministre déléguée chargée de l'Organisation territoriale et des Professions de santé, elle est une figure du parti Horizons. Elle est élue députée de la 7e circonscription de la Seine-Maritime lors des élections législatives de juin 2017 et réélue depuis.",
  "agnes-pannier-runacher": "Native de Paris et diplômée de l'ENA et de HEC, Agnès Pannier-Runacher a mené une carrière de haute fonctionnaire et de dirigeante d'entreprise au sein du groupe Caisse des Dépôts et de Faurecia. Ancienne ministre de la Transition écologique et de l'Énergie, elle est membre du parti Renaissance. Elle est élue députée de la 2e circonscription du Pas-de-Calais lors des élections législatives de juillet 2024.",
  "alban-maggiar": "Natif de Paris et diplômé d'HEC, Alban Maggiar a mené une carrière de chef d'entreprise dans le secteur de l'assurance et a présidé la Fédération européenne des PME. Membre du parti Renaissance et engagé sur les thématiques économiques et européennes, il s'est investi dans la vie publique locale. Il est élu député de la 11e circonscription des Français établis hors de France lors des législatives de juillet 2024.",
  "alexandra-martin": "Native de Cannes, Alexandra Martin a exercé comme cadre dans le secteur privé, notamment dans le domaine de l'événementiel et de la communication. Conseillère départementale des Alpes-Maritimes et membre du groupe Droite républicaine, elle s'est investie dans les politiques de solidarité territoriale. Elle est élue députée de la 8e circonscription du département en juin 2022 et réélue en 2024.",
  "alexandra-martin-2": "Native de Paris, Alexandra Martin a exercé la profession d'avocate au barreau de Paris après des études supérieures en droit. Engagée au sein du Parti socialiste et spécialisée dans les questions de justice et de droits fondamentaux, elle s'est investie dans la vie publique de Gironde. Elle est élue députée de la 1re circonscription du département lors des élections législatives de juillet 2024.",
  "alexandre-allegret-pilot": "Natif de Thonon-les-Bains, Alexandre Allegret-Pilot est un haut fonctionnaire au ministère de l'Économie et des Finances après des études à l'ENA. Engagé au sein du groupe Rassemblement national et spécialisé dans les questions budgétaires et industrielles, il s'est investi dans la vie publique du Gard. Il est élu député de la 5e circonscription du département lors des élections législatives de juillet 2024.",
  "alexandre-vincendet": "Natif de Lyon, Alexandre Vincendet a exercé comme collaborateur parlementaire avant de se consacrer à ses mandats locaux. Maire de Rillieux-la-Pape pendant huit ans et membre du parti Horizons, il est engagé sur les enjeux de sécurité et de rénovation urbaine. Il est élu député de la 7e circonscription du Rhône lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "alexis-corbiere": "Natif de Béziers, Alexis Corbière a exercé la profession de professeur de lettres et d'histoire en lycée professionnel après des études supérieures. Porte-parole historique de La France insoumise et auteur de plusieurs ouvrages politiques, il est engagé sur les thématiques sociales et institutionnelles. Il est élu député de la 7e circonscription de la Seine-Saint-Denis en juin 2017 et réélu en 2022 et 2024.",
  "alexis-izard": "Natif de Savigny-sur-Orge, Alexis Izard a mené une carrière de cadre au sein de grands groupes du secteur bancaire et financier après des études supérieures. Membre du parti Renaissance et engagé sur les thématiques économiques et de compétitivité des entreprises, il s'est investi dans la vie publique de l'Essonne. Il est élu député de la 3e circonscription du département en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "alexis-jolly": "Natif de Grenoble, Alexis Jolly a exercé comme cadre administratif et commercial au sein du secteur privé après des études supérieures. Membre du Rassemblement national et conseiller régional d'Auvergne-Rhône-Alpes, il est engagé sur les thématiques de souveraineté industrielle et de développement local. Il est élu député de la 6e circonscription de l'Isère en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "alice-le-moal": "Native de Paris, Alice Le Moal a exercé la profession de conseillère en insertion professionnelle après des études supérieures en psychologie. Adjointe au maire de sa commune d'adoption et membre du MoDem, elle s'est investie dans les politiques de solidarité et d'accompagnement social. Elle est élue députée de la 2e circonscription des Hauts-de-Seine lors des élections législatives de juillet 2024.",
  "alicia-felix": "Native de Paris, Alicia Félicx a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de défense des services publics, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de la 2e circonscription de l'Oise en octobre 2024.",
  "aline-dessine": "Native de Paris, Aline Dessine a exercé la profession de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Écologiste et Social et engagée sur les enjeux de transition écologique et de justice climatique, elle s'est investie dans la vie publique de Loire-Atlantique. Elle est élue députée de la 1re circonscription du département lors des élections législatives de juillet 2024.",
  "alizee-daguerre": "Native de Bayonne, Alizée Daguerre a exercé la profession de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique du Loiret. Elle rejoint l'Assemblée nationale en tant que députée de la 3e circonscription du département en octobre 2024.",
  "alma-dufour": "Native d'Auch, Alma Dufour a mené une carrière de responsable de campagnes au sein de l'ONG Amis de la Terre, luttant notamment contre la surconsommation numérique. Membre de La France insoumise et engagée sur les enjeux d'écologie populaire et de défense des droits sociaux, elle est élue députée de la 4e circonscription de la Seine-Maritime en juin 2022 et réélue en juillet 2024.",
  "aly-diouara": "Natif de Bobigny, Aly Diouara a exercé comme cadre administratif au sein de la fonction publique territoriale après avoir été responsable associatif. Engagé au sein du groupe de la Gauche démocrate et républicaine et portant les thématiques de justice sociale et de lutte contre les inégalités urbaines, il est élu député de la 5e circonscription de la Seine-Saint-Denis lors des élections législatives de juillet 2024.",
  "amanda-clark": "Native de Paris, Amanda Clark a mené une carrière de cadre dirigeant dans le secteur du conseil et des nouvelles technologies avant son engagement public. Membre du groupe Ensemble pour la République et spécialisée dans les questions de souveraineté numérique et d'innovation, elle s'est investie dans la vie publique locale. Elle est élue députée de la 11e circonscription des Français établis hors de France en juillet 2024.",
  "amelie-de-montchalin": "Native de Lyon et diplômée de HEC et de l'université Harvard, Amélie de Montchalin a mené une carrière d'économiste et de cadre dirigeante au sein du groupe AXA. Ancienne ministre de la Transformation et de la Fonction publiques, elle est membre du parti Renaissance. Elle est élue députée de la 6e circonscription de l'Essonne en juin 2017 et réélue lors du scrutin législatif de juin 2022.",
  "amelie-oudia-castera": "Native de Paris et ancienne championne de tennis, Amélie Oudéa-Castéra a mené une carrière de haute fonctionnaire et de dirigeante d'entreprise chez AXA et Carrefour avant de diriger la FFT. Ancienne ministre des Sports et des Jeux Olympiques et Paralympiques, elle est membre du parti Renaissance. Elle rejoint l'Assemblée nationale en tant que députée de la 6e circonscription des Hauts-de-Seine en octobre 2024.",
  "andree-taurine": "Native de Perpignan, Andrée Taurine exerce la profession de professeure d'histoire-géographie au sein de l'Éducation nationale après des études supérieures. Membre de La France insoumise et engagée sur les thématiques de justice sociale et de défense des services publics, elle s'est investie dans la vie publique des Pyrénées-Orientales. Elle est élue députée de la 1re circonscription du département en juin 2022.",
  "andreea-lianu": "Native de Bucarest (Roumanie), Andreea Lianu a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Écologiste et Social et engagée sur les enjeux de solidarité et de transition écologique, elle s'est investie dans la vie publique du Rhône. Elle rejoint l'Assemblée nationale en tant que députée de la 2e circonscription du département en octobre 2024.",
  "andrew-christoff": "Natif de Paris, Andrew Christoff a exercé des fonctions de cadre au sein de la haute administration après des études supérieures en droit public. Membre du groupe Ensemble pour la République et engagé sur les thématiques institutionnelles et de gestion publique, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que députée de la 1re circonscription des Yvelines en octobre 2024.",
  "andy-kerbrat": "Natif de Chambéry, Andy Kerbrat a exercé comme employé au sein du secteur privé après avoir été militant syndical et associatif. Membre de La France insoumise et engagé sur les enjeux de défense des travailleurs et de lutte contre la précarité, il s'est investi dans la vie publique de Loire-Atlantique. Il est élu député de la 2e circonscription du département en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "angelina-favario": "Native de Chambéry, Angélina Favario a exercé comme cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Droite républicaine et engagée sur les enjeux de proximité et de défense de la ruralité, elle s'est investie dans la vie publique de la Savoie. Elle rejoint l'Assemblée nationale en tant que députée de la 2e circonscription du département en octobre 2024.",
  "anna-jacob": "Native de Lyon, Anna Jacob a mené une carrière de cadre au sein de la fonction publique après des études supérieures en sciences politiques. Membre du groupe Écologiste et Social et engagée sur les thématiques de transition écologique et de solidarité urbaine, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de la 4e circonscription du Rhône en octobre 2024.",
  "annaig-le-meur": "Native de Quimper et diplômée en kinésithérapie, Annaïg Le Meur a exercé comme kinésithérapeute libérale et a dirigé un centre de rééducation avant son élection. Membre du parti Renaissance et engagée sur les enjeux de santé et d'accessibilité, elle s'est investie dans la vie publique finistérienne. Elle est élue députée de la 1re circonscription du Finistère en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "anne-bergantz": "Native de Paris, Anne Bergantz a exercé la profession de cadre au sein du secteur médico-social après des études supérieures en gestion. Conseillère municipale de sa commune d'adoption et membre du MoDem, elle s'est investie dans les politiques de santé et de solidarité locale. Elle rejoint l'Assemblée nationale en tant que députée de la 2e circonscription des Yvelines en janvier 2024.",
  "anne-bruant-bisson": "Native de Paris, Anne Bruant-Bisson a exercé comme cadre supérieure au sein de la fonction publique territoriale après une carrière de haute fonctionnaire. Adjointe au maire de sa commune d'adoption et membre du groupe Ensemble pour la République, elle s'est investie dans les politiques de proximité et de développement local. Elle rejoint l'Assemblée nationale en tant que députée d'Eure-et-Loir en octobre 2024.",
  "anne-laure-babault": "Native de Rochefort, Anne-Laure Babault a mené une carrière de cadre commerciale au sein de grands groupes du secteur agroalimentaire après des études supérieures. Membre du parti MoDem et engagée sur les thématiques de consommation durable et de soutien aux filières locales, elle s'est investie dans la vie publique de Charente-Maritime. Elle est élue députée de la 2e circonscription du département en juin 2022.",
  "anne-laure-blin": "Native de Cholet, Anne-Laure Blin a exercé la profession de consultante en stratégie et communication après des études supérieures en droit public. Membre du groupe Droite républicaine et engagée sur les enjeux de défense de la ruralité et des libertés locales, elle s'est investie dans la vie publique du Maine-et-Loire. Elle est élue députée de la 3e circonscription du département lors d'une partielle en 2020 et réélue depuis.",
  "anne-le-henanff": "Native de Vannes, Anne Le Hénanff a mené une carrière de cadre au sein du secteur privé, spécialisée dans le numérique et la cybersécurité. Adjointe au maire de Vannes et membre du parti Horizons, elle est engagée sur les enjeux de souveraineté technologique et de sécurité. Elle est élue députée de la 1re circonscription du Morbihan lors des élections législatives de juin 2022 et réélue en 2024.",
  "anne-stambach-terrenoir": "Native d'Amiens, Anne Stambach-Terrenoir a exercé comme professeure de piano et cadre administrative après des études supérieures. Membre de La France insoumise et engagée sur les thématiques de défense de la cause animale et de justice sociale, elle s'est investie dans la vie publique de Haute-Garonne. Elle est élue députée de la 2e circonscription du département en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "anne-valerie-tard": "Native de Paris, Anne-Valérie Tard a exercé la profession de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique de l'Oise. Elle rejoint l'Assemblée nationale en tant que députée de la 4e circonscription du département en octobre 2024.",
  "anne-sophie-frigout": "Native de Reims, Anne-Sophie Frigout exerce la profession de professeure d'histoire-géographie au sein de l'Éducation nationale après des études supérieures. Membre du Rassemblement national et engagée sur les thématiques d'éducation et de défense du patrimoine, elle s'est investie dans la vie publique de la Marne. Elle est élue députée de la 2e circonscription du département en juin 2022.",
  "annick-cousin": "Native de Paris, Annick Cousin a exercé comme cadre administratif et commercial au sein du secteur privé après des études supérieures. Membre du Rassemblement national et engagée dans la vie publique du Lot-et-Garonne, elle s'est investie sur les thématiques de proximité et de défense des services publics ruraux. Elle est élue députée de la 3e circonscription du département en juin 2022.",
  "annie-genevard": "Native d'Audincourt, Annie Genevard exerce la profession de professeure certifiée de lettres après des études supérieures. Maire de Morteau pendant quinze ans et membre du parti Les Républicains, elle a occupé les fonctions de vice-présidente de l'Assemblée nationale. Elle est élue députée de la 5e circonscription du Doubs en juin 2012 et réélue lors de chaque scrutin législatif suivant.",
  "anthony-brosse": "Natif de Vendôme, Anthony Brosse a mené une carrière de cadre administratif au sein du secteur privé avant son engagement public. Adjoint au maire de sa commune d'adoption et membre du parti Renaissance, il s'est investi sur les thématiques de développement économique local. Il est élu député de la 5e circonscription du Loiret lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "antoine-armand": "Natif de Paris et diplômé de l'ENA, Antoine Armand est inspecteur des finances, ayant exercé au sein du ministère de l'Économie après ses études. Membre du parti Renaissance et ministre de l'Économie, des Finances et de l'Industrie, il est spécialisé dans les politiques publiques de transition énergétique. Il est élu député de la 2e circonscription de la Haute-Savoie en juin 2022 et réélu en 2024.",
  "antoine-leaument": "Natif de Châteauroux, Antoine Léaument a exercé comme responsable de la communication numérique et cadre administratif après des études supérieures. Membre de La France insoumise et engagé sur les enjeux institutionnels et de souveraineté populaire, il est une figure du mouvement sur les réseaux sociaux. Il est élu député de la 10e circonscription de l'Essonne en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "antoine-vermorel-marques": "Natif de Roanne, Antoine Vermorel-Marques a exercé comme cadre au sein du secteur public après avoir été collaborateur de cabinet ministériel. Membre du groupe Droite républicaine et engagé sur les thématiques d'écologie de droite et de défense des territoires ruraux, il s'est investi dans la vie publique de la Loire. Il est élu député de la 5e circonscription du département en juin 2022 et réélu en 2024.",
  "arnaud-le-gall": "Natif de Nantes et diplômé en sciences politiques, Arnaud Le Gall a exercé comme chargé de cours universitaire et cadre administratif après une carrière de militant. Membre de La France insoumise et spécialisé dans les questions internationales et de défense, il s'est investi dans la vie publique du Val-d'Oise. Il est élu député de la 9e circonscription du département en juin 2022 et réélu en 2024.",
  "arnaud-petit": "Natif de Paris, Arnaud Petit a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe de la Gauche démocrate et républicaine et engagé sur les enjeux de solidarité et de défense des services publics, il s'est investi dans la vie publique locale. Il est élu député de la 1re circonscription de la Nièvre lors des élections législatives de juillet 2024.",
  "arnaud-saint-martin": "Natif de Paris et docteur en sociologie, Arnaud Saint-Martin est chercheur au CNRS, spécialisé dans la sociologie des sciences et des technologies. Membre de La France insoumise et engagé sur les thématiques de l'enseignement supérieur et de la recherche, il s'est investi dans la vie publique de Seine-et-Marne. Il est élu député de la 1re circonscription du département lors des élections législatives de juillet 2024.",
  "arthur-delaporte": "Natif de Rouen et agrégé d'histoire, Arthur Delaporte a exercé comme enseignant et cadre administratif après ses études à l'ENS de Lyon. Premier secrétaire fédéral du Parti socialiste dans le Calvados, il est engagé sur les thématiques de justice sociale et d'éducation. Il est élu député de la 2e circonscription du département lors des élections législatives de juin 2022 et réélu en 2024.",
  "astrid-panosyan-bouvet": "Native de Paris et diplômée de HEC et de l'ENA, Astrid Panosyan-Bouvet a mené une carrière de cadre dirigeante chez AXA et Unibail-Rodamco-Westfield avant d'être ministre du Travail et de l'Emploi. Membre du parti Renaissance, elle est spécialisée dans les questions de solidarité et de travail. Elle est élue députée de la 4e circonscription de Paris en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "aude-luquet": "Native de Paris, Aude Luquet a exercé comme cadre dans le secteur privé, notamment dans le domaine de la communication et du marketing avant son engagement public. Membre du MoDem et engagée sur les enjeux de transition écologique et de mobilité, elle s'est investie dans la vie publique de Seine-et-Marne. Elle est élue députée de la 1re circonscription du département en juin 2017 et réélue en 2022.",
  "audrey-dufeu": "Native de Saint-Nazaire et diplômée en soins infirmiers, Audrey Dufeu a exercé comme infirmière puis comme cadre dirigeante d'un établissement de santé après des études en gestion. Membre du parti Renaissance et engagée sur les enjeux de santé et de vieillissement, elle est élue députée de la 8e circonscription de Loire-Atlantique en juin 2017 et réélue lors du scrutin législatif de juin 2022.",
  "audrey-linkenheld": "Native de Charleville-Mézières, Audrey Linkenheld a exercé comme cadre au sein de la fonction publique territoriale après des études à Sciences Po et en droit. Adjointe à la maire de Lille et membre du Parti socialiste, elle est spécialisée dans les enjeux de logement et de rénovation urbaine. Elle est élue députée du Nord en juin 2012 et réélue lors des scrutins législatifs de 2022 et 2024.",
  "aurelie-trouve": "Native de Nevers et ingénieure en chef des ponts, des eaux et des forêts, Aurélie Trouvé est enseignante-chercheuse en économie après des études supérieures. Ancienne porte-parole d'Attac France et présidente du parlement de l'Union populaire, elle est membre de La France insoumise. Elle est élue députée de la 9e circonscription de la Seine-Saint-Denis en juin 2022 et réélue en 2024.",
  "aurelien-le-coq": "Natif de Lille, Aurélien Le Coq a exercé comme cadre administratif et commercial au sein du secteur privé après des études supérieures. Membre de La France insoumise et engagé sur les thématiques de jeunesse et de pouvoir d'achat, il est une figure du mouvement dans le Nord. Il est élu député de la 1re circonscription du département lors des élections législatives de juillet 2024, siégeant au sein du groupe LFI.",
  "aurelien-lopez-ligot": "Natif de Nice, Aurélien Lopez-Lligot a exercé comme cadre administratif au sein de la fonction publique d'État après des études supérieures. Membre du Rassemblement national et engagé sur les enjeux de souveraineté nationale et de sécurité, il s'est investi dans la vie publique des Alpes-Maritimes. Il est élu député de la 5e circonscription du département lors des élections législatives de juillet 2024.",
  "aurelien-rousseau": "Natif d'Alès et diplômé de l'ENA, Aurélien Rousseau est un haut fonctionnaire ayant dirigé l'ARS Île-de-France et servi comme directeur de cabinet à Matignon. Ancien ministre de la Santé et de la Prévention et membre du groupe Socialistes et apparentés, il est spécialisé dans les questions sociales. Il est élu député de la 7e circonscription des Yvelines lors des élections législatives de juillet 2024.",
  "aurelien-sainoul": "Natif de Paris, Aurélien Saintoul a exercé la profession de professeur agrégé de lettres modernes au sein de l'Éducation nationale après ses études. Membre de La France insoumise et engagé sur les thématiques de défense et de souveraineté numérique, il s'est investi dans la vie publique des Hauts-de-Seine. Il est élu député de la 11e circonscription du département lors des élections législatives de juin 2022.",
  "aurelien-tache": "Natif de Niort, Aurélien Taché a exercé comme cadre au sein de la fonction publique territoriale après des études en droit public. Membre du groupe Écologiste et Social et spécialisé dans les questions d'intégration et d'asile, il s'est investi dans la vie publique du Val-d'Oise. Il est élu député de la 10e circonscription du département en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "avril-pennacchi": "Native de Marseille, Avril Pennacchi a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de solidarité urbaine, elle s'est investie dans la vie publique des Bouches-du-Rhône. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "aymeric-caron": "Natif de Boulogne-sur-Mer, Aymeric Caron a mené une carrière de journaliste, chroniqueur et auteur, officiant pour plusieurs grands médias nationaux (France Télévisions, Canal+). Fondateur du parti Révolution écologique pour le vivant (REV) et engagé sur les thématiques de défense des animaux et d'écologie radicale, il est élu député de la 18e circonscription de Paris en juin 2022 et réélu en 2024.",
  "balthazar-muller": "Natif de Strasbourg, Balthazar Müller a exercé des fonctions de cadre au sein de la haute administration après des études supérieures en droit public. Membre du groupe Ensemble pour la République et engagé sur les thématiques de gestion publique et de développement local, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député du Bas-Rhin en octobre 2024.",
  "barbara-navarro": "Native de Madrid (Espagne) et diplômée en droit, Barbara Navarro a mené une carrière de cadre dirigeante chez Google et HSBC, spécialisée dans les politiques publiques et l'innovation. Membre du parti Renaissance et engagée sur les enjeux de souveraineté numérique et d'attractivité économique, elle est élue députée des Français établis hors de France en juillet 2024.",
  "barbara-pompili": "Native de Bois-Bernard et diplômée de Sciences Po Lille, Barbara Pompili a exercé comme collaboratrice parlementaire avant de se consacrer à la vie publique. Ancienne ministre de la Transition écologique et membre du parti Renaissance, elle est spécialisée dans les questions environnementales. Elle est élue députée de la 2e circonscription de la Somme en juin 2012 et réélue lors des scrutins de 2017 et 2022.",
  "barthelemy-mani": "Natif de Paris, Barthélemy Mani a exercé des fonctions de cadre au sein de la fonction publique d'État après des études supérieures en gestion. Membre du groupe Ensemble pour la République et engagé sur les thématiques de proximité et de défense des services publics, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de la 3e circonscription des Hauts-de-Seine en octobre 2024.",
  "bastien-lachaud": "Natif de Vitry-sur-Seine et agrégé d'histoire, Bastien Lachaud a exercé comme enseignant dans le secondaire avant de devenir cadre administratif au sein de structures politiques. Membre de La France insoumise et engagé sur les thématiques de défense et de mémoire, il est élu député de la 6e circonscription de la Seine-Saint-Denis lors des élections législatives de juin 2017 et réélu en 2022 et 2024.",
  "bastien-marchive": "Natif de Niort, Bastien Marchive a exercé comme cadre administratif et commercial au sein du secteur privé après des études supérieures. Membre du parti Renaissance et engagé sur les thématiques de développement économique et de proximité, il s'est investi dans la vie publique des Deux-Sèvres. Il est élu député de la 1re circonscription du département en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "beatrice-bellay": "Native de Fort-de-France, Béatrice Bellay a exercé comme cadre administrative au sein de la fonction publique territoriale après des études supérieures. Première secrétaire fédérale du Parti socialiste en Martinique, elle est engagée sur les thématiques de justice sociale et d'égalité réelle dans les outre-mer. Elle est élue députée de la 1re circonscription de l'île lors des élections législatives de juillet 2024.",
  "beatrice-piron": "Native de Paris et ingénieure en électronique, Béatrice Piron a mené une carrière de cadre dirigeante dans le secteur des technologies de l'information, notamment chez Bull et Thales. Membre du parti Renaissance et engagée sur les enjeux d'éducation et de numérique, elle est élue députée de la 3e circonscription des Yvelines lors des élections législatives de juin 2017 et réélue en 2022 et 2024.",
  "beatrice-roullaud": "Native de Melun, Béatrice Roullaud exerce la profession d'avocate au barreau de sa ville natale après des études supérieures en droit. Membre du Rassemblement national et engagée sur les thématiques de justice et de sécurité publique, elle s'est investie dans la vie publique de Seine-et-Marne. Elle est élue députée de la 6e circonscription du département en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "belkhir-belhaddad": "Natif de Beni Ourtilane (Algérie), Belkhir Belhaddad a mené une carrière de cadre dirigeant au sein du secteur privé, notamment dans le domaine du conseil et de la gestion. Membre du parti Renaissance et engagé sur les thématiques d'insertion et de politique de la ville, il s'est investi dans la vie publique de la Moselle. Il est élu député de la 1re circonscription du département en juin 2017 et réélu depuis.",
  "benedicte-auriol": "Native de Paris, Bénédicte Auriol a exercé la profession de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de la 1re circonscription de l'Essonne en octobre 2024.",
  "benedicte-taurine": "Native de Lavelanet, Bénédicte Taurine exerce la profession de professeure de SVT au sein de l'Éducation nationale après des études supérieures. Membre de La France insoumise et engagée sur les thématiques d'agriculture paysanne et de défense de l'environnement, elle s'est investie dans la vie publique de l'Ariège. Elle est élue députée de la 1re circonscription du département en juin 2017 et réélue en 2022.",
  "benjamin-dirx": "Natif de Villeneuve-Saint-Georges, Benjamin Dirx a mené une carrière de cadre au sein du secteur privé, notamment dans le domaine de la distribution d'articles de sport. Membre du parti Renaissance et engagé sur les thématiques économiques et de soutien à l'entreprise, il s'est investi dans la vie publique de Saône-et-Loire. Il est élu député de la 1re circonscription du département en juin 2017 et réélu depuis lors.",
  "benjamin-haddad": "Natif de Paris et diplômé de Sciences Po et de HEC, Benjamin Haddad a mené une carrière de chercheur et cadre dirigeant dans des think tanks internationaux à Washington. Ministre délégué chargé de l'Europe et membre du parti Renaissance, il est spécialisé dans les questions géopolitiques. Il est élu député de la 14e circonscription de Paris en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "benjamin-lucas-lundy": "Natif d'Amiens, Benjamin Lucas-Lundy s'est engagé tôt en politique, présidant le mouvement des Jeunes Socialistes de 2015 à 2018. Conseiller régional des Hauts-de-France à partir de 2021, il quitte le PS pour co-coordonner le mouvement Génération.s. Élu député de la 8e circonscription des Yvelines en 2022 sous l'étiquette NUPES, il est réélu en 2024 sous celle du Nouveau Front populaire.",
  "benjamin-saint-huile": "Natif de Maubeuge, Benjamin Saint-Huile a exercé des fonctions de cadre au sein de la fonction publique territoriale après des études supérieures. Maire de Jeumont pendant quatorze ans et membre du groupe LIOT, il est engagé sur les thématiques d'aménagement du territoire et de solidarité. Il est élu député de la 3e circonscription du Nord lors des élections législatives de juin 2022 et réélu en juillet 2024.",
  "benoit-mournet": "Natif de Tarbes et diplômé de l'ENA, Benoît Mournet est un haut fonctionnaire ayant exercé comme directeur d'hôpital et au sein de l'inspection générale des finances. Membre du parti Renaissance et spécialisé dans les questions de santé publique et de finances locales, il est élu député de la 2e circonscription des Hautes-Pyrénées en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "benoit-payan": "Natif de Marseille, Benoît Payan a exercé comme cadre administratif après avoir été collaborateur de cabinet politique. Maire de Marseille depuis décembre 2020 et membre du Parti socialiste, il est une figure de la gauche unie dans le Sud. Il est élu député des Bouches-du-Rhône lors des élections législatives de juillet 2024, s'investissant particulièrement sur les enjeux urbains et sociaux.",
  "benoit-bordat": "Natif de Dijon, Benoît Bordat a mené une carrière de cadre au sein du secteur privé après avoir exercé comme collaborateur parlementaire. Membre du parti Renaissance et engagé sur les thématiques d'aménagement rural et de défense nationale, il s'est investi dans la vie publique de la Côte-d'Or. Il est élu député de la 2e circonscription du département en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "bernadette-dreux": "Native de Paris, Bernadette Dreux a exercé la profession d'exploitante agricole après des études supérieures dans le domaine agronomique. Maire de sa commune d'adoption et membre du groupe Droite républicaine, elle s'est investie dans la défense des territoires ruraux et du monde paysan. Elle rejoint l'Assemblée nationale en tant que députée de Lot-et-Garonne en octobre 2024.",
  "bernard-chaix": "Natif de Nice, Bernard Chaix a mené une carrière de chef d'entreprise dans le secteur de l'hôtellerie-restauration après des études supérieures. Conseiller départemental des Alpes-Maritimes et membre du groupe Rassemblement national, il s'est investi sur les thématiques de développement économique local. Il est élu député de la 3e circonscription du département lors des élections législatives de juillet 2024.",
  "bernard-perrut": "Natif de Villefranche-sur-Saône, Bernard Perrut exerce la profession d'avocat au barreau de Lyon après des études de droit. Maire de sa ville natale pendant neuf ans et membre du parti Les Républicains, il est engagé sur les enjeux de solidarité et de travail. Il est élu député de la 9e circonscription du Rhône en juin 1997 et réélu lors de chaque scrutin législatif suivant jusqu'en juin 2024.",
  "bertrand-bouyx": "Natif de Paris et diplômé en pharmacie, Bertrand Bouyx a exercé comme pharmacien d'officine avant de se consacrer à la vie publique. Membre du parti Horizons et engagé sur les thématiques de santé et de coopération internationale, il s'est investi dans la vie publique du Calvados. Il est élu député de la 5e circonscription du département lors des élections législatives de juin 2017 et réélu en 2022 et 2024.",
  "bertrand-pancher": "Natif de Saint-Mihiel, Bertrand Pancher a exercé des fonctions de cadre au sein du secteur privé, notamment dans le domaine du conseil et de la gestion. Président du groupe LIOT à l'Assemblée nationale entre 2022 et 2024 et membre du parti Utiles, il est spécialisé dans les enjeux de décentralisation. Il est élu député de la 1re circonscription de la Meuse en juin 2007 et réélu lors des scrutins suivants.",
  "bertrand-petit": "Natif de Saint-Omer, Bertrand Petit a exercé comme cadre au sein de la fonction publique territoriale après des études supérieures. Maire de Saint-Martin-lez-Tatinghem et membre du Parti socialiste, il est engagé sur les thématiques d'aménagement du territoire et de solidarité rurale. Il est élu député de la 8e circonscription du Pas-de-Calais lors d'une élection partielle en 2023 et réélu en juillet 2024.",
  "bill-francois": "Natif de Paris et agrégé de physique, Bill François a mené une carrière de chercheur et d'auteur, spécialisé dans la vulgarisation scientifique et l'écologie marine. Membre du groupe Écologiste et Social et engagé sur les enjeux de protection de la biodiversité, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "blanche-chaussat": "Native de Marseille, Blanche Chaussat a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du Rassemblement national et engagée sur les enjeux de proximité et de défense de la ruralité, elle s'est investie dans la vie publique de la Marne. Elle est élue députée de la 2e circonscription du département lors des élections législatives de juillet 2024.",
  "bodonirina-rakotofiringa": "Native d'Antananarivo (Madagascar), Bodonirina Rakotofiringa a exercé comme cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de solidarité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de l'Essonne en octobre 2024.",
  "boris-vallaud": "Natif de Beyrouth et diplômé de l'ENA, Boris Vallaud est un haut fonctionnaire ayant servi comme secrétaire général adjoint de l'Élysée après avoir été directeur de cabinet ministériel. Président du groupe Socialistes et apparentés, il est spécialisé dans les questions économiques et sociales. Il est élu député de la 3e circonscription des Landes en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "brice-gaillard": "Natif de Paris, Brice Gaillard a exercé comme cadre au sein de la haute administration après des études supérieures en droit public. Membre du Parti socialiste et spécialisé dans les thématiques institutionnelles et de gestion publique, il s'est investi dans la vie publique locale. Il est élu député de la 1re circonscription des Hauts-de-Seine lors des élections législatives de juillet 2024.",
  "brigitte-klinkert": "Native de Colmar, Brigitte Klinkert a mené une carrière de cadre au sein de la fonction publique territoriale après avoir présidé le conseil départemental du Haut-Rhin. Ancienne ministre déléguée chargée de l'Insertion et membre du parti Renaissance, elle est spécialisée dans les enjeux de solidarité. Elle est élue députée de la 1re circonscription du département en juin 2022 et réélue en 2024.",
  "bruno-fuchs": "Natif de Colmar, Bruno Fuchs a mené une carrière de journaliste à TF1 puis de chef d'entreprise dans le secteur de la communication après des études supérieures. Membre du MoDem et engagé sur les enjeux de coopération internationale et de francophonie, il s'est investi dans la vie publique du Haut-Rhin. Il est élu député de la 6e circonscription du département en juin 2017 et réélu en 2022 et 2024.",
  "bruno-le-maire": "Natif de Neuilly-sur-Seine et diplômé de l'ENA et de l'ENS, Bruno Le Maire est un haut fonctionnaire et écrivain ayant servi comme ministre de l'Économie et des Finances pendant sept ans. Membre du parti Renaissance, il est spécialisé dans les politiques publiques de souveraineté économique. Il est élu député de l'Eure en juin 2007 et réélu lors de chaque scrutin législatif suivant jusqu'en 2024.",
  "bruno-millienne": "Natif d'Argenteuil, Bruno Millienne a mené une carrière de journaliste et consultant dans le secteur des médias avant son engagement public. Membre du parti MoDem et spécialisé dans les questions de transport et de transition écologique, il s'est investi dans la vie publique des Yvelines. Il est élu député de la 9e circonscription du département en juin 2017 et réélu lors du scrutin de juin 2022.",
  "bruno-questel": "Natif de Bourg-Achard, Bruno Questel exerce la profession d'avocat au barreau de Rouen après des études de droit. Maire de sa commune natale pendant treize ans et membre du parti Renaissance, il est engagé sur les enjeux de décentralisation et de territoires. Il est élu député de la 4e circonscription de l'Eure en juin 2017 et réélu lors du scrutin législatif de juin 2022.",
  "carine-leclair": "Native de Nantes, Carine Leclair a exercé comme cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Droite républicaine et engagée sur les enjeux de proximité et de défense de la ruralité, elle s'est investie dans la vie publique de Maine-et-Loire. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "carl-lang": "Natif de Boulogne-sur-Mer, Carl Lang a exercé la profession de cadre au sein du secteur privé après une carrière de permanent politique. Ancien député européen et membre du Rassemblement national, il s'est investi sur les thématiques de souveraineté nationale et de sécurité publique. Il est élu député de la 3e circonscription de l'Eure lors des élections législatives de juillet 2024.",
  "carlos-martens-bilongo": "Natif de Paris, Carlos Martens Bilongo a exercé comme entrepreneur dans le secteur du bâtiment et formateur après avoir été consultant en insertion. Membre de La France insoumise et engagé sur les enjeux de politique de la ville et de lutte contre les inégalités territoriales, il est élu député de la 8e circonscription du Val-d'Oise en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "carole-delga": "Native de Toulouse, Carole Delga a exercé comme cadre supérieure au sein de la fonction publique territoriale après avoir servi comme secrétaire d'État. Présidente de la région Occitanie depuis 2016 et membre du Parti socialiste, elle est une figure de la gauche régionale. Elle est élue députée de la Haute-Garonne en juin 2012 et réélue lors du scrutin législatif de juillet 2024.",
  "caroline-abadie": "Native de Saint-Martin-d'Hères, Caroline Abadie a mené une carrière de cheffe d'entreprise dans le secteur du conseil après des études supérieures en gestion. Membre du parti Renaissance et engagée sur les enjeux de justice et de réinsertion, elle s'est investie dans la vie publique de l'Isère. Elle est élue députée de la 8e circonscription du département en juin 2017 et réélue lors du scrutin de 2022.",
  "caroline-colombier": "Native de Pau, Caroline Colombier exerce la profession d'avocate après des études supérieures en droit public. Membre du Rassemblement national et engagée dans la vie publique de la Charente, elle s'est investie sur les thématiques de proximité et de défense des services publics ruraux. Elle est élue députée de la 3e circonscription du département en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "caroline-fiat": "Native de Verdun, Caroline Fiat exerce la profession d'aide-soignante au sein d'un EHPAD après une carrière dans le secteur médico-social. Membre de La France insoumise et ancienne vice-présidente de l'Assemblée nationale, elle est engagée sur les enjeux de santé et de grand âge. Elle est élue députée de la 6e circonscription de Meurthe-et-Moselle en juin 2017 et réélue lors du scrutin de 2022.",
  "caroline-janvier": "Native de Châteaudun, Caroline Janvier a mené une carrière de cadre au sein du secteur médico-social après des études à Sciences Po et en gestion. Membre du parti Renaissance et spécialisée dans les questions de santé publique et de lutte contre les addictions, elle est élue députée de la 2e circonscription du Loiret en juin 2017 et réélue lors du scrutin de juin 2022.",
  "caroline-parmentier": "Native d'Antibes, Caroline Parmentier a mené une carrière de journaliste, officiant pour plusieurs titres de la presse nationale avant de devenir conseillère en communication. Membre du Rassemblement national et conseillère régionale d'Île-de-France, elle s'est investie sur les thématiques de culture et de médias. Elle est élue députée de la 9e circonscription du Pas-de-Calais lors des élections législatives de juin 2022.",
  "caroline-yadan": "Native de Paris, Caroline Yadan exerce la profession d'avocate au barreau de sa ville natale, spécialisée dans la défense des droits fondamentaux. Membre du parti Renaissance et engagée sur les enjeux de lutte contre l'antisémitisme et le racisme, elle est élue députée des Français établis hors de France (8e circonscription) lors d'une élection partielle en 2023 et réélue en juillet 2024.",
  "cassandra-maitre": "Native de Paris, Cassandra Maître a exercé la profession de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de Seine-et-Marne en octobre 2024.",
  "catherine-couturier": "Native de Guéret, Catherine Couturier a exercé comme cadre au sein de la fonction publique territoriale après une carrière de militante associative. Membre de La France insoumise et engagée sur les enjeux de défense des services publics et de ruralité, elle s'est investie dans la vie publique de la Creuse. Elle est élue députée de la circonscription unique du département lors des élections législatives de juin 2022.",
  "catherine-fabre": "Native de Bordeaux et maître de conférences à l'université, Catherine Fabre est spécialisée dans les enjeux de gestion et de formation professionnelle après ses études. Membre du parti Renaissance et engagée sur les questions de travail et d'emploi, elle est élue députée de la 2e circonscription de la Gironde en juin 2017 et réélue lors du scrutin législatif de juin 2022.",
  "catherine-herpin": "Native de Paris, Catherine Herpin a exercé la profession de cadre au sein de la fonction publique territoriale après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique de Seine-Maritime. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "catherine-jaouen": "Native de Paris, Catherine Jaouen exerce la profession d'avocate au barreau de sa ville natale après des études supérieures en droit. Membre du Rassemblement national et engagée sur les thématiques de justice et de sécurité publique, elle s'est investie dans la vie publique du Vaucluse. Elle rejoint l'Assemblée nationale en tant que députée de la 1re circonscription du département en juin 2024.",
  "catherine-o-brien": "Native de Dublin (Irlande), Catherine O'Brien a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Écologiste et Social et engagée sur les enjeux de solidarité et de transition écologique, elle s'est investie dans la vie publique de l'Essonne. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "catherine-vautrin": "Native de Reims, Catherine Vautrin a exercé comme cadre au sein du secteur privé avant d'occuper plusieurs fonctions ministérielles et de présider le Grand Reims. Ancienne ministre du Partenariat avec les territoires et de la Décentralisation, elle est membre du parti Horizons. Elle est élue députée de la Marne en juin 2002 et retrouve un rôle national majeur au sein du gouvernement en 2024.",
  "cecile-bajolet": "Native de Nancy, Cécile Bajolet a exercé comme cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique de Meurthe-et-Moselle. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "cecile-untermaier": "Native de Belley et diplômée de l'ENA, Cécile Untermaier est une magistrate administrative ayant servi au sein de la fonction publique après ses études. Membre du Parti socialiste et spécialisée dans les enjeux institutionnels et de transparence publique, elle s'est investie dans la vie publique de Saône-et-Loire. Elle est élue députée de la 4e circonscription du département en juin 2012 et réélue depuis lors.",
  "cedric-rousset": "Natif de Lyon, Cédric Rousset a exercé comme cadre au sein du secteur privé après des études supérieures en gestion. Membre du groupe Ensemble pour la République et engagé sur les thématiques de développement économique local et de proximité, il s'est investi dans la vie publique du Rhône. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "cedric-vial": "Natif de Chambéry, Cédric Vial a exercé des fonctions de cadre au sein de la fonction publique territoriale après des études supérieures. Maire des Échelles pendant quatorze ans et membre du groupe Droite républicaine, il est engagé sur les thématiques d'aménagement du territoire et de ruralité. Il est élu député de la 3e circonscription de la Savoie lors des élections législatives de juillet 2024.",
  "celine-calvez": "Native de Rennes, Céline Calvez a mené une carrière de cheffe d'entreprise dans le secteur de la communication et du conseil après des études à Sciences Po et en droit. Membre du parti Renaissance et spécialisée dans les enjeux d'égalité entre les femmes et les hommes, elle est élue députée de la 5e circonscription des Hauts-de-Seine en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "celine-villecourt": "Native de Paris, Céline Villecourt a exercé comme cadre administratif au sein de la fonction publique territoriale après des études supérieures. Adjointe au maire de sa commune d'adoption et membre du groupe Ensemble pour la République, elle s'est investie dans les politiques de proximité et de solidarité urbaine. Elle rejoint l'Assemblée nationale en tant que députée du Val-d'Oise en octobre 2024.",
  "charles-de-courson": "Natif de Paris et diplômé de l'ENA et de l'ESSEC, Charles de Courson est un magistrat à la Cour des comptes, issu d'une lignée de parlementaires. Membre du parti Les Centristes et doyen de l'Assemblée nationale, il est spécialisé dans les questions budgétaires et les finances publiques. Il est élu député de la 5e circonscription de la Marne sans interruption depuis 1993.",
  "charles-rodwell": "Natif de Londres (Royaume-Uni), Charles Rodwell a exercé comme collaborateur parlementaire et de cabinet ministériel après des études en sciences politiques. Membre du parti Renaissance et engagé sur les thématiques d'attractivité économique et d'industrie, il s'est investi dans la vie publique des Yvelines. Il est élu député de la 1re circonscription du département en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "charles-sitzenstuhl": "Natif de Strasbourg et diplômé de Sciences Po, Charles Sitzenstuhl a exercé comme conseiller politique et de cabinet ministériel après ses études supérieures. Membre du parti Renaissance et engagé sur les enjeux européens et économiques, il s'est investi dans la vie publique du Bas-Rhin. Il est élu député de la 5e circonscription du département en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "charlotte-lecocq": "Native de Valenciennes, Charlotte Lecocq a mené une carrière d'avocate au barreau de sa ville natale avant son engagement public. Membre du parti Renaissance et spécialisée dans les enjeux de santé au travail et de protection sociale, elle est élue députée de la 6e circonscription du Nord en juin 2017 et réélue lors du scrutin législatif de juin 2022.",
  "charlotte-leduc": "Native de Senlis et docteure en archéozoologie, Charlotte Leduc est chercheuse et ingénieure de recherche après des études supérieures scientifiques. Membre de La France insoumise et engagée sur les thématiques de justice fiscale et de transition écologique, elle s'est investie dans la vie publique de la Moselle. Elle est élue députée de la 3e circonscription du département lors des élections législatives de juin 2022.",
  "charlotte-parmentier-lecocq": "Native de Valenciennes, Charlotte Parmentier-Lecocq a mené une carrière de consultante RH et de cheffe d'entreprise avant de devenir ministre déléguée chargée des Personnes handicapées. Membre du parti Renaissance, elle est spécialisée dans les questions de santé au travail. Elle est élue députée de la 6e circonscription du Nord en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "chloe-rigaud": "Native de Nîmes, Chloé Rigaud a exercé la profession de cadre au sein de la fonction publique territoriale après des études supérieures. Membre du groupe Écologiste et Social et engagée sur les enjeux de transition écologique et de solidarité urbaine, elle s'est investie dans la vie publique du Gard. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "christian-baptiste": "Natif de Pointe-à-Pitre, Christian Baptiste a exercé comme cadre administratif au sein de la fonction publique territoriale après des études supérieures. Maire de Sainte-Anne pendant plusieurs années et membre du groupe Socialistes et apparentés, il est engagé sur les thématiques de développement local et d'égalité réelle. Il est élu député de la 2e circonscription de la Guadeloupe lors des législatives de juin 2022.",
  "christine-engrand": "Native de Paris, Christine Engrand a mené une carrière de cadre commerciale et administrative au sein du secteur privé après des études supérieures. Membre du Rassemblement national et conseillère régionale des Hauts-de-France, elle s'est investie sur les thématiques de proximité et de défense des services publics ruraux. Elle est élue députée de la 6e circonscription du Pas-de-Calais lors des législatives de juin 2022.",
  "christine-le-nabour": "Native de Rennes, Christine Le Nabour a exercé comme cadre au sein de la fonction publique d'État après une carrière de cadre dans le secteur privé. Membre du parti Renaissance et engagée sur les thématiques d'insertion et de politiques sociales, elle s'est investie dans la vie publique d'Ille-et-Vilaine. Elle est élue députée de la 5e circonscription du département en juin 2017 et réélue en 2022 et 2024.",
  "christine-pirès-beaune": "Native de Saint-Avit, Christine Pirès Beaune a exercé comme cadre au sein de la fonction publique territoriale après des études supérieures. Membre du Parti socialiste et spécialisée dans les questions de fiscalité locale et de finances publiques, elle s'est investie dans la vie publique du Puy-de-Dôme. Elle est élue députée de la 2e circonscription du département en juin 2012 et réélue depuis lors.",
  "christine-lordon": "Native de Paris, Christine Lordon a exercé la profession de cadre au sein de la fonction publique territoriale après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique de Seine-et-Marne. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "christophe-barthes": "Natif de Carcassonne, Christophe Barthès exerce la profession d'agriculteur viticulteur au sein de l'exploitation familiale dans l'Aude. Membre du Rassemblement national et engagé dans la vie publique locale, il s'est investi sur les thématiques de défense de la ruralité et du monde paysan. Il est élu député de la 1re circonscription du département en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "christophe-bechu": "Natif d'Angers et diplômé de Sciences Po Paris, Christophe Béchu a mené une carrière de consultant avant d'être maire d'Angers et ministre de la Transition écologique. Président du parti Horizons et spécialisé dans les enjeux d'aménagement du territoire, il est une figure majeure de la majorité. Il est élu sénateur du Maine-et-Loire en 2011 et retrouve un rôle de député lors des élections de juillet 2024.",
  "christophe-bentz": "Natif de Paris, Christophe Bentz a exercé la profession de cadre administratif et de consultant après des études supérieures en sciences politiques. Membre du Rassemblement national et engagé sur les thématiques de souveraineté et de protection des libertés locales, il s'est investi dans la vie publique de la Haute-Marne. Il est élu député de la 1re circonscription du département lors des élections législatives de juin 2022.",
  "christophe-bex": "Natif de Montauban, Christophe Bex a exercé comme attaché d'administration à l'université Jean-Jaurès de Toulouse après une carrière de seize ans au sein des PTT. Membre de La France insoumise et engagé sur les thématiques de services publics et de justice sociale, il s'est investi dans la vie publique de Haute-Garonne. Il est élu député de la 7e circonscription du département en juin 2022 et siège jusqu'en 2024.",
  "christophe-blanchet": "Natif de Caen, Christophe Blanchet a mené une carrière de chef d'entreprise dans le secteur de l'hôtellerie-restauration et de l'événementiel avant son engagement public. Membre du parti Renaissance et spécialisé dans les thématiques de sécurité et de défense, il s'est investi dans la vie publique du Calvados. Il est élu député de la 4e circonscription du département en juin 2017 et réélu en 2022 et 2024.",
  "christophe-dicorso": "Natif de Marseille, Christophe Di Corso a exercé des fonctions de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les thématiques de gestion publique et de proximité, il s'est investi dans la vie publique des Bouches-du-Rhône. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "christophe-marion": "Natif de Vendôme et diplômé en histoire, Christophe Marion a exercé comme enseignant-chercheur et cadre au sein de la fonction publique d'État. Maire de Saint-Ouen pendant plusieurs années et membre du parti Renaissance, il est engagé sur les enjeux d'éducation et de patrimoine. Il est élu député de la 3e circonscription du Loir-et-Cher lors des élections législatives de juin 2022 et réélu en juillet 2024.",
  "christophe-naegelen": "Natif de Remiremont, Christophe Naegelen a mené une carrière de chef d'entreprise dans le secteur du textile et de l'export après des études supérieures. Membre du groupe LIOT et engagé sur les thématiques économiques et de défense des services publics ruraux, il s'est investi dans la vie publique des Vosges. Il est élu député de la 3e circonscription du département en juin 2017 et réélu en 2022 et 2024.",
  "christophe-plassard": "Natif de Paris, Christophe Plassard a mené une carrière de chef d'entreprise dans le secteur de la communication après des études supérieures. Membre du parti Horizons et engagé sur les enjeux de souveraineté économique et de développement local, il s'est investi dans la vie publique de Charente-Maritime. Il est élu député de la 5e circonscription du département lors des élections législatives de juin 2022 et réélu en 2024.",
  "christophe-prevost": "Natif de Paris, Christophe Prévost a exercé comme cadre administratif au sein de la fonction publique territoriale après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique de l'Oise. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "christophe-proenca": "Natif de Souillac, Christophe Proença a exercé la profession de cadre au sein de la fonction publique territoriale après des études supérieures. Maire de Gintrac et conseiller départemental du Lot, il est membre du Parti socialiste engagé sur les enjeux de ruralité et de proximité. Il est élu député de la 2e circonscription du département lors des élections législatives de juillet 2024.",
  "claire-guichard": "Native de Nantes, Claire Guichard a exercé des fonctions de cadre au sein du secteur privé après avoir été collaboratrice parlementaire. Membre du parti Renaissance et engagée sur les thématiques d'éducation et de solidarité, elle s'est investie dans la vie publique des Hauts-de-Seine. Elle est élue députée de la 10e circonscription du département en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "claire-javois": "Native de Saint-Barthélemy, Claire Javois a mené une carrière de cadre administratif au sein du secteur privé avant son engagement politique. Membre du groupe Droite républicaine et engagée dans la défense des territoires insulaires, elle s'est investie dans la vie publique de Saint-Martin et Saint-Barthélemy. Elle est élue députée de la circonscription des Îles du Nord en juin 2017.",
  "claire-le-jeune": "Native de Paris et diplômée de l'ENS, Claire Lejeune a exercé comme chercheuse et cadre associative spécialisée dans les questions écologiques après ses études. Membre de La France insoumise et engagée sur les thématiques de planification écologique et de justice sociale, elle s'est investie dans la vie publique de l'Essonne. Elle est élue députée de la 7e circonscription du département lors des législatives de juillet 2024.",
  "claire-marais-beuil": "Native de Melun, Claire Marais-Beuil a exercé la profession de cadre au sein du secteur médico-social après des études supérieures. Membre du Rassemblement national et engagée sur les enjeux de proximité et de défense des services publics ruraux, elle s'est investie dans la vie publique de l'Oise. Elle est élue députée de la 4e circonscription du département lors des élections législatives de juillet 2024.",
  "claire-pitollat": "Native de Marseille et docteure en robotique, Claire Pitollat a mené une carrière d'ingénieure et de cheffe de projet dans le secteur industriel avant son engagement public. Membre du parti Renaissance et engagée sur les thématiques de santé environnementale et d'innovation, elle est élue députée de la 2e circonscription des Bouches-du-Rhône en juin 2017 et réélue lors du scrutin de juin 2022.",
  "claude-malhuret": "Natif de Strasbourg et docteur en médecine, Claude Malhuret est un avocat et ancien ministre ayant présidé l'organisation Médecins sans frontières. Maire de Vichy pendant vingt-deux ans et sénateur de l'Allier, il préside le groupe Les Indépendants au Sénat et est une figure du parti Horizons. Il rejoint l'Assemblée nationale en tant que député lors des élections législatives de juillet 2024.",
  "clemence-guette": "Native de Niort et diplômée de Sciences Po Paris, Clémence Guetté a exercé comme cadre administrative et responsable des programmes au sein de La France insoumise. Vice-présidente de l'Assemblée nationale et spécialiste de la planification écologique, elle est une figure majeure de son mouvement. Elle est élue députée de la 2e circonscription du Val-de-Marne en juin 2022 et réélue au premier tour en 2024.",
  "clement-beaune": "Natif de Paris et diplômé de l'ENA, Clément Beaune est un haut fonctionnaire ayant servi comme conseiller spécial à l'Élysée puis ministre chargé de l'Europe et des Transports. Membre du parti Renaissance, il est spécialisé dans les enjeux européens et de mobilité. Il est élu député de la 7e circonscription de Paris lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "clovis-cassand": "Natif de Paris, Clovis Cassand a exercé des fonctions de cadre au sein de la fonction publique d'État après des études supérieures en droit. Membre du groupe Ensemble pour la République et engagé sur les thématiques de gestion publique et de proximité, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de la 4e circonscription des Yvelines en octobre 2024.",
  "colette-capdevielle": "Native d'Orthez, Colette Capdevielle exerce la profession d'avocate au barreau de Bayonne, spécialisée dans la défense des droits sociaux. Adjointe au maire de Bayonne et membre du Parti socialiste, elle est engagée sur les thématiques de justice et de territoires. Elle est élue députée de la 5e circonscription des Pyrénées-Atlantiques en juin 2012 et retrouve son siège à l'Assemblée en juillet 2024.",
  "constance-de-pereyre": "Native de Paris, Constance de Pereyre a exercé comme cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de la 4e circonscription de Paris en octobre 2024.",
  "constantin-androulakis": "Natif d'Athènes (Grèce), Constantin Androulakis a exercé des fonctions de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les thématiques de gestion publique et de proximité, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de l'Essonne en octobre 2024.",
  "corentin-le-fur": "Natif de Paris, Corentin Le Fur a exercé la profession de cadre administratif après des études supérieures en gestion et en droit. Membre du groupe Droite républicaine et engagé sur les enjeux de défense de la ruralité et des libertés locales, il s'est investi dans la vie publique des Côtes-d'Armor. Il est élu député de la 3e circonscription du département lors des élections législatives de juillet 2024.",
  "cyrille-isaac-sibille": "Natif de Lyon, Cyrille Isaac-Sibille exerce la profession de médecin ORL, ayant pratiqué au sein de la clinique Charcot et des Hôpitaux de Lyon. Membre du parti MoDem et conseiller municipal de Sainte-Foy-lès-Lyon depuis 1995, il est spécialisé dans les enjeux de santé publique et de prévention. Il est élu député de la 12e circonscription du Rhône lors des élections législatives de juin 2017 et réélu depuis.",
  "daniela-fastiere": "Native de Paris, Daniela Fastière a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée du Loiret en octobre 2024.",
  "danielle-simonnet": "Native de Montereau-Fault-Yonne, Danielle Simonnet a exercé la profession de conseillère d'orientation-psychologue au sein de l'Éducation nationale après des études supérieures. Conseillère de Paris depuis 2008 et engagée sur les thématiques de logement social et de services publics, elle est une figure de la gauche radicale. Elle est élue députée de la 15e circonscription de Paris en juin 2022 et réélue en 2024.",
  "dany-waserman": "Natif de Paris, Dany Waserman a mené une carrière de cadre dirigeant dans le secteur privé après des études supérieures en gestion. Membre du groupe Ensemble pour la République et engagé sur les enjeux de développement économique local et de proximité, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député du Bas-Rhin en octobre 2024.",
  "david-amiel": "Natif de Paris et diplômé de l'ENS et de l'ENA, David Amiel est un haut fonctionnaire ayant servi comme conseiller spécial à l'Élysée après ses études. Membre du parti Renaissance et spécialisé dans les politiques publiques de lutte contre les inégalités et de travail, il est élu député de la 13e circonscription de Paris en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "david-guiraud": "Natif de Paris, David Guiraud a exercé comme cadre administratif et responsable de la communication politique au sein de La France insoumise après des études supérieures. Membre du groupe LFI et engagé sur les thématiques de justice fiscale et de souveraineté populaire, il est une figure médiatique du mouvement. Il est élu député de la 8e circonscription du Nord en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "david-habib": "Natif de Paris, David Habib a exercé des fonctions de cadre au sein du secteur privé, notamment dans le domaine du conseil et de la gestion. Maire de Mourenx pendant douze ans et membre du groupe LIOT, il est spécialisé dans les questions de défense et de souveraineté énergétique. Il est élu député de la 3e circonscription des Pyrénées-Atlantiques sans interruption depuis juin 2002.",
  "david-taupiac": "Natif de Condom, David Taupiac a mené une carrière d'ingénieur au sein du secteur aéronautique après des études supérieures. Maire de Saint-Clar et conseiller régional d'Occitanie, il est membre du groupe LIOT engagé sur les enjeux de ruralité et de soutien aux filières agricoles et industrielles. Il est élu député de la 2e circonscription du Gers lors des élections législatives de juin 2022 et réélu en 2024.",
  "david-valence": "Natif de Épinal et agrégé d'histoire, David Valence a exercé comme enseignant et cadre au sein de la fonction publique territoriale après ses études à l'ENS. Maire de Saint-Dié-des-Vosges pendant huit ans et membre du parti Renaissance, il est spécialisé dans les questions de transport et de mobilité. Il est élu député de la 2e circonscription des Vosges lors des élections législatives de juin 2022.",
  "davy-rimane": "Natif de Kourou, Davy Rimane a exercé comme technicien au sein de l'entreprise EDF en Guyane après avoir mené un engagement syndical de premier plan. Président de la délégation aux outre-mer de l'Assemblée nationale et membre de la Gauche démocrate et républicaine, il porte les enjeux de souveraineté territoriale. Il est élu député de la 2e circonscription de Guyane lors des élections législatives de juin 2022.",
  "delphine-batho": "Native de Paris, Delphine Batho a exercé des fonctions de cadre au sein de la fonction publique territoriale après une carrière de militante associative. Ancienne ministre de l'Écologie et présidente du parti Génération Écologie, elle est spécialisée dans les questions de protection de l'environnement et de santé. Elle est élue députée des Deux-Sèvres en juin 2007 et réélue lors de chaque scrutin législatif suivant.",
  "delphine-lingemann": "Native de Clermont-Ferrand et docteure en sciences, Delphine Lingemann a mené une carrière d'enseignante-chercheuse et de cheffe d'entreprise dans le secteur technologique. Membre du parti MoDem et engagée sur les thématiques d'éducation et d'innovation, elle s'est investie dans la vie publique du Puy-de-Dôme. Elle est élue députée de la 4e circonscription du département en juin 2022 et réélue en juillet 2024.",
  "dieynaba-diop": "Native de Mantes-la-Jolie, Dieynaba Diop exerce la profession de professeure de lettres et d'histoire au sein de l'Éducation nationale après des études supérieures. Adjointe à la maire des Mureaux et conseillère régionale d'Île-de-France, elle est membre du Parti socialiste engagée sur les enjeux d'éducation et de citoyenneté. Elle est élue députée de la 9e circonscription des Yvelines lors des législatives de juillet 2024.",
  "dominique-da-silva": "Natif de Lisbonne (Portugal), Dominique Da Silva a mené une carrière de chef d'entreprise dans le secteur du conseil et de la formation après des études supérieures. Membre du parti Renaissance et spécialisé dans les enjeux de travail et de protection sociale, il s'est investi dans la vie publique du Val-d'Oise. Il est élu député de la 7e circonscription du département en juin 2017 et réélu en 2022.",
  "dominique-faure": "Native de Carcassonne et diplômée de HEC et de l'École Polytechnique, Dominique Faure a mené une carrière de cadre dirigeante chez Veolia et SFR avant d'être ministre déléguée aux Collectivités territoriales. Membre du parti Renaissance et ancienne maire de Saint-Orens-de-Gameville, elle est spécialisée dans les enjeux ruraux. Elle est élue députée de la Haute-Garonne en juin 2022.",
  "dominique-morfouace": "Native de Paris, Dominique Morfouace a exercé la profession de cadre au sein de la fonction publique territoriale après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique des Côtes-d'Armor. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "dominique-potier": "Natif de Toul, Dominique Potier exerce la profession d'agriculteur au sein d'une exploitation en GAEC après des études supérieures. Membre du Parti socialiste et spécialisé dans les questions de foncier agricole et de régulation mondiale, il s'est investi dans la vie publique de Meurthe-et-Moselle. Il est élu député de la 5e circonscription du département sans interruption depuis juin 2012.",
  "dominique-voynet": "Native de Montbéliard et docteur en médecine, Dominique Voynet est une figure historique de l'écologie, ayant servi comme ministre de l'Aménagement du territoire et sénatrice. Ancienne maire de Montreuil et membre du parti Les Écologistes, elle est spécialisée dans les politiques de santé environnementale. Elle est élue députée de la Haute-Savoie en juin 2024, siégeant au sein du groupe Écologiste et Social.",
  "edouard-benard": "Natif de Dieppe, Édouard Bénard a exercé comme cadre administratif au sein de la fonction publique territoriale après des études supérieures. Membre du groupe de la Gauche démocrate et républicaine et engagé sur les thématiques de solidarité et de défense des services publics, il s'est investi dans la vie publique locale. Il est élu député de la 3e circonscription de la Seine-Maritime lors des élections législatives de juillet 2024.",
  "edouard-philippe": "Natif de Rouen et diplômé de l'ENA et de Sciences Po Paris, Édouard Philippe est un haut fonctionnaire et avocat ayant servi comme Premier ministre entre 2017 et 2020. Maire du Havre et président du parti Horizons, il est une figure centrale de la vie politique nationale. Il est élu député de la Seine-Maritime en juin 2012 et retrouve son siège au Palais Bourbon lors des élections législatives de juillet 2024.",
  "eleonore-revel": "Native de Paris, Éléonore Revel a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Rassemblement national et engagée sur les enjeux de proximité et de souveraineté nationale, elle s'est investie dans la vie publique de Loire-Atlantique. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "elisabeth-borne": "Native de Paris et diplômée de l'École Polytechnique et de l'ENA, Élisabeth Borne est une haute fonctionnaire et dirigeante d'entreprise ayant servi comme Première ministre entre 2022 et 2024. Membre du parti Renaissance et ancienne ministre des Transports et du Travail, elle est spécialisée dans les politiques sociales. Elle est élue députée du Calvados en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "elisabeth-de-maistre": "Native de Paris, Élisabeth de Maistre a exercé comme cadre au sein de la fonction publique territoriale après des études supérieures. Adjointe au maire de sa commune d'adoption et membre du groupe Ensemble pour la République, elle s'est investie dans les politiques de proximité et de solidarité. Elle rejoint l'Assemblée nationale en tant que députée de la 10e circonscription des Yvelines en octobre 2024.",
  "elise-leboucher": "Native d'Alençon, Élise Leboucher exerce la profession d'éducatrice spécialisée au sein du secteur médico-social après des études supérieures. Membre de La France insoumise et engagée sur les thématiques de protection de l'enfance et de santé mentale, elle s'est investie dans la vie publique de la Sarthe. Elle est élue députée de la 4e circonscription du département lors des élections législatives de juin 2022 et réélue en 2024.",
  "elsa-faucillon": "Native d'Amiens, Elsa Faucillon a exercé la profession de médiatrice culturelle après des études supérieures en communication. Membre du Parti communiste français et conseillère départementale des Hauts-de-Seine, elle est engagée sur les enjeux de justice sociale et de défense des droits fondamentaux. Elle est élue députée de la 1re circonscription du département en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "elysabeth-robitaille": "Native de Paris, Élysabeth Robitaille a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de Seine-et-Marne en octobre 2024.",
  "emeline-k-bidi": "Native de Saint-Denis de La Réunion, Émeline K/Bidi exerce la profession d'avocate au barreau de Saint-Pierre après des études de droit. Adjointe au maire de Saint-Joseph et membre du parti Le Progrès, elle est engagée sur les thématiques de justice sociale et de défense des territoires ultramarins. Elle est élue députée de la 4e circonscription de l'île lors des élections législatives de juin 2022 et réélue en 2024.",
  "emeric-salmon": "Natif de Rennes, Emeric Salmon exerce la profession d'ingénieur après des études scientifiques supérieures. Conseiller régional de Bretagne et membre du Rassemblement national, il s'est investi sur les thématiques d'aménagement du territoire et de sécurité. Il est élu député de la 2e circonscription de la Haute-Saône lors des élections législatives de juin 2022 et réélu au premier tour lors du scrutin de juin 2024.",
  "emilie-bonnivard": "Native de Chambéry, Émilie Bonnivard a exercé comme cadre au sein de la fonction publique territoriale après des études à Sciences Po et à l'ESSEC. Membre de la Droite républicaine et engagée sur les enjeux de montagne et de développement économique local, elle s'est investie dans la vie publique de la Savoie. Elle est élue députée de la 3e circonscription du département en juin 2017 et réélue depuis lors.",
  "emilie-chandler": "Native de Paris, Émilie Chandler exerce la profession d'avocate au barreau de Pontoise après des études supérieures en droit. Membre du parti Renaissance et engagée sur les thématiques de justice et de lutte contre les violences intrafamiliales, elle s'est investie dans la vie publique du Val-d'Oise. Elle est élue députée de la 1re circonscription du département en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "emmanuel-duplessy": "Natif de Paris, Emmanuel Duplessy a exercé comme cadre administratif au sein du secteur public après des études supérieures. Membre de l'Union des gauches et des écologistes et engagé dans la vie publique du Loiret, il s'est investi sur les thématiques de transition écologique et de solidarité territoriale. Il est élu député de la 2e circonscription du département lors des élections législatives de juillet 2024.",
  "emmanuel-fernandes": "Natif de Creil, Emmanuel Fernandes a exercé comme cadre au sein de la fonction publique après avoir mené des études supérieures. Membre de La France insoumise et engagé sur les thématiques de protection de l'environnement et de services publics, il s'est investi dans la vie publique du Bas-Rhin. Il est élu député de la 2e circonscription du département lors des élections législatives de juin 2022 et réélu en 2024.",
  "emmanuel-fouquart": "Natif de Maubeuge, Emmanuel Fouquart a effectué une carrière de militaire dans la Marine nationale puis de gendarme avant de devenir agent immobilier. Gérant de société dans le courtage et membre du Rassemblement national, il s'est investi dans la vie publique du Nord. Il est élu député de la 13e circonscription du département lors des élections législatives de juillet 2024.",
  "emmanuel-gregoire": "Natif de Cholet, Emmanuel Grégoire a mené une carrière de consultant, notamment dans le secteur médical, après des études en sciences politiques. Premier adjoint à la maire de Paris pendant six ans et membre du Parti socialiste, il est devenu maire de la capitale en mars 2026. Il est élu député de la 7e circonscription de Paris lors des élections législatives de juillet 2024.",
  "emmanuelle-anthoine": "Native de Valence, Emmanuelle Anthoine exerce la profession d'avocate après des études supérieures en droit. Adjointe au maire de sa commune natale et membre du parti Les Républicains, elle est engagée sur les enjeux d'éducation et de proximité territoriale. Elle est élue députée de la 4e circonscription de la Drôme en juin 2017 et réélue lors des scrutins législatifs de 2022 et 2024.",
  "emmanuelle-menard": "Native de Lille, Emmanuelle Ménard exerce la profession de journaliste et a dirigé le site d'information Boulevard Voltaire après ses études supérieures. Engagée à droite sur les enjeux de souveraineté et de valeurs identitaires, elle s'est investie dans la vie publique de l'Hérault. Elle est élue députée de la 6e circonscription du département en juin 2017 et réélue lors du scrutin de 2022.",
  "emmanuelle-mignon": "Native de Paris et major de l'ENA, Emmanuelle Mignon est une haute fonctionnaire ayant servi comme directrice de cabinet à l'Élysée après avoir été maîtresse des requêtes au Conseil d'État. Membre du groupe Droite républicaine et spécialisée dans les questions institutionnelles et sociales, elle est élue députée des Hauts-de-Seine lors des élections législatives de juillet 2024.",
  "enric-vicente": "Natif de Marseille, Enric Vicente a exercé des fonctions de cadre au sein de la fonction publique territoriale après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les thématiques de proximité et de développement local, il s'est investi dans la vie publique des Bouches-du-Rhône. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "enzo-ismail": "Natif de Lyon, Enzo Ismaïl a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les thématiques de proximité et de solidarité urbaine, il s'est investi dans la vie publique du Rhône. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "eric-alauzet": "Natif de Nancy, Éric Alauzet exerce la profession de médecin généraliste après ses études de médecine. Adjoint au maire de Besançon et membre du parti Renaissance, il est spécialisé dans les questions de santé environnementale et de transition écologique. Il est élu député du Doubs en juin 2012 et réélu lors des scrutins législatifs de 2017 et 2022.",
  "eric-bothorel": "Natif de Paimpol, Éric Bothorel a mené une carrière de plus de vingt ans comme cadre dirigeant dans le secteur privé, notamment chez General Electric et Infopoint. Réserviste de la cyberdéfense, il s'est spécialisé sur les enjeux du numérique. Il est élu député de la 5e circonscription des Côtes-d'Armor en 2017 sous l'étiquette LREM et réélu en 2022 et 2024.",
  "eric-ciotti": "Natif de Nice et diplômé de l'IEP de Paris, Éric Ciotti a exercé comme collaborateur de cabinet ministériel et parlementaire. Président du conseil départemental des Alpes-Maritimes entre 2008 et 2017, il est élu député de la 1re circonscription du département sans interruption depuis 2007. Il préside le parti Union des Droites pour la République (UDR).",
  "eric-coquerel": "Né à Courbevoie, Éric Coquerel a exercé les professions de communicant et de professionnel de la voile avant son engagement politique national. Membre fondateur du Parti de gauche puis de La France insoumise, il est élu député de la 1re circonscription de la Seine-Saint-Denis en 2017. Il préside la commission des Finances de l'Assemblée nationale depuis 2022.",
  "eric-girardin": "Né à Epernay, Éric Girardin a mené une carrière dans les secteurs de la banque (Crédit Agricole), de l'assurance et de la transmission d'entreprises. Il a également enseigné en IUT et en école de commerce. Élu député de la 3e circonscription de la Marne en 2017 sous l'étiquette Renaissance, il est réélu lors du scrutin législatif de juin 2022.",
  "eric-liegeon": "Natif de Besançon, Éric Liégeon a exercé comme cadre au sein de la fonction publique territoriale après avoir mené des études supérieures. Maire de Courchaton et membre du Rassemblement national, il s'est investi sur les enjeux de ruralité et de proximité. Il est élu député de la 2e circonscription de la Haute-Saône lors des élections législatives de juillet 2024.",
  "eric-martineau": "Natif de la Sarthe, Éric Martineau est agriculteur pomiculteur de profession, ayant repris l'exploitation familiale en 1990. Maire de Chenu entre 2020 et 2022 et s'est investi dans les structures intercommunales de son département. Il est élu député de la 3e circonscription de la Sarthe lors des élections législatives de juin 2022 sous l'étiquette du MoDem.",
  "eric-michoux": "Né à Chalon-sur-Saône et ingénieur diplômé de l'IPSA, Éric Michoux a été ingénieur R&D avant de fonder le groupe industriel Galilé. Ancien président du Medef de Saône-et-Loire et maire d'Épervans pendant seize ans, il est élu député de la 4e circonscription de Saône-et-Loire en juillet 2024, siégeant au sein du groupe À droite !.",
  "eric-pauget": "Natif d'Antibes, Éric Pauget a exercé comme cadre dans le secteur privé avant de se consacrer à ses mandats locaux. Premier adjoint au maire d'Antibes et conseiller départemental des Alpes-Maritimes, il est élu député de la 7e circonscription du département en 2017 sous l'étiquette Les Républicains, siège qu'il conserve lors des scrutins de 2022 et 2024.",
  "eric-woerth": "Natif de Creil et diplômé de HEC et de Sciences Po Paris, Éric Woerth a mené une carrière de cadre dirigeant et consultant avant d'occuper plusieurs fonctions ministérielles (Budget, Travail). Membre du parti Renaissance et ancien maire de Chantilly, il est spécialisé dans les questions budgétaires. Il est élu député de l'Oise en juin 2002 et réélu lors de chaque scrutin législatif suivant.",
  "ersilia-soudais": "Native d'Aubervilliers, Ersilia Soudais exerce la profession de professeure certifiée de français après des études de lettres. Membre de La France insoumise et engagée sur les thématiques de lutte contre les discriminations et de justice sociale, elle s'est investie dans la vie publique de Seine-et-Marne. Elle est élue députée de la 7e circonscription du département lors des élections législatives de juin 2022 et réélue en 2024.",
  "erwan-balanant": "Natif de Lorient, Erwan Balanant a exercé la profession de photographe et réalisateur audiovisuel après des études en arts et sciences de l'informatique. Adjoint au maire de Quimperlé entre 2008 et 2014, il est élu député de la 8e circonscription du Finistère en 2017 sous l'étiquette du MoDem et réélu lors des scrutins législatifs de 2022 et 2024.",
  "estelle-mercier": "Née à Nancy, Estelle Mercier est docteur en sciences de gestion et maître de conférences à l'IAE de Nancy (Université de Lorraine). Adjointe au maire de Nancy chargée des finances et conseillère métropolitaine, elle est élue députée de la 1re circonscription de Meurthe-et-Moselle en juillet 2024 sous l'étiquette du Parti socialiste.",
  "estelle-youssouffa": "Née à Châtenay-Malabry, Estelle Youssouffa a mené une carrière de journalistes pour LCI, France 2 et Al Jazeera English avant de devenir consultante en communication pour la Banque mondiale et Mazars. Élue députée de la 1re circonscription de Mayotte en 2022, elle siège au sein du groupe Libertés, Indépendants, Outre-mer et Territoires (LIOT).",
  "eva-sas": "Native de Nice et diplômée de l'ESSEC, Eva Sas a exercé comme experte économique auprès d'organisations syndicales au sein du cabinet Secafi. Élue députée de l'Essonne en 2012, elle retrouve un siège à l'Assemblée nationale en 2022 dans la 8e circonscription de Paris sous les couleurs des Écologistes. Elle est spécialisée sur les enjeux de transport.",
  "fabien-di-filippo": "Natif de Sarrebourg et diplômé de Sciences Po Paris, Fabien Di Filippo a été consultant chez KPMG puis cadre au sein du groupe Auchan avant son élection. Élu député de la 4e circonscription de la Moselle en 2017 sous l'étiquette Les Républicains, il est réélu en 2022 et 2024 avant de devenir maire de Sarrebourg en mars 2026.",
  "fabien-roussel": "Natif de Béthune, Fabien Roussel a mené une carrière de journaliste avant de s'engager pleinement dans la vie politique. Secrétaire national du Parti communiste français et député du Nord depuis 2017, il est une figure majeure de la gauche française. Il s'investit particulièrement sur les thématiques du pouvoir d'achat, de l'industrie et de la défense des services publics territoriaux.",
  "fabrice-barusseau": "Natif de Saintes, Fabrice Barusseau exerce la profession de professeur de technologie en collège. Maire de Villars-les-Bois depuis 2014 et conseiller départemental de la Charente-Maritime, il est engagé au sein du Parti socialiste. Il est élu député de la 3e circonscription de son département lors des élections législatives de juillet 2024.",
  "fabrice-brun": "Né à Aubenas, Fabrice Brun a été directeur départemental de la FDSEA de l'Ardèche avant de travailler comme indépendant dans le secteur viticole. Élu député de la 3e circonscription de l'Ardèche en 2017 sous l'étiquette Les Républicains, il siège désormais comme député non-inscrit à la suite du scrutin législatif de juillet 2024.",
  "fabrice-roussel": "Natif de Nantes, Fabrice Roussel a exercé comme cadre territorial au sein de collectivités locales après des études supérieures. Maire de La Chapelle-sur-Erdre depuis 2008 et membre du Parti socialiste, il est engagé sur les enjeux de développement métropolitain et de transports. Il est élu député de la 5e circonscription de Loire-Atlantique lors des élections législatives de juillet 2024.",
  "fanny-dombre-coste": "Native de Sainte-Adresse, Fanny Dombre-Coste a exercé la profession d'artisan photographe. Adjointe au maire de Montpellier entre 2008 et 2012 puis de 2020 à 2024, elle est engagée au sein du Parti socialiste. Élue députée de l'Hérault en 2012, elle retrouve son siège à l'Assemblée nationale lors des élections législatives de juillet 2024.",
  "farida-amrani": "Née à Ajdir (Maroc), Farida Amrani a exercé comme fonctionnaire territoriale au sein de la communauté d'agglomération Cœur d'Essonne. Conseillère municipale d'Évry-Courcouronnes, elle est engagée au sein de La France insoumise. Elle est élue députée de la 1re circonscription de l'Essonne lors des élections législatives de juin 2022 et réélue en 2024.",
  "fatiha-keloua-hachi": "Native de Montreuil, Fatiha Keloua Hachi a mené une carrière d'enseignante en lettres modernes pendant près de trente ans, notamment à l'université. Membre du Parti socialiste et engagée sur les enjeux d'éducation prioritaire et de lutte contre la pauvreté, elle s'est investie dans la vie publique de Seine-Saint-Denis. Elle est élue députée de la 8e circonscription du département en juin 2022 et réélue en 2024.",
  "felicie-gerard": "Native de Dunkerque, Félicie Gérard a effectué sa carrière au sein du groupe Enedis comme conseillère clients industriels puis chef de projet. Adjointe au maire de Wasquehal depuis 2014, elle est membre du parti Horizons. Elle est élue députée de la 7e circonscription du Nord lors des élections législatives de juin 2022 et réélue en 2024.",
  "florence-goulet": "Née au Mêle-sur-Sarthe, Florence Goulet est cadre de la fonction publique de profession, ayant notamment exercé au sein de cabinets et de groupes politiques. Membre du Rassemblement national, elle s'investit dans la vie publique locale dans le département de la Meuse. Elle est élue députée de la 2e circonscription de la Meuse lors des élections législatives de juin 2022.",
  "florence-herouin-leautey": "Native de Paris, Florence Hérouin-Léautey a exercé comme cadre au sein de la fonction publique territoriale. Adjointe au maire de Rouen chargée des écoles et conseillère départementale de la Seine-Maritime, elle est engagée au sein du Parti socialiste. Elle est élue députée de la 1re circonscription de son département lors des élections législatives de juillet 2024.",
  "florence-joubert": "Née à Reims, Florence Joubert a effectué sa carrière comme cadre de la fonction publique, occupant diverses fonctions administratives au sein de collectivités et de structures politiques. Conseillère régionale de Nouvelle-Aquitaine, elle est membre du Rassemblement national. Elle est élue députée de la 3e circonscription de la Dordogne lors des élections législatives de juillet 2024.",
  "florent-boudie": "Natif de Sainte-Foy-la-Grande, Florent Boudié a exercé comme cadre supérieur du secteur public, ayant notamment servi comme conseiller de cabinet ministériel et parlementaire. Élu député de la 10e circonscription de la Gironde en 2012 sous l'étiquette socialiste, il rejoint ensuite la majorité présidentielle (Renaissance) et préside la commission des Lois de l'Assemblée nationale depuis 2024.",
  "franck-allisio": "Natif de Marseille, Franck Allisio a exercé des fonctions de conseiller de cabinet ministériel (Relations avec le Parlement) et de professionnel de la communication en tant qu'indépendant. Conseiller régional de Provence-Alpes-Côte d'Azur et membre du Rassemblement national, il est élu député de la 12e circonscription des Bouches-du-Rhône lors des élections législatives de juin 2022.",
  "frank-giletti": "Natif de Paris, Frank Giletti a exercé comme cadre administratif et financier, dirigeant notamment des établissements scolaires à l'étranger. Conseiller régional de Provence-Alpes-Côte d'Azur et membre du Rassemblement national, il s'est investi sur les thématiques de sécurité et de gestion publique. Il est élu député de la 6e circonscription du Var lors des élections législatives de juin 2022 et réélu en 2024.",
  "franck-louvrier": "Natif de Nantes, Franck Louvrier a mené une carrière dans la communication, assurant la présidence de Publicis Events et la vice-présidence de Publicis Consultants. Conseiller historique de Nicolas Sarkozy à l'Élysée, il est élu maire de La Baule-Escoublac en 2020. Il a également été député suppléant et siège au conseil régional des Pays de la Loire.",
  "franck-riester": "Natif de Paris, Franck Riester est un chef d'entreprise ayant dirigé des concessions automobiles Peugeot familiales avant son engagement national. Maire de Coulommiers pendant dix ans et député de Seine-et-Marne depuis 2007, il a occupé plusieurs fonctions ministérielles (Culture, Commerce extérieur) entre 2018 et 2024 au sein du gouvernement.",
  "francois-cormier-bouligeon": "Né à Bourges, François Cormier-Bouligeon est juriste de formation. Il a exercé comme chef de cabinet adjoint du ministre de l'Économie à Bercy puis comme conseiller ministériel aux Sports. Élu député de la 1re circonscription du Cher en 2017 sous l'étiquette Renaissance, il est réélu lors des scrutins législatifs de 2022 et de 2024.",
  "francois-gernigon": "Natif d'Angers, François Gernigon a exercé comme directeur de mission au sein du cabinet CAEXIS AUDIT et a présidé la SAS SFP Collectivités. Maire de Saint-Sylvain-d'Anjou (Verrières-en-Anjou) de 2014 à 2022, il est membre du parti Horizons. Il est élu député de la 6e circonscription de Maine-et-Loire lors des élections législatives de juin 2022.",
  "francois-hollande": "Né à Rouen et diplômé de l'ENA (promotion Voltaire), François Hollande a débuté sa carrière comme auditeur à la Cour des comptes. Chargé de mission à l'Élysée dès 1981, il a également été maître de conférences à Sciences Po Paris. Président de la République entre 2012 et 2017, il est élu député de la 1re circonscription de la Corrèze en juillet 2024.",
  "francois-jolivet": "Natif de Châteauroux, François Jolivet a mené une carrière de cadre supérieur dans le secteur du logement social, exerçant des fonctions de direction au sein de groupes immobiliers. Maire de Saint-Maur pendant vingt-deux ans et conseiller régional, il est élu député de la 1re circonscription de l'Indre en 2017 sous l'étiquette LREM et réélu en 2022 et 2024.",
  "francois-piquemal": "Né à Besançon, François Piquemal exerce la profession de professeur de lettres, d'histoire et de géographie en lycée professionnel. Ancien porte-parole de l'association Droit au logement (DAL) à Toulouse, il est conseiller municipal de la ville. Membre de La France insoumise, il est élu député de la 4e circonscription de la Haute-Garonne en 2022 et réélu en 2024.",
  "francois-ruffin": "Natif de Calais, François Ruffin est journaliste, fondateur du journal Fakir et réalisateur de films documentaires, dont Merci Patron ! qui a reçu le César du meilleur film documentaire en 2017. Élu député de la 1re circonscription de la Somme en 2017 sous l'étiquette Picardie Debout !, il siège au sein du groupe Écologiste et Social à l'Assemblée nationale.",
  "francois-xavier-ceccoli": "Natif de Cervione, François-Xavier Ceccoli est un chef d'entreprise et agriculteur, président du groupement d'intérêt économique Corsica Comptoir. Maire de San-Giuliano entre 2008 et 2024, il est engagé au sein de la droite républicaine. Il est élu député de la 2e circonscription de la Haute-Corse lors des élections législatives de juillet 2024.",
  "francoise-buffet": "Native de Strasbourg, Françoise Buffet a exercé les professions de commerçante et de chef d'entreprise dans le secteur de la restauration. Adjointe au maire de Strasbourg chargée de l'éducation et de l'environnement entre 2008 et 2020, elle est membre du parti Renaissance. Elle est élue députée de la 4e circonscription du Bas-Rhin en juin 2022 et réélue en 2024.",
  "frantz-gumbs": "Natif de Saint-Martin, Frantz Gumbs a effectué sa carrière dans l'enseignement comme professeur puis proviseur, dirigeant notamment le GRETA des Îles du Nord. Ancien président de la collectivité de Saint-Martin et membre du groupe MoDem, il porte les enjeux spécifiques des territoires ultramarins. Il est élu député de la circonscription des Îles du Nord lors des élections législatives de juin 2022 et réélu en 2024.",
  "frederic-boccaletti": "Natif de Toulon, Frédéric Boccaletti a exercé les professions de libraire et d'éditeur, ainsi que de comptable pour la société Greece. Conseiller régional de Provence-Alpes-Côte d'Azur depuis 2010, il est membre du Rassemblement national. Élu député du Var en 2022, il devient maire de Six-Fours-les-Plages lors des élections municipales de mars 2026.",
  "frederic-falcon": "Né à Besançon et diplômé de l'INSEEC, Frédéric Falcon a été consultant en systèmes d'information avant de fonder un cabinet de conseil en investissement immobilier. Membre du Rassemblement national, il s'est investi sur les enjeux économiques et de logement. Il est élu député de la 2e circonscription de la Aude lors des élections législatives de juin 2022 et réélu en 2024.",
  "frederic-maillot": "Natif de Saint-Denis de La Réunion, Frédéric Maillot a exercé comme travailleur social, notamment au sein d'une fondation de lutte contre le mal-logement. Musicien de maloya et conseiller régional, il est engagé au sein du parti Pour La Réunion. Il est élu député de la 6e circonscription de l'île en juin 2022 et réélu lors du scrutin législatif de 2024.",
  "frederic-mathieu": "Né à Orléans, Frédéric Mathieu est un cadre de la fonction publique d'État, ayant exercé au ministère des Armées sur le contrôle des marchés publics d'armement. Militant syndical à la CGT, il est engagé au sein de La France insoumise. Il a été député de la 1re circonscription d'Ille-et-Vilaine entre 2022 et 2024 et vice-président de la délégation française au Conseil de l'Europe.",
  "frederic-petit": "Natif de Marseille et ingénieur de formation, Frédéric Petit a mené une carrière de dirigeant dans des entreprises du secteur de l'énergie en Europe centrale et en Égypte. Également médiateur et conseiller du commerce extérieur, il est élu député des Français établis hors de France (7e circonscription) en 2017 sous l'étiquette du MoDem et réélu en 2022 et 2024.",
  "frederic-pierre-vos": "Né à Draveil, Frédéric-Pierre Vos est un avocat d'affaires, cofondateur du cabinet LVI Avocats-Associés. Ancien directeur juridique adjoint de l'Epamarne, il est engagé au sein du Rassemblement national. Il est élu député de la 5e circonscription de l'Oise lors des élections législatives de juillet 2024, siégeant au sein du groupe À droite !.",
  "frederic-valletoux": "Natif de Paris, Frédéric Valletoux a exercé la profession de journaliste, notamment pour Les Échos et La Gazette des communes. Maire de Fontainebleau pendant dix-sept ans et président de la Fédération hospitalière de France, il est élu député de Seine-et-Marne en 2022. Il a occupé les fonctions de ministre délégué chargé de la Santé en 2024 au sein du gouvernement.",
  "frederic-weber": "Natif de Metz, Frédéric Weber exerce la profession d'infirmier, ayant notamment travaillé au sein du site ArcelorMittal de Florange. Ancien responsable syndical chez Force Ouvrière, il est engagé au sein du Rassemblement national. Il est élu député de la 3e circonscription de Meurthe-et-Moselle lors des élections législatives de juillet 2024.",
  "frederique-meunier": "Native de Paris, Frédérique Meunier exerce la profession d'avocate. Ancienne maire de Malemort-sur-Corrèze et conseillère départementale, elle préside la fédération LR de son département. Élue députée de la 2e circonscription de la Corrèze en 2017 sous l'étiquette Les Républicains, elle conserve son siège lors des scrutins de 2022 et 2024.",
  "gabriel-amard": "Natif de Juvisy-sur-Orge, Gabriel Amard est formateur d'élus locaux et auteur d'ouvrages sur la gestion publique de l'eau. Maire de Viry-Châtillon puis président de la communauté d'agglomération Les Lacs de l'Essonne, il est engagé au sein de La France insoumise. Il est élu député de la 6e circonscription du Rhône lors des élections législatives de juin 2022.",
  "gabriel-attal": "Né à Clamart et diplômé de Sciences Po Paris, Gabriel Attal a été chargé de mission à la Villa Médicis avant d'intégrer le cabinet de la ministre des Affaires sociales. Porte-parole du gouvernement puis ministre de l'Éducation nationale, il est nommé Premier ministre en janvier 2024. Il est député de la 10e circonscription des Hauts-de-Seine depuis 2017.",
  "gabrielle-cathala": "Native de Paris, Gabrielle Cathala a exercé comme cadre administratif au sein du secteur public après des études supérieures en droit. Engagée au sein de La France insoumise et membre de la vie publique du Val-d'Oise, elle s'est investie sur les thématiques de justice sociale et de services publics. Elle est élue députée de la 6e circonscription du département lors des élections législatives de juillet 2024.",
  "gaetan-dussausaye": "Natif de Brétigny-sur-Orge, Gaëtan Dussausaye est un cadre politique, ancien président du Front national de la jeunesse (FNJ). Conseiller régional d'Île-de-France et membre du bureau national du Rassemblement national, il est élu député de la 2e circonscription des Vosges en juillet 2024 et occupe le poste de secrétaire de l'Assemblée nationale depuis 2025.",
  "gaspard-gantzer": "Natif de Paris et diplômé de l'ENA, Gaspard Gantzer est un haut fonctionnaire et chef d'entreprise, fondateur de la Gantzer Agency. Ancien conseiller communication de Bertrand Delanoë à la mairie de Paris puis de François Hollande à l'Élysée, il a également été candidat aux élections municipales de Paris en 2020 avant de rejoindre la vie publique locale.",
  "gerald-darmanin": "Natif de Valenciennes et diplômé de Sciences Po Lille, Gérald Darmanin a été maire de Tourcoing avant d'occuper plusieurs fonctions ministérielles (Action et Comptes publics, Intérieur, Justice) entre 2017 et 2025. Élu député du Nord en 2012, il retrouve son siège à l'Assemblée nationale en 2024 sous l'étiquette de la majorité présidentielle.",
  "genevieve-darrieussecq": "Née à Dax, Geneviève Darrieussecq exerce la profession de médecin allergologue. Maire de Mont-de-Marsan entre 2008 et 2017 et présidente de l'agglomération, elle a occupé plusieurs fonctions ministérielles (Armées, Santé, Solidarités) depuis 2017. Elle est élue députée de la 1re circonscription des Landes sous l'étiquette du MoDem.",
  "geraldine-bannier": "Native de Laval et professeure agrégée de lettres classiques, Géraldine Bannier a exercé dans l'enseignement secondaire avant son élection. Maire de Courbeveille de 2014 à 2017, elle est membre du MoDem. Elle est élue députée de la 2e circonscription de la Mayenne lors des élections législatives de juin 2017 et réélue en 2022 et 2024.",
  "geraldine-grangier": "Née à Besançon, Géraldine Grangier a exercé la profession d'assistante sociale avant de s'engager dans la vie publique locale en tant que conseillère régionale de Bourgogne-Franche-Comté. Membre du Rassemblement national, elle est élue députée de la 4e circonscription du Doubs lors des élections législatives de juin 2022 et réélue en 2024.",
  "gerard-leseul": "Natif du Mesnil-Esnard, Gérard Leseul a été enseignant universitaire et cadre au sein du Crédit Mutuel, où il a occupé le poste de responsable des affaires publiques et de la RSE. Membre du Parti socialiste, il est élu député de la 5e circonscription de la Seine-Maritime en 2020 à la suite d'une élection partielle, et réélu en 2022 et 2024.",
  "gerault-verny": "Né à Bourgoin-Jallieu, Gérault Verny est un chef d'entreprise ayant exercé des fonctions de direction dans les secteurs industriel et technologique. Engagé au sein de l'Union des Droites pour la République (UDR), il est élu député de la 14e circonscription du Rhône lors des élections législatives de juillet 2024, siégeant au sein du groupe À droite !.",
  "gisele-lelouis": "Native de Paris, Gisèle Lelouis exerce la profession d'ingénieure en électronique de métier. Conseillère municipale de Marseille et conseillère métropolitaine, elle est membre du Rassemblement national. Elle est élue députée de la 3e circonscription des Bouches-du-Rhône lors des élections législatives de juin 2022 et réélue en 2024.",
  "graziella-melchior": "Née à Landerneau, Graziella Melchior est professeure agrégée d'économie et de gestion, ayant également une expérience professionnelle en entreprise. Conseillère municipale de Lannilis, elle est membre de la majorité présidentielle (Renaissance). Elle est élue députée de la 5e circonscription du Finistère en 2017 et réélue lors des scrutins de 2022 et 2024.",
  "gregoire-de-fournas": "Natif de Lesparre-Médoc, Grégoire de Fournas exerce la profession de viticulteur, gérant l'exploitation familiale du Château Cassan. Conseiller départemental de la Gironde entre 2015 et 2022 et membre du Rassemblement national, il est élu député de la 5e circonscription du département en juin 2022 et conserve son siège jusqu'en juin 2024.",
  "guillaume-bigot": "Né à Paris, Guillaume Bigot a été directeur général de l'école de commerce IPAG Business School et éditorialiste pour plusieurs médias nationaux (CNews, Europe 1). Engagé au sein du Rassemblement national, il est élu député de la 2e circonscription du Territoire de Belfort lors des élections législatives de juillet 2024.",
  "guillaume-florquin": "Natif de Dunkerque, Guillaume Florquin a exercé comme cadre de la fonction publique et a occupé des fonctions de direction dans le secteur médico-social. Membre du Rassemblement national et engagé sur les thématiques de santé et d'accès aux soins, il s'est investi dans la vie publique du Nord. Il est élu député de la 20e circonscription du département lors des élections législatives de juillet 2024.",
  "guillaume-garot": "Natif de Laval, Guillaume Garot a exercé comme conseiller de cabinet ministériel avant de devenir maire de Laval puis ministre délégué à l'Agroalimentaire entre 2012 et 2014. Membre du Parti socialiste, il est élu député de la 1re circonscription de la Mayenne sans interruption depuis 2007 et préside le conseil national de son parti.",
  "guillaume-gouffier-valente": "Né à Beauvais, Guillaume Gouffier Valente a exercé comme assistant en ressources humaines puis comme conseiller technique au sein du cabinet du ministre de la Défense Jean-Yves Le Drian. Élu député de la 6e circonscription du Val-de-Marne en 2017 sous l'étiquette LREM, il est réélu en 2022 et 2024, s'investissant particulièrement sur les enjeux de défense.",
  "guillaume-kasbarian": "Natif de Marseille et diplômé de l'ESSEC, Guillaume Kasbarian a mené une carrière de consultant en stratégie chez Monitor Group puis de manager au sein du cabinet PMP Conseil. Élu député d'Eure-et-Loir en 2017, il a occupé les fonctions de ministre délégué au Logement puis de ministre de la Fonction publique en 2024 au sein du gouvernement.",
  "guillaume-lepers": "Né à Besançon, Guillaume Lepers a exercé des fonctions de cadre au sein du groupe de distribution Gifi avant de se consacrer à ses mandats locaux. Maire de Villeneuve-sur-Lot entre 2020 et 2024 et président de l'agglomération, il est membre du parti Les Républicains. Il est élu député de la 3e circonscription du Lot-et-Garonne lors des élections législatives de juillet 2024.",
  "hadrien-clouet": "Natif d'Aix-en-Provence et docteur en sociologie, Hadrien Clouet a mené une carrière de chercheur postdoctoral au CNRS et d'enseignant universitaire. Spécialiste des questions liées au travail et à l'emploi, il est engagé au sein de La France insoumise. Il est élu député de la 1re circonscription de la Haute-Garonne lors des élections législatives de juin 2022 et réélu en 2024.",
  "hanane-mansouri": "Née à Échirolles, Hanane Mansouri était étudiante en droit public lors de son élection, ayant également exercé comme attachée de groupe politique et chargée de mission régionale. Ancienne présidente des Jeunes Républicains de l'Isère, elle rejoint l'UDR d'Éric Ciotti. Elle est élue députée de la 8e circonscription de l'Isère lors des élections législatives de juillet 2024.",
  "harold-huwart": "Né à Nogent-le-Rotrou et diplômé de l'ENA, Harold Huwart est un haut fonctionnaire et agrégé d'histoire de formation. Maire de Nogent-le-Rotrou de 2020 à 2024 et vice-président du conseil régional du Centre-Val de Loire, il est membre du Parti radical. Il est élu député de la 3e circonscription d'Eure-et-Loir lors des élections législatives de juillet 2024.",
  "helene-laporte": "Native de Villeneuve-sur-Lot, Hélène Laporte a exercé la profession d'analyste bancaire au Crédit Agricole et de conseillère en gestion de patrimoine. Ancienne députée européenne et conseillère régionale, elle est vice-présidente du Rassemblement national. Élue députée du Lot-et-Garonne en 2022, elle occupe le poste de vice-présidente de l'Assemblée nationale.",
  "hendrik-davi": "Natif de Marseille et docteur en écologie, Hendrik Davi est chercheur à l'INRAE, spécialisé dans l'étude de l'adaptation des forêts au changement climatique. Membre de la Gauche démocrate et républicaine et engagé sur les enjeux de planification écologique, il s'est investi dans la vie publique des Bouches-du-Rhône. Il est élu député de la 5e circonscription du département en juin 2022 et réélu en 2024.",
  "henri-alfandari": "Né à Tours, Henri Alfandari a exercé comme directeur de la communication du groupe de santé Saint-Gatien et a réalisé des films documentaires. Maire de Genillé entre 2020 et 2022 et conseiller départemental d'Indre-et-Loire, il est membre du parti Horizons. Il est élu député de la 3e circonscription de son département lors des élections législatives de juin 2022.",
  "herve-berville": "Natif de Madina (Guinée) et diplômé de la London School of Economics, Hervé Berville a exercé comme économiste pour l'Agence française de développement. Secrétaire d'État chargé de la Mer entre 2022 et 2024 et membre du parti Renaissance, il est spécialisé dans les enjeux de développement international et d'économie maritime. Il est élu député des Côtes-d'Armor en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "herve-de-lepinau": "Natif de Toulon, Hervé de Lépinau exerce la profession d'avocat au barreau de Carpentras, ayant été associé gérant au sein d'un cabinet juridique. Conseiller départemental de Vaucluse depuis 2015, il est membre du Rassemblement national. Élu député de Vaucluse en 2022, il devient maire de Carpentras lors des élections municipales de mars 2026.",
  "herve-saulignac": "Né à Privas, Hervé Saulignac a exercé comme cadre territorial après avoir été collaborateur d'élu. Président du conseil départemental de l'Ardèche entre 2012 et 2017 et conseiller régional, il est membre du Parti socialiste. Il est élu député de la 1re circonscription de l'Ardèche en 2017 et réélu lors des scrutins législatifs de 2022 et de 2024.",
  "hubert-brigand": "Natif de Châtillon-sur-Seine, Hubert Brigand a exercé une profession intermédiaire avant son engagement politique. Maire de sa ville natale pendant vingt-sept ans et conseiller départemental de la Côte-d'Or depuis 1988, il est membre du parti Les Républicains. Il est élu député de la 4e circonscription de son département lors des élections législatives de juin 2022 et réélu en 2024.",
  "hubert-ott": "Né à Colmar, Hubert Ott est professeur agrégé de sciences de la vie et de la terre (SVT) de profession. Biologiste et photographe naturaliste, il s'est investi dans la protection de l'environnement avant d'être élu conseiller municipal de Rouffach. Membre du MoDem, il est élu député de la 2e circonscription du Haut-Rhin lors des élections législatives de juin 2022 et réélu en 2024.",
  "ian-boucard": "Natif de Belfort, Ian Boucard a exercé comme cadre dans le secteur de la communication au sein du secteur privé. Conseiller municipal de Belfort et membre du parti Les Républicains, il est élu député de la 1re circonscription du Territoire de Belfort lors d'une élection partielle en 2018, après un premier scrutin en 2017, et conserve son siège jusqu'en juin 2024.",
  "idir-boumertit": "Né à Lyon, Idir Boumertit a exercé comme conseiller en insertion professionnelle et employé administratif d'entreprise. Adjoint au maire de Vénissieux pendant plus de vingt ans et conseiller métropolitain de Lyon, il est membre de La France insoumise. Élu député du Rhône en 2022, il devient maire de Vénissieux lors des élections municipales de mars 2026.",
  "inaki-echaniz": "Né à Oloron-Sainte-Marie, Iñaki Echaniz exerce la profession de conseiller principal d'éducation (CPE) au sein de la fonction publique. Conseiller municipal de sa ville natale et membre du Parti socialiste, il est élu député de la 4e circonscription des Pyrénées-Atlantiques lors des élections législatives de juin 2022 et occupe le poste de secrétaire de l'Assemblée nationale depuis 2024.",
  "isabelle-rauch": "Native de Villers-Semeuse, Isabelle Rauch a mené une carrière de consultante en formation professionnelle et de responsable dans le secteur agroalimentaire. Conseillère régionale du Grand Est et membre du parti Horizons, elle est élue députée de la 9e circonscription de la Moselle en 2017. Elle préside la commission des Affaires culturelles et de l'Éducation de l'Assemblée nationale entre 2022 et 2024.",
  "isabelle-santiago": "Née à Neuilly-sur-Seine, Isabelle Santiago a exercé comme cadre au sein de la fonction publique territoriale. Conseillère départementale du Val-de-Marne depuis 2015 et ancienne adjointe au maire d'Alfortville, elle est membre du Parti socialiste. Elle est élue députée de la 9e circonscription du département lors d'une élection partielle en 2020 et réélu en 2022 et 2024.",
  "jacques-oberti": "Natif de Marseille et ingénieur agronome de formation, Jacques Oberti a exercé comme ingénieur territorial. Maire d'Ayguesvives entre 2008 et 2024 et président du Sicoval (communauté d'agglomération du Sud-Est toulousain), il est membre du Parti socialiste. Il est élu député de la 10e circonscription de la Haute-Garonne lors des élections législatives de juillet 2024.",
  "jean-carles-grelier": "Né au Mans, Jean-Carles Grelier exerce la profession d'avocat spécialisé en droit public. Maire de La Ferté-Bernard pendant neuf ans et conseiller départemental de la Sarthe, il est membre de la majorité présidentielle. Élu député de la Sarthe en 2017 sous l'étiquette Les Républicains, il rejoint ensuite le groupe Horizons puis le groupe Les Démocrates en 2024.",
  "jean-claude-raux": "Natif d'Argentan, Jean-Claude Raux a exercé comme enseignant en lettres-anglais au sein d'un lycée professionnel après une carrière de formateur. Maire de Saffré entre 2020 et 2022 et membre du parti Écologiste, il est élu député de la 6e circonscription de la Loire-Atlantique lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "jean-francois-coulomme": "Né à Paris, Jean-François Coulomme a exercé comme ingénieur commercial dans le secteur de l'informatique et des nouvelles technologies. Conseiller municipal de Chambéry et engagé au sein de La France insoumise, il est élu député de la 4e circonscription de la Savoie lors des élections législatives de juin 2022 et réélu lors du scrutin législatif de juillet 2024.",
  "jean-francois-portarrieu": "Natif de Toulouse, Jean-François Portarrieu a exercé la profession de journaliste au sein du groupe La Dépêche du Midi avant de diriger des services de communication territoriale. Conseiller municipal de Toulouse et membre du parti Horizons, il est élu député de la 5e circonscription de la Haute-Garonne lors des élections législatives de juin 2017 et réélu en 2022 et 2024.",
  "jean-francois-rousset": "Né à Aurillac, Jean-François Rousset a exercé la profession de chirurgien digestif, notamment au sein de la clinique Pasteur de Toulouse. Retraité depuis 2014 et membre du parti Renaissance, il est engagé dans la vie publique locale en Aveyron. Il est élu député de la 3e circonscription de l'Aveyron lors des élections législatives de juin 2022 et réélu en juillet 2024.",
  "jean-hugues-ratenon": "Natif de Saint-Benoît de La Réunion, Jean-Hugues Ratenon a exercé comme employé dans le secteur privé tout en menant un engagement associatif contre la pauvreté. Conseiller régional et membre de La France insoumise, il fonde le parti Rézistan's Égalité 974. Il est élu député de la 5e circonscription de l'île en 2017 et réélu lors des scrutins législatifs de 2022 et 2024.",
  "jean-louis-roumegas": "Natif d'Alger, Jean-Louis Roumégas exerce la profession de professeur des écoles au sein de l'éducation nationale. Ancien porte-parole national d'Europe Écologie Les Verts et adjoint au maire de Montpellier, il est élu député de la 1re circonscription de l'Hérault en 2012 sous l'étiquette écologiste et retrouve son siège à l'Assemblée nationale en juillet 2024.",
  "jean-louis-thieriot": "Natif de Paris, Jean-Louis Thiériot exerce la profession d'avocat au barreau de Paris. Maire de Beauvoir et président du conseil départemental de Seine-et-Marne en 2018, il est membre du parti Les Républicains. Élu député de Seine-et-Marne en 2018, il a occupé les fonctions de ministre délégué aux Armées et aux Anciens combattants à la fin de l'année 2024.",
  "jean-luc-bourgeaux": "Natif de Saint-Malo, Jean-Luc Bourgeaux exerce la profession d'agriculteur au sein de l'exploitation familiale. Maire de Cherrueix pendant dix-neuf ans et conseiller départemental d'Ille-et-Vilaine depuis 2008, il est membre de la droite républicaine. Il est élu député de la 7e circonscription de son département en 2020 et réélu lors des scrutins de 2022 et 2024.",
  "jean-luc-fugit": "Natif de Rodez et docteur-ingénieur en chimie, Jean-Luc Fugit a mené une carrière d'enseignant-chercheur et de vice-président à l'université Jean-Monnet de Saint-Étienne. Membre du parti Renaissance, il préside le Conseil supérieur de l'énergie. Il est élu député de la 11e circonscription du Rhône lors des élections législatives de juin 2017 et réélu en 2022 et 2024.",
  "jean-luc-warsmann": "Natif de Villers-Semeuse, Jean-Luc Warsmann a exercé comme directeur d'une mutuelle étudiante avant son engagement national. Maire de Douzy pendant près de vingt ans et conseiller régional du Grand Est, il est membre de la droite républicaine. Il est élu député de la 3e circonscription des Ardennes sans interruption depuis 1995 et a présidé la commission des Lois.",
  "jean-marie-fievet": "Natif de Bressuire, Jean-Marie Fiévet a effectué sa carrière comme sapeur-pompier professionnel, atteignant le grade de lieutenant au sein du service départemental d'incendie et de secours. Membre du parti Renaissance, il est élu député de la 3e circonscription des Deux-Sèvres lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "jean-michel-brard": "Natif de Pornic, Jean-Michel Brard a exercé les professions d'enseignant puis de commerçant et chef d'entreprise. Maire de Pornic pendant dix ans et président de l'agglomération Pornic Agglo Pays de Retz, il est membre de la majorité présidentielle. Il est élu député de la 9e circonscription de la Loire-Atlantique lors des élections législatives de juillet 2024.",
  "jean-michel-jacques": "Natif de Metz, Jean-Michel Jacques a servi comme infirmier au sein des forces spéciales de la Marine nationale pendant vingt ans avant de devenir enseignant en gestes d'urgence. Maire de Brandérion et membre du parti Renaissance, il est élu député du Morbihan en 2017. Il préside la commission de la Défense nationale et des Forces armées depuis juillet 2024.",
  "jean-paul-lecoq": "Natif du Havre, Jean-Paul Lecoq a exercé la profession d'électricien avant de se consacrer à ses mandats électifs. Maire de Gonfreville-l'Orcher pendant vingt-deux ans et membre du Parti communiste français, il est élu député de la 6e circonscription de la Seine-Maritime en 2007. Il retrouve son siège à l'Assemblée nationale en 2017 et est réélu en 2022 et 2024.",
  "jean-philippe-nilor": "Natif de Fort-de-France, Jean-Philippe Nilor a exercé comme collaborateur parlementaire avant son élection. Titulaire d'un DEA en aménagement du territoire et membre du parti Péyi-A, il siège au conseil à l'Assemblée de Martinique. Élu député de la 4e circonscription de l'île en juin 2012, il conserve son siège lors de tous les scrutins législatifs ultérieurs.",
  "jean-philippe-tanguy": "Natif de Boulogne-sur-Mer et diplômé de l'ESSEC, Jean-Philippe Tanguy a exercé comme cadre administratif et commercial au sein du secteur industriel et énergétique. Conseiller régional des Hauts-de-France et membre du Rassemblement national, il préside le parti L'Avenir français. Il est élu député de la 4e circonscription de la Somme en juin 2022 et réélu en 2024.",
  "jean-pierre-bataille": "Natif d'Hazebrouck, Jean-Pierre Bataille exerce la profession de pharmacien. Maire de Steenvoorde depuis 1999 et ancien vice-président du conseil régional des Hauts-de-France, il est membre du parti Utiles. Il est élu député de la 15e circonscription du Nord lors des élections législatives de juillet 2024, siégeant au sein du groupe Libertés, Indépendants, Outre-mer et Territoires.",
  "jean-pierre-taite": "Natif de Feurs, Jean-Pierre Taite a exercé les professions de photographe et d'artisan-commerçant. Maire de sa ville natale pendant quatorze ans et vice-président de la région Auvergne-Rhône-Alpes, il préside la fédération LR de la Loire. Élu député de la 6e circonscription du département en juin 2022, il conserve son siège lors du scrutin législatif de juillet 2024.",
  "jean-pierre-vigier": "Natif de Brioude, Jean-Pierre Vigier est un haut fonctionnaire au sein de la fonction publique d'État. Maire de Lavoûte-Chilhac entre 2008 et 2020 et conseiller régional d'Auvergne-Rhône-Alpes, il est membre du parti Les Républicains. Il est élu député de la 2e circonscription de la Haute-Loire lors des élections législatives de juin 2012 et réélu lors de tous les scrutins suivants.",
  "jean-rene-cazeneuve": "Natif de Paris et ingénieur de formation, Jean-René Cazeneuve a mené une carrière de cadre dirigeant au sein de grandes entreprises technologiques, notamment comme directeur général chez Apple France et Cisco. Membre du parti Renaissance, il est élu député du Gers en 2017 et occupe le poste de rapporteur général du budget de l'Assemblée nationale entre 2022 et 2024.",
  "jean-terlier": "Natif de Toulon, Jean Terlier exerce la profession d'avocat, spécialisé dans les domaines du droit rural et agroalimentaire. Conseiller municipal de Lavaur et membre du parti Renaissance, il s'est investi sur les questions de justice et de territoires. Il est élu député de la 3e circonscription du Tarn lors des élections législatives de juin 2017 et réélu en 2022 et 2024.",
  "jean-victor-castor": "Natif de Sinnamary, Jean-Victor Castor a exercé comme cadre technique au sein de l'entreprise EDF en Guyane tout en menant un engagement syndical à l'UTG. Membre du Mouvement de décolonisation et d'émancipation sociale, il est conseiller à l'Assemblée de Guyane. Il est élu député de la 1re circonscription du territoire lors des élections législatives de juin 2022.",
  "jean-yves-bony": "Natif d'Aurillac, Jean-Yves Bony exerce la profession d'exploitant agricole. Maire d'Ally pendant seize ans et vice-président du conseil départemental du Cantal, il est membre du parti Les Républicains. Suppléant d'Alain Marleix, il devient député du Cantal en 2007 avant d'être élu en son nom propre lors des élections législatives de juin 2017, réélu en 2022 et 2024.",
  "jeremie-iordanoff": "Natif de Laxou, Jérémie Iordanoff exerce la profession d'artiste-peintre, ayant également servi comme collaborateur parlementaire. Engagé au sein du parti Écologiste, il s'investit particulièrement sur les enjeux institutionnels. Élu député de l'Isère en 2022, il occupe le poste de vice-président de l'Assemblée nationale entre octobre 2024 et octobre 2025.",
  "jeremie-patrier-leitus": "Natif de Paris et diplômé de Paris-Dauphine, Jérémie Patrier-Leitus a exercé comme cadre de la fonction publique, notamment au sein du cabinet de la ministre de la Culture et pour la reconstruction de Notre-Dame. Membre du parti Horizons, il est élu député de la 3e circonscription du Calvados lors des élections législatives de juin 2022 et réélu en 2024.",
  "jerome-buisson": "Natif de Roanne, Jérôme Buisson exerce la profession de professeur d'italien au sein de l'éducation nationale. Conseiller municipal de Bourg-en-Bresse et conseiller régional d'Auvergne-Rhône-Alpes, il est membre du Rassemblement national. Il est élu député de la 4e circonscription de l'Ain lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "jerome-guedj": "Natif de Pantin et diplômé de l'ENA, Jérôme Guedj est inspecteur général des affaires sociales (IGAS) de profession. Président du conseil départemental de l'Essonne entre 2011 et 2015 et membre du Parti socialiste, il est élu député de l'Essonne en 2012. Il retrouve son siège à l'Assemblée nationale en 2022 et est réélu lors du scrutin législatif de juillet 2024.",
  "jerome-legavre": "Natif de Rennes, Jérôme Legavre exerce la profession de professeur de lettres après avoir été employé administratif. Responsable syndical au sein de la FNEC FP-FO et membre du Parti ouvrier indépendant, il est engagé au sein de La France insoumise. Il est élu député de la 12e circonscription de la Seine-Saint-Denis lors des élections législatives de juin 2022.",
  "jerome-nury": "Natif de Valence, Jérôme Nury a exercé comme cadre de la fonction publique territoriale et collaborateur parlementaire. Maire de Tinchebray pendant sept ans et président de l'intercommunalité, il est membre du parti Les Républicains. Élu député de l'Orne en 2017 et réélu en 2022, il devient maire de Tinchebray-Bocage lors des élections municipales de mars 2026.",
  "jimmy-pahun": "Natif de Paris, Jimmy Pahun est un navigateur professionnel, skippeur de renom et ancien journaliste sportif spécialisé dans la voile. Conseiller municipal de Port-Louis et membre de la majorité présidentielle (MoDem), il est élu député de la 2e circonscription du Morbihan lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "jiovanny-william": "Natif de Fort-de-France, Jiovanny William exerce la profession d'avocat au barreau de Martinique depuis 2013. Conseiller municipal du Robert et engagé dans la vie publique locale, il siège au sein du groupe Socialistes et apparentés à l'Assemblée nationale. Il est élu député de la 1re circonscription de la Martinique lors des élections législatives de juin 2022.",
  "jocelyn-dessigny": "Né à Noisy-le-Grand, Jocelyn Dessigny a exercé comme responsable d'agence dans le secteur de l'intérim après avoir été chargé d'affaires et chef d'entreprise. Premier adjoint au maire de Villers-Cotterêts et membre du Rassemblement national, il est élu député de la 5e circonscription de l'Aisne lors des élections législatives de juin 2022 et réélu en 2024.",
  "joel-aviragnet": "Natif d'Encausse-les-Thermes, Joël Aviragnet a mené une carrière de directeur d'établissement spécialisé pour l'enfance handicapée après avoir exercé comme kinésithérapeute. Membre du Parti socialiste, il est élu député de la 8e circonscription de la Haute-Garonne lors d'une élection partielle en 2017 et réélu lors des scrutins législatifs de 2022 et 2024.",
  "joel-bruneau": "Né à Levroux et diplômé de Sciences Po Paris, Joël Bruneau a exercé comme cadre dans le secteur financier à la Caisse d'Épargne et comme directeur général des services de région. Maire de Caen pendant dix ans et membre de la droite républicaine, il est élu député de la 1re circonscription du Calvados lors des élections législatives de juillet 2024.",
  "joelle-melin": "Native de Versailles, Joëlle Mélin exerce la profession de médecin, spécialisée comme médecin expert judiciaire auprès des tribunaux. Ancienne députée européenne et membre du Rassemblement national, elle est conseillère municipale d'Aubagne. Elle est élue députée de la 9e circonscription des Bouches-du-Rhône en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "jonathan-gery": "Natif d'Aubenas, Jonathan Gery a effectué sa carrière au sein du gendarmerie nationale en tant que policier et militaire. Engagé au sein du Rassemblement national, il s'est investi sur les questions de sécurité et de ruralité. Il est élu député de la 8e circonscription du Rhône lors des élections législatives de juillet 2024, siégeant au sein du groupe RN.",
  "jordan-guitton": "Natif de Troyes, Jordan Guitton a exercé la profession de collaborateur parlementaire avant son élection à l'Assemblée nationale. Conseiller régional du Grand Est et membre du Rassemblement national, il est élu député de la 1re circonscription de l'Aube lors des élections législatives de juin 2022 et réélu au premier tour lors du scrutin de juin 2024.",
  "jorys-bovet": "Né à Saint-Martin-d'Hères, Jorys Bovet a exercé la profession de chauffeur-livreur avant son engagement dans la vie politique nationale. Membre du Rassemblement national, il s'est investi sur les thématiques liées au pouvoir d'achat et aux transports. Il est élu député de la 2e circonscription de l'Allier lors des élections législatives de juin 2022 et réélu en 2024.",
  "jose-beaurain": "Natif de Chauny, José Beaurain exerce la profession d'artisan accordeur de pianos de métier. Conseiller municipal de sa ville natale et membre du Rassemblement national, il est le premier député non-voyant de la Ve République. Il est élu député de la 4e circonscription de l'Aisne lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "jose-gonzalez": "Natif d'Oran, José Gonzalez a exercé des fonctions administratives au sein de la Chambre de Commerce et d'Industrie puis à l'Aéroport Marseille-Provence. Conseiller municipal d'Allauch et doyen de l'Assemblée nationale en 2022, il est membre du Rassemblement national. Il est élu député de la 10e circonscription des Bouches-du-Rhône en 2022 et réélu en 2024.",
  "joseph-riviere": "Natif de Saint-Denis de La Réunion, Joseph Rivière a exercé comme cadre administratif au sein de la fonction publique, notamment sur les enjeux d'insertion. Engagé au sein du Rassemblement national, il s'est investi dans la défense des territoires ultramarins. Il est élu député de la 3e circonscription de La Réunion lors des élections législatives de juillet 2024.",
  "josephine-missoffe": "Native de Boulogne-Billancourt, Joséphine Missoffe a exercé les professions d'infirmière-puéricultrice et de directrice de crèche, puis de directrice de PMI pour la Croix-Rouge. Conseillère municipale du 16e arrondissement de Paris, elle rejoint l'Assemblée nationale en tant que députée de Paris en juillet 2024, siégeant au sein du groupe Ensemble pour la République.",
  "josy-poueyto": "Native de Paris, Josy Poueyto est une retraitée de la fonction publique d'État après une carrière administrative. Première adjointe au maire de Pau pendant plusieurs années et membre du MoDem, elle est élue députée de la 1re circonscription des Pyrénées-Atlantiques lors des élections législatives de juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "julie-delpech": "Native du Mans, Julie Delpech a exercé comme chargée de communication au sein du groupe de services à la personne Oui Care après avoir été collaboratrice d'élus locaux. Membre du parti Renaissance, elle est élue députée de la 4e circonscription de la Sarthe lors des élections législatives de juin 2022 et réélue lors du scrutin législatif de juillet 2024.",
  "julie-laernoes": "Native de Delft (Pays-Bas) et diplômée de Sciences Po Paris, Julie Laernoes a exercé comme assistante parlementaire au Sénat et chef de cabinet en collectivité. Adjointe à la maire de Nantes et vice-présidente de la métropole, elle est membre du parti Écologiste. Elle est élue députée de la 4e circonscription de Loire-Atlantique en 2022 et réélue en 2024.",
  "julie-lechanteux": "Native d'Annecy, Julie Lechanteux a exercé les professions d'agente immobilière et de responsable dans les secteurs de la restauration et de la coiffure. Ancienne députée européenne et adjointe au maire de Fréjus, elle est membre du Rassemblement national. Elle est élue députée de la 5e circonscription du Var en 2022 et réélu lors du scrutin de 2024.",
  "julie-ozenne": "Native de Granville et architecte de formation, Julie Ozenne exerce la profession d'ingénieure et cadre technique au sein du secteur privé. Conseillère municipale de Vigneux-sur-Seine et membre du parti Écologiste, elle s'est investie sur les enjeux d'urbanisme durable. Elle est élue députée de la 9e circonscription de l'Essonne lors des élections législatives de juillet 2024.",
  "julien-brugerolles": "Né à Beaumont et diplômé de l'IEP de Toulouse, Julien Brugerolles a exercé comme enseignant en économie sociale avant de devenir collaborateur parlementaire. Adjoint au maire de Paslières et membre de la Gauche démocrate et républicaine, il est élu député de la 5e circonscription du Puy-de-Dôme lors des élections législatives de juillet 2024.",
  "julien-dive": "Natif de Saint-Quentin, Julien Dive a mené une carrière de chef de projet au sein du secteur industriel avant de se consacrer à ses mandats électifs. Maire d'Itancourt entre 2014 et 2017 et membre du parti Les Républicains, il est vice-président de la commission des Affaires économiques. Il est élu député de l'Aisne lors d'une élection partielle en 2016 et réélu depuis.",
  "julien-gabarron": "Natif de Lille, Julien Gabarron a exercé les professions de gérant d'établissement commercial puis d'ingénieur commercial au sein du groupe Fiducial. Conseiller municipal de Béziers et membre du Rassemblement national, il est élu député de la 6e circonscription de l'Hérault lors des élections législatives de juillet 2024, siégeant au sein du groupe RN.",
  "julien-gokel": "Natif de Saint-Pol-sur-Mer, Julien Gokel a exercé des fonctions de cadre administratif au sein de la fonction publique territoriale. Maire de sa ville natale et vice-président de la Communauté urbaine de Dunkerque, il est membre du Parti socialiste. Il est élu député de la 13e circonscription du Nord lors des élections législatives de juillet 2024.",
  "julien-guibert": "Natif de Clamecy, Julien Guibert a exercé comme cadre dans le conseil et l'audit, ayant été associé au sein de cabinets spécialisés. Conseiller régional de Bourgogne-Franche-Comté et membre du Rassemblement national, il est élu député de la 2e circonscription de la Nièvre lors des élections législatives de juillet 2024, siégeant au sein du groupe RN.",
  "julien-limongi": "Natif de la Ciotat et diplômé de Sciences Po Toulouse, Julien Limongi a exercé comme collaborateur parlementaire et a travaillé au sein d'une ambassade française à l'étranger. Membre du Rassemblement national, il s'est investi sur les questions de politique étrangère. Il est élu député de la 4e circonscription de Seine-et-Marne lors des élections législatives de juillet 2024.",
  "julien-odoul": "Natif de Paris, Julien Odoul a exercé la profession de collaborateur parlementaire après des études d'histoire. Conseiller régional de Bourgogne-Franche-Comté et porte-parole national du Rassemblement national, il est une figure médiatique de son parti. Il est élu député de la 3e circonscription de l'Yonne lors des élections législatives de juin 2022 et réélu en 2024.",
  "julien-rancoule": "Natif de Carcassonne, Julien Rancoule a exercé les fonctions d'agent de sécurité et de sapeur-pompier volontaire avant son engagement politique. Conseiller municipal de Limoux et membre du Rassemblement national, il est élu député de la 3e circonscription de l'Aude lors des élections législatives de juin 2022 et réélu lors du scrutin législatif de juillet 2024.",
  "justine-gruet": "Native de Besançon, Justine Gruet exerce la profession de masseur-kinésithérapeute en cabinet libéral. Adjointe au maire de Dole pendant huit ans et membre du parti Les Républicains, elle s'est investie sur les thématiques de santé et de proximité. Elle est élue députée de la 3e circonscription du Jura lors des élections législatives de juin 2022 et réélue en 2024.",
  "karen-erodi": "Native de Toulouse, Karen Erodi a exercé comme cheffe d'entreprise dans le secteur de l'économie de la construction et de la maîtrise d'œuvre. Engagée au sein de La France insoumise, elle est élue députée de la 2e circonscription du Tarn lors des élections législatives de juin 2022 et réélue lors du scrutin législatif de juillet 2024.",
  "karim-ben-cheikh": "Natif de Tunis et diplômé de Sciences Po Paris, Karim Ben Cheikh est un diplomate de carrière ayant servi comme consul général de France à Beyrouth. Membre du parti Génération.s, il est élu député des Français établis hors de France (9e circonscription) lors des élections législatives de juin 2022 et réélu lors des scrutins de 2023 et 2024.",
  "karim-benbrahim": "Natif de Salon-de-Provence, Karim Benbrahim exerce la profession d'ingénieur, ayant notamment travaillé au sein de l'entreprise RTE à Nantes. Premier secrétaire fédéral du Parti socialiste en Loire-Atlantique, il est élu député de la 1re circonscription du département lors des élections législatives de juillet 2024, siégeant au sein du groupe Socialistes et apparentés.",
  "karine-lebon": "Native du Port, Karine Lebon exerce la profession de professeure des écoles après des études en anthropologie. Également actrice et secrétaire générale de l'Union des femmes de La Réunion, elle est membre du parti Pour La Réunion. Elle est élue députée de la 2e circonscription de l'île en 2020 et réélue lors des scrutins législatifs de 2022 et 2024.",
  "karl-olive": "Natif de Saint-Germain-en-Laye, Karl Olive a mené une carrière de journaliste sportif et de producteur de télévision avant de diriger ses propres entreprises de communication. Maire de Poissy pendant huit ans et membre du parti Renaissance, il est une figure de la majorité présidentielle. Il est élu député des Yvelines en juin 2022 et réélu en juillet 2024.",
  "katiana-levavasseur": "Native de Rouen, Katiana Levavasseur a exercé comme agente de maintenance et de nettoyage au sein du secteur de la grande distribution. Conseillère municipale du Neubourg et membre du Rassemblement national, elle est élue députée de la 2e circonscription de l'Eure lors des élections législatives de juin 2022 et réélue lors du scrutin de juillet 2024.",
  "kevin-mauvieux": "Natif de Pont-Audemer, Kévin Mauvieux a exercé la profession de conseiller en assurance au sein du secteur privé. Conseiller municipal de sa ville natale et membre du Rassemblement national, il s'est investi sur les thématiques liées au commerce et à l'artisanat. Il est élu député de la 3e circonscription de l'Eure en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "kevin-pfeffer": "Natif de Forbach et diplômé en génie chimique, Kévin Pfeffer a exercé comme permanent politique, occupant des fonctions de directeur général et de trésorier national du RN. Conseiller municipal de Stiring-Wendel et membre du Rassemblement national, il est élu député de la 6e circonscription de la Moselle en juin 2022 et réélu lors du scrutin de juin 2024.",
  "laetitia-saint-paul": "Native de Chartres et diplômée de Saint-Cyr, Laetitia Saint-Paul est officier de l'armée de terre, ayant servi comme capitaine et commandant d'unité. Membre du parti Renaissance, elle a occupé le poste de vice-présidente de l'Assemblée nationale entre 2019 et 2022. Elle est élue députée de la 4e circonscription du Maine-et-Loire en juin 2017 et réélue depuis.",
  "laure-lavalette": "Native de Talence, Laure Lavalette s'est consacrée à son engagement politique après une expérience dans le secteur de l'assurance. Conseillère municipale de Toulon et conseillère régionale de Provence-Alpes-Côte d'Azur, elle est membre du Rassemblement national. Elle est élue députée de la 2e circonscription du Var en juin 2022 et réélue au premier tour en juin 2024.",
  "laure-miller": "Native de Reims, Laure Miller exerce la profession d'avocate au barreau de sa ville natale. Adjointe au maire de Reims pendant huit ans et membre du parti Renaissance, elle s'est investie sur les questions de justice et de territoires. Elle est élue députée de la 2e circonscription de la Marne lors d'une élection partielle en 2023 et réélue lors du scrutin de juillet 2024.",
  "laurence-robert-dehault": "Native de Saint-Dizier, Laurence Robert-Dehault a exercé comme hypnothérapeute en cabinet libéral après avoir été commerçante dans le secteur animalier. Conseillère départementale de la Haute-Marne depuis 2015 et membre du Rassemblement national, elle est élue députée de la 2e circonscription du département en juin 2022 et réélue au premier tour en juin 2024.",
  "laurent-alexandre": "Natif de Decazeville, Laurent Alexandre a effectué sa carrière comme ouvrier qualifié au sein du secteur industriel aveyronnais. Maire d'Aubin pendant plus de vingt ans et membre de La France insoumise, il s'est investi dans la défense des services publics. Il est élu député de la 2e circonscription de l'Aveyron lors des élections législatives de juin 2022 et réélu en 2024.",
  "laurent-baumel": "Natif de Charleville-Mézières et diplômé de l'École centrale de Lyon, Laurent Baumel est un cadre supérieur au sein de la Banque de France. Maire de Ballan-Miré pendant six ans et membre du Parti socialiste, il est une figure du courant des 'frondeurs'. Il est élu député d'Indre-et-Loire en 2012 et retrouve son siège à l'Assemblée nationale lors des élections de juillet 2024.",
  "laurent-croizier": "Natif de Besançon, Laurent Croizier exerce la profession de professeur des écoles, ayant également été entraîneur et directeur de centre de formation sportive. Conseiller municipal de sa ville natale et membre du MoDem, il est une figure de la majorité présidentielle dans le Doubs. Il est élu député de la 1re circonscription du département en juin 2022 et réélu en juillet 2024.",
  "laurent-jacobelli": "Natif de Thiais et diplômé de l'ESCP, Laurent Jacobelli a mené une carrière de cadre dirigeant dans l'audiovisuel, notamment chez TF1, TV5 Monde et Zodiak Kids Studios. Porte-parole national du Rassemblement national et conseiller régional du Grand Est, il s'est investi sur les questions de culture et de médias. Il est élu député de la 8e circonscription de la Moselle en juin 2022 et réélu en 2024.",
  "laurent-lhardit": "Natif de Marseille, Laurent Lhardit a exercé comme consultant en stratégies publiques et fondateur d'un cabinet d'études et de communication. Adjoint au maire de Marseille chargé de l'économie et membre du Parti socialiste, il est engagé sur les enjeux de développement urbain. Il est élu député de la 2e circonscription des Bouches-du-Rhône lors des élections législatives de juillet 2024.",
  "laurent-marcangeli": "Natif d'Ajaccio, Laurent Marcangeli exerce la profession d'avocat au barreau de sa ville natale. Maire d'Ajaccio pendant huit ans et président du groupe Horizons à l'Assemblée nationale, il a également occupé des fonctions ministérielles. Il est élu député de la 1re circonscription de la Corse-du-Sud lors des élections législatives de juin 2012 et réélu lors des scrutins de 2022 et 2024.",
  "laurent-mazaury": "Natif de Pantin, Laurent Mazaury a exercé comme cadre administratif et commercial au sein du secteur privé. Vice-président de la communauté d'agglomération de Saint-Quentin-en-Yvelines et membre de l'UDI, il est engagé dans la vie publique locale depuis 2008. Il est élu député de la 11e circonscription des Yvelines lors des élections législatives de juillet 2024.",
  "laurent-wauquiez": "Natif de Lyon et major de l'ENA, Laurent Wauquiez est maître des requêtes au Conseil d'État et agrégé d'histoire. Ancien ministre et président de la région Auvergne-Rhône-Alpes, il préside le groupe Droite républicaine à l'Assemblée nationale. Il est élu député de la 1re circonscription de la Haute-Loire en 2004 et retrouve son siège au Palais Bourbon lors des élections de juillet 2024.",
  "lea-balage-el-mariky": "Native d'Évry, Léa Balage El Mariky a exercé comme consultante et cadre administratif après avoir été collaboratrice d'élus. Adjointe au maire du 18e arrondissement de Paris et membre du parti Les Écologistes, elle s'est investie dans la justice sociale et l'écologie urbaine. Elle est élue députée de la 3e circonscription de Paris lors des élections législatives de juillet 2024.",
  "liliana-tanguy": "Native de Pancevo et diplômée de l'ESSEC, Liliana Tanguy a exercé des fonctions de cadre supérieur au sein du secteur public et de consultante experte auprès de la Commission européenne. Membre du parti Renaissance et engagée sur les enjeux européens, elle est élue députée de la 7e circonscription du Finistère lors des élections législatives de juin 2017 et réélue en 2022.",
  "lionel-causse": "Natif de Toulouse, Lionel Causse a exercé comme cadre au sein du secteur de l'économie sociale et solidaire après des études en gestion. Maire de Saint-Martin-de-Seignanx et membre de la majorité présidentielle (Renaissance), il préside le Conseil national de l'habitat. Il est élu député de la 2e circonscription des Landes lors des élections législatives de juin 2017 et réélu en 2022.",
  "lionel-duparay": "Natif de Châtenay-Malabry, Lionel Duparay exerce la profession d'ingénieur au sein du groupe industriel Alstom au Creusot. Adjoint au maire de Montceau-les-Mines et membre du parti Les Républicains, il est engagé sur les enjeux de souveraineté industrielle. Il rejoint l'Assemblée nationale en tant que député de la 5e circonscription de Saône-et-Loire en novembre 2025.",
  "lionel-tivoli": "Natif de Marseille, Lionel Tivoli a exercé comme chef d'entreprise dans le secteur privé avant son élection à l'Assemblée nationale. Conseiller régional de Provence-Alpes-Côte d'Azur et membre du Rassemblement national, il s'est investi sur les questions de sécurité et d'économie. Il est élu député de la 2e circonscription des Alpes-Maritimes en juin 2022 et réélu en juillet 2024.",
  "lionel-vuibert": "Natif de Villers-Semeuse, Lionel Vuibert a exercé comme directeur général de centres de formation industrielle (UIMM) et comme éleveur bovin. Maire de Faissault pendant quatorze ans et membre de la majorité présidentielle, il s'est investi dans l'aménagement rural. Il est élu député de la 1re circonscription des Ardennes lors des élections législatives de juin 2022.",
  "lisa-belluco": "Native de Metz et ingénieure de formation, Lisa Belluco a exercé comme inspectrice de l'environnement au sein d'une DREAL après une expérience dans le secteur de la construction. Membre du parti Les Écologistes, elle s'est investie sur les politiques de préservation de la biodiversité. Elle est élue députée de la 1re circonscription de la Vienne lors des élections législatives de juin 2022.",
  "lise-magnier": "Native de Châlons-en-Champagne, Lise Magnier a exercé comme cadre territorial au sein de collectivités locales après des études en droit public. Adjointe au maire de sa ville natale et membre du parti Horizons, elle siège à la commission des Finances de l'Assemblée nationale. Elle est élue députée de la 4e circonscription de la Marne lors des élections législatives de juin 2017 et réélue depuis.",
  "lisette-pollet": "Native de Romorantin-Lanthenay, Lisette Pollet a exercé la profession de chef d'équipe au sein du secteur du nettoyage industriel, notamment pour les groupes Elior et Sodexo. Conseillère régionale d'Auvergne-Rhône-Alpes et membre du Rassemblement national, elle s'est investie dans la défense des travailleurs précaires. Elle est élue députée de la 2e circonscription de la Drôme en juin 2022.",
  "loic-kervran": "Natif de Moulins et diplômé de Sciences Po Paris, Loïc Kervran a exercé comme cadre supérieur dans le secteur bancaire, notamment au sein de l'inspection générale du groupe HSBC. Membre du parti Horizons et spécialisé dans les questions de défense, il est élu député de la 3e circonscription du Cher lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "loic-prud-homme": "Natif de Bègles, Loïc Prud'homme a exercé la profession de technicien de recherche au sein de l'INRA, spécialisé dans l'agroécologie et les sciences du sol. Membre de La France insoumise et engagé sur les thématiques de souveraineté alimentaire, il est élu député de la 3e circonscription de la Gironde lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "louis-boyard": "Natif de Fontenay-le-Comte, Louis Boyard a mené un engagement de syndicaliste lycéen avant de devenir chroniqueur régulier dans plusieurs émissions de radio et de télévision. Membre de La France insoumise et étudiant en droit, il est l'un des plus jeunes élus de l'Assemblée nationale. Il est élu député de la 3e circonscription du Val-de-Marne en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "louise-morel": "Native de Strasbourg et diplômée de Sciences Po, Louise Morel a exercé comme consultante au sein d'un cabinet spécialisé dans le secteur agroalimentaire. Membre du MoDem et engagée sur les enjeux de renouvellement démocratique, elle est élue députée de la 6e circonscription du Bas-Rhin lors des élections législatives de juin 2022 et réélue lors du scrutin législatif de juillet 2024.",
  "ludovic-mendes": "Natif de Metz, Ludovic Mendes a exercé comme responsable commercial au sein du secteur privé puis comme gérant d'une entreprise de services. Membre du parti Renaissance et engagé sur les questions de citoyenneté, il est élu député de la 2e circonscription de la Moselle lors des élections législatives de juin 2017 et réélu lors des scrutins législatifs de 2022 et 2024.",
  "manon-bouquin": "Native d'Évreux, Manon Bouquin exerce des fonctions de cadre au sein de la fonction publique d'État. Membre du Rassemblement national et engagée sur les enjeux de souveraineté nationale, elle siège au sein du groupe RN à l'Assemblée nationale. Elle est élue députée de la 4e circonscription de l'Hérault lors des élections législatives de juillet 2024.",
  "manon-meunier": "Native de Limoges et ingénieure agronome de formation, Manon Meunier a exercé comme consultante senior spécialisée dans les politiques publiques d'emploi et de formation. Membre de La France insoumise et engagée sur les thématiques environnementales, elle est élue députée de la 3e circonscription de la Haute-Vienne lors des élections législatives de juin 2022 et réélue en 2024.",
  "marc-chavent": "Natif de Bourg-en-Bresse, Marc Chavent a exercé comme cadre administratif après avoir été collaborateur d'élus. Maire de Cerdon pendant quatre ans et membre du groupe Union des Droites pour la République (UDR), il est engagé dans la vie publique locale depuis 2020. Il est élu député de la 5e circonscription de l'Ain lors des élections législatives de juillet 2024.",
  "marc-de-fleurian": "Natif de Ploemeur et diplômé de Saint-Cyr, Marc de Fleurian est un ancien officier de la Légion étrangère ayant servi au sein de l'armée de terre. Conseiller municipal de Calais et membre du Rassemblement national, il s'est investi sur les enjeux de sécurité et de défense. Il est élu député de la 7e circonscription du Pas-de-Calais lors des élections législatives de juillet 2024.",
  "marc-ferracci": "Natif des Lilas et docteur en économie, Marc Ferracci est professeur des universités et a exercé comme conseiller spécial au sein de cabinets ministériels et à Matignon. Membre du parti Renaissance et spécialiste des politiques de l'emploi, il a été ministre délégué chargé de l'Industrie. Il est élu député des Français établis hors de France (6e circonscription) en 2022 et réélu en 2024.",
  "marc-fesneau": "Natif de Paris, Marc Fesneau a exercé comme directeur de service au sein d'une chambre d'agriculture après avoir été collaborateur d'élus. Ancien ministre de l'Agriculture et de la Souveraineté alimentaire, il est une figure majeure du MoDem. Maire de Marchenoir pendant neuf ans, il est élu député de la 1re circonscription du Loir-et-Cher en juin 2017 et réélu lors des scrutins suivants.",
  "marc-pena": "Natif de Marseille et professeur agrégé d'histoire du droit, Marc Pena a exercé comme doyen de faculté puis président de l'université Aix-Marseille-III. Conseiller municipal d'Aix-en-Provence et membre du groupe Socialistes et apparentés, il est engagé sur les enjeux d'enseignement supérieur. Il est élu député des Bouches-du-Rhône lors des élections législatives de juillet 2024.",
  "marcellin-nadeau": "Natif de Saint-Pierre, Marcellin Nadeau a exercé la profession de gestionnaire comptable au sein de l'Éducation nationale après des études de comptabilité. Maire du Prêcheur pendant quatorze ans et membre du parti Martinique Écologie, il est engagé dans la défense des territoires ultramarins. Il est élu député de la 2e circonscription de la Martinique en juin 2022 et réélu en 2024.",
  "marianne-maximi": "Native de Louviers, Marianne Maximi exerce la profession d'éducatrice spécialisée après des études dans le secteur du travail social. Conseillère municipale de Clermont-Ferrand et membre de La France insoumise, elle s'est investie dans la lutte contre les exclusions. Elle est élue députée de la 1re circonscription du Puy-de-Dôme lors des élections législatives de juin 2022 et réélue en 2024.",
  "marie-agnes-poussier-winsback": "Native de Nancy, Marie-Agnès Poussier-Winsback a exercé comme professeure d'économie après une carrière de chargée de mission en collectivité. Maire de Fécamp pendant huit ans et ancienne ministre déléguée, elle est membre du parti Horizons. Elle est élue députée de la 9e circonscription de la Seine-Maritime lors des élections législatives de juin 2022 et réélue lors du scrutin de juillet 2024.",
  "marie-charlotte-garin": "Native de Vernon, Marie-Charlotte Garin a exercé comme chargée de projet au sein de l'ONG Handicap International après avoir été collaboratrice d'élus. Directrice de cabinet en mairie et membre du parti Les Écologistes, elle s'est investie sur les enjeux de santé et de handicap. Elle est élue députée de la 3e circonscription du Rhône lors des élections législatives de juin 2022 et réélue en 2024.",
  "marie-christine-dalloz": "Native de Saint-Claude, Marie-Christine Dalloz a exercé les professions de conseillère en gestion de patrimoine et d'employée de banque avant ses mandats électifs. Maire de Martigna pendant treize ans et membre du parti Les Républicains, elle siège à la commission des Finances de l'Assemblée nationale. Elle est élue députée de la 2e circonscription du Jura en juin 2007 et réélue lors de chaque scrutin.",
  "marie-france-lorho": "Native de Colmar, Marie-France Lorho a exercé la profession de déléguée médicale au sein du secteur privé avant son engagement politique. Conseillère municipale d'Orange et membre du Rassemblement national, elle s'est investie sur les thématiques de santé et de protection sociale. Elle rejoint l'Assemblée nationale en tant que députée de la 4e circonscription du Vaucluse en juin 2017.",
  "marie-lebec": "Native de Vernon, Marie Lebec a exercé comme consultante en affaires publiques au sein d'un cabinet spécialisé après des études à Sciences Po Bordeaux. Ancienne ministre déléguée chargée des Relations avec le Parlement, elle est membre du parti Renaissance. Elle est élue députée de la 4e circonscription des Yvelines en juin 2017 et réélue lors des scrutins législatifs de 2022 et 2024.",
  "marie-mesmeur": "Native de Landerneau, Marie Mesmeur exerce la profession d'éducatrice spécialisée après des études en sociologie. Doctorante spécialisée dans la protection de l'enfance et membre de La France insoumise, elle est engagée sur les enjeux de justice sociale. Elle est élue députée de la 1re circonscription d'Ille-et-Vilaine lors des élections législatives de juillet 2024.",
  "marie-noelle-battistel": "Native de Grenoble, Marie-Noëlle Battistel a exercé des fonctions de cadre au sein du secteur privé après des études supérieures. Maire de La Salle-en-Beaumont pendant plusieurs années et membre du Parti socialiste, elle s'est investie sur les questions énergétiques. Elle est élue députée de la 4e circonscription de l'Isère lors d'une élection partielle en 2010 et réélue lors des scrutins suivants.",
  "marie-philippe-lubet": "Native d'Orléans, Marie-Philippe Lubet a exercé des fonctions de cadre au sein du ministère de l'Intérieur après une carrière administrative. Maire de Saint-Denis-en-Val et membre du parti Renaissance, elle s'est investie dans la gestion des collectivités locales et le tourisme. Elle rejoint l'Assemblée nationale en tant que députée du Loiret en février 2026, siégeant au sein du groupe EPR.",
  "marie-pierre-rixain": "Native de Saint-Cyr-l'École, Marie-Pierre Rixain a exercé comme consultante indépendante en communication publique et professeure à l'ISCOM après des études à Sciences Po Toulouse. Membre du parti Renaissance et engagée sur les droits des femmes, elle préside la délégation aux droits des femmes de l'Assemblée nationale. Elle est élue députée de l'Essonne lors des élections de juin 2017 et réélue depuis.",
  "marie-pochon": "Native de Grenoble, Marie Pochon a exercé des fonctions de responsable associative et de collaboratrice parlementaire après des études en relations internationales. Militante écologiste et membre du parti Les Écologistes, elle s'est investie sur les enjeux de transition agroécologique. Elle est élue députée de la 3e circonscription de la Drôme lors des élections législatives de juin 2022 et réélue en 2024.",
  "marie-recalde": "Native de Langon, Marie Récalde exerce la profession d'avocate au barreau de Bordeaux, spécialisée dans le droit public et l'aménagement du territoire. Adjointe au maire de Mérignac pendant seize ans et membre du Parti socialiste, elle est engagée sur les enjeux de défense. Elle est élue députée de la 6e circonscription de la Gironde lors des élections législatives de juin 2012 et réélue en 2024.",
  "marietta-karamanli": "Native d'Athènes et diplômée de l'université, Marietta Karamanli exerce la profession de professeure après une carrière dans l'enseignement et l'administration d'État. Adjointe au maire du Mans pendant dix-huit ans et membre du Parti socialiste, elle est spécialisée dans les questions de justice et d'affaires européennes. Elle est élue députée de la Sarthe en juin 2007 et réélue lors de chaque scrutin législatif.",
  "marine-hamelet": "Native de Savigny-sur-Orge, Marine Hamelet a exercé comme commerciale après l'obtention d'un BTS en commerce international, puis comme assistante maternelle. Membre du Rassemblement national, elle s'est investie dans la vie publique locale en Occitanie. Elle est élue députée de la 2e circonscription de Tarn-et-Garonne lors des élections législatives de juin 2022 et réélue en juin 2024.",
  "marine-le-pen": "Native de Neuilly-sur-Seine, Marine Le Pen exerce la profession d'avocate au barreau de Paris après des études de droit. Ancienne directrice du service juridique du Front national et députée européenne pendant treize ans, elle préside le groupe Rassemblement national à l'Assemblée nationale. Elle est élue députée de la 11e circonscription du Pas-de-Calais en juin 2017 et réélue au premier tour en 2024.",
  "martine-froger": "Native de Blois, Martine Froger a mené une carrière de cheffe d'entreprise, notamment dans le secteur de l'insertion par l'activité économique. Membre du groupe Libertés, Indépendants, Outre-mer et Territoires (LIOT), elle est engagée sur les enjeux de ruralité et de solidarité. Elle est élue députée de la 1re circonscription de l'Ariège lors d'une élection partielle en avril 2023 et réélue en 2024.",
  "mathilde-feld": "Native de Rueil-Malmaison, Mathilde Feld a exercé comme consultante spécialisée dans l'évaluation des politiques publiques d'emploi et de formation. Ancienne présidente de communauté de communes et membre de La France insoumise, elle est engagée sur les enjeux de développement territorial. Elle est élue députée de la 12e circonscription de la Gironde lors des élections législatives de juillet 2024.",
  "mathilde-hignet": "Native de Rennes, Mathilde Hignet a exercé la profession d'ouvrière agricole, notamment dans le secteur de l'agriculture biologique. Membre de La France insoumise, elle porte les thématiques liées au monde paysan et aux conditions de travail à l'Assemblée nationale. Elle est élue députée de la 4e circonscription d'Ille-et-Vilaine lors des élections législatives de juin 2022 et réélue en 2024.",
  "mathilde-panot": "Native de Tours et diplômée de Sciences Po Paris, Mathilde Panot a exercé comme coordinatrice de projets associatifs au sein de l'association VoisinMalin. Présidente du groupe La France insoumise à l'Assemblée nationale, elle est engagée sur les questions d'écologie populaire et de logement. Elle est élue députée de la 10e circonscription du Val-de-Marne en juin 2017 et réélue depuis.",
  "matthias-renault": "Natif de Villeurbanne et diplômé de l'ENA, Matthias Renault est magistrat à la Cour des comptes après une carrière au sein de la haute administration française. Membre du Rassemblement national, il s'est investi sur les questions de finances publiques et de souveraineté économique. Il est élu député de la 3e circonscription de la Somme lors des élections législatives de juillet 2024.",
  "matthias-tavel": "Natif de Villeurbanne, Matthias Tavel a exercé comme cadre de la fonction publique d'État après des études à Sciences Po. Ancien collaborateur parlementaire et membre de La France insoumise, il s'est investi sur les questions de planification écologique et d'industrie. Il est élu député de la 8e circonscription de la Loire-Atlantique lors des élections législatives de juin 2022 et réélu en 2024.",
  "matthieu-bloch": "Natif d'Audincourt, Matthieu Bloch a exercé comme cadre administratif au sein du secteur privé. Maire de Colombier-Fontaine et membre du groupe Union des Droites pour la République (UDR), il est engagé dans la vie publique locale depuis plusieurs années. Il est élu député de la 3e circonscription du Doubs lors des élections législatives de juillet 2024, siégeant au sein du groupe RN.",
  "matthieu-marchio": "Natif de Dieppe, Matthieu Marchio a exercé comme cadre administratif et commercial au sein du secteur privé. Conseiller municipal de Somain et membre du Rassemblement national, il s'est investi sur les thématiques liées à la désindustrialisation et aux services publics. Il est élu député de la 16e circonscription du Nord en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "maud-petit": "Native de Paris, Maud Petit a exercé les fonctions de chargée de ressources humaines au sein de grands groupes du secteur privé, notamment dans l'agroalimentaire. Membre du MoDem et engagée sur les enjeux de protection de l'enfance et de sport, elle est élue députée de la 4e circonscription du Val-de-Marne lors des élections législatives de juin 2017 et réélue depuis.",
  "maxime-amblard": "Natif de L'Isle-d'Espagnac et ingénieur de formation, Maxime Amblard a exercé comme consultant en ingénierie au sein du secteur privé. Engagé au sein du Rassemblement national, il s'est investi sur les thématiques de l'industrie et de l'énergie. Il est élu député de la 1re circonscription de la Meuse lors des élections législatives de juillet 2024, siégeant au sein du groupe RN.",
  "maxime-laisney": "Natif de Lisieux, Maxime Laisney exerce la profession de professeur des écoles, ayant notamment travaillé auprès d'enfants issus de milieux défavorisés. Membre de La France insoumise et engagé sur les questions d'éducation et de services publics, il est élu député de la 10e circonscription de Seine-et-Marne en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "maxime-meffre": "Natif de Carpentras, Maxime Meffre a exercé la profession de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique du Vaucluse. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "maxime-minot": "Natif de Clermont, Maxime Minot a exercé comme cadre au sein de la fonction publique territoriale après avoir été agent de la SNCF. Maire d'Etouy pendant huit ans et membre du parti Les Républicains, il est engagé sur les thématiques de jeunesse et de vie associative. Il est élu député de la 7e circonscription de l'Oise en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "meriem-derkaoui": "Native de Bougaâ (Algérie), Meriem Derkaoui exerce la profession de cadre au sein de la fonction publique territoriale après des études en droit. Maire d'Aubervilliers pendant quatre ans et membre du Parti communiste français, elle est engagée sur les enjeux de justice sociale et de solidarité urbaine. Elle est élue députée de la Seine-Saint-Denis lors des élections législatives de juillet 2024.",
  "meyer-habib": "Natif de Paris et diplômé en ingénierie, Meyer Habib a mené une carrière de chef d'entreprise dans le secteur de la joaillerie et du conseil avant son engagement public. Membre du groupe Droite républicaine et spécialisé dans les questions de défense et de relations internationales, il est élu député des Français établis hors de France (8e circonscription) sans interruption depuis 2013.",
  "michel-herbillon": "Natif de Saint-Mandé, Michel Herbillon a exercé des fonctions de cadre au sein du secteur privé après ses études supérieures. Maire de Maisons-Alfort pendant vingt-cinq ans et membre du parti Les Républicains, il est spécialisé dans les questions de diplomatie et d'affaires étrangères. Il est élu député de la 8e circonscription du Val-de-Marne sans interruption depuis juin 1997.",
  "michel-lauzzana": "Natif de Tarbes et diplômé en médecine, Michel Lauzzana exerce la profession de médecin généraliste. Maire de Bon-Encontre pendant seize ans et membre du parti Renaissance, il est engagé sur les enjeux de santé publique et d'organisation des soins. Il est élu député de la 1re circonscription du Lot-et-Garonne en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "michel-sala": "Natif de Paris, Michel Sala a exercé comme cadre administratif et commercial au sein du secteur privé après avoir mené un engagement associatif. Maire de Saint-Félix-de-Pallières et membre de La France insoumise, il s'est investi dans la défense des territoires ruraux et des services publics. Il est élu député de la 5e circonscription du Gard lors des élections législatives de juin 2022.",
  "michele-tabarot": "Native d'Alicante (Espagne), Michèle Tabarot a exercé des fonctions de cadre au sein du secteur privé avant de se consacrer à ses mandats locaux. Maire du Cannet pendant dix-sept ans et membre du parti Les Républicains, elle a présidé la commission des Affaires culturelles de l'Assemblée nationale. Elle est élue députée de la 9e circonscription des Alpes-Maritimes sans interruption depuis juin 2002.",
  "mickael-bouloux": "Natif de Rennes et ingénieur de formation, Mickaël Bouloux a exercé comme cadre au sein du groupe Orange après avoir servi dans l'enseignement et la recherche. Maire du Rheu et membre du Parti socialiste, il est engagé sur les thématiques de développement numérique et de solidarité territoriale. Il est élu député de la 8e circonscription d'Ille-et-Vilaine lors des élections législatives de juin 2022.",
  "mickael-cosson": "Natif de Saint-Brieuc, Mickaël Cosson a exercé la profession de cadre au sein de la fonction publique territoriale après une carrière dans le secteur privé. Maire de Hillion et membre du parti MoDem, il s'est investi sur les thématiques de protection du littoral et d'aménagement du territoire. Il est élu député de la 1re circonscription des Côtes-d'Armor lors des élections législatives de juin 2022.",
  "mireille-clapot": "Native de Belley et diplômée d'HEC, Mireille Clapot a mené une carrière de cadre dirigeante dans le secteur industriel et technologique, notamment chez Renault et Alstom. Membre du parti Renaissance et spécialisée dans les thématiques de droits humains et de diplomatie parlementaire, elle est élue députée de la 1re circonscription de la Drôme en juin 2017 et réélue en 2022.",
  "monique-iborra": "Native de Maison-Carrée (Algérie), Monique Iborra a exercé comme cadre au sein de la fonction publique après des études supérieures. Membre du parti Renaissance et spécialisée dans les enjeux de formation professionnelle et de solidarité, elle s'est investie dans la vie publique de Haute-Garonne. Elle est élue députée de la 6e circonscription du département en juin 2007 et réélue depuis lors.",
  "morgane-monnet": "Native de Lyon, Morgane Monnet a exercé comme cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique du Rhône. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "mounir-belhamiti": "Natif de Nantes et ingénieur de formation, Mounir Belhamiti a mené une carrière de cadre au sein du secteur technologique et de l'innovation après ses études supérieures. Membre du parti Renaissance et conseiller municipal de Nantes, il est engagé sur les enjeux de souveraineté numérique et d'industrie. Il est élu député de la 1re circonscription de Loire-Atlantique lors des législatives de juin 2022.",
  "mya-bollaers": "Native de Bruxelles (Belgique), Mya Bollaers a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de solidarité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "nadege-abomangoli": "Native de Brazzaville (Congo) et diplômée de Sciences Po Paris, Nadège Abomangoli a exercé comme cadre au sein de la fonction publique territoriale après une carrière associative. Vice-présidente de l'Assemblée nationale et membre de La France insoumise, elle est spécialisée dans les politiques sociales. Elle est élue députée de la 10e circonscription de la Seine-Saint-Denis en juin 2022 et réélue en 2024.",
  "nadia-hai": "Native de Trappes, Nadia Hai a mené une carrière de cadre dirigeante dans le secteur bancaire, notamment chez Barclays et HSBC, avant d'être ministre déléguée chargée de la Ville. Membre du parti Renaissance, elle est spécialisée dans les enjeux de cohésion sociale et de travail. Elle est élue députée des Yvelines en juin 2017 et réélue dans les Hauts-de-Seine lors du scrutin de juin 2022.",
  "naima-moutchou": "Native d'Ermont, Naïma Moutchou exerce la profession d'avocate au barreau de Paris après des études supérieures en droit. Vice-présidente de l'Assemblée nationale et membre du parti Horizons, elle est spécialisée dans les thématiques de justice et de libertés publiques. Elle est élue députée de la 4e circonscription du Val-d'Oise en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "nathalie-bassire": "Native de Saint-Pierre, Nathalie Bassire a exercé comme cadre administratif au sein de la fonction publique territoriale après des études supérieures. Conseillère régionale de La Réunion et membre du groupe LIOT, elle est engagée sur les thématiques d'aménagement du territoire et de solidarité insulaire. Elle est élue députée de la 3e circonscription de l'île en juin 2017 et réélue lors du scrutin de juin 2022.",
  "nathalie-da-conceicao-carvalho": "Native de Blois, Nathalie Da Conceicao Carvalho a mené une carrière de cadre au sein du secteur privé, notamment dans le domaine du commerce et de la gestion. Membre du Rassemblement national et engagée dans la vie publique de l'Essonne, elle s'est investie sur les thématiques de proximité et de défense des services publics. Elle est élue députée de la 2e circonscription du département en juin 2022.",
  "nathalie-delattre": "Native d'Aubervilliers, Nathalie Delattre a mené une carrière de viticultrice et de cheffe d'entreprise après des études supérieures. Ministre déléguée chargée des Relations avec le Parlement et membre du Parti radical, elle est spécialisée dans les questions institutionnelles. Elle est élue sénatrice de la Gironde en 2017 et rejoint l'Assemblée nationale lors des élections de juillet 2024.",
  "nathalie-oziol": "Native de Nîmes et agrégée d'anglais, Nathalie Oziol a exercé comme enseignante au sein du secondaire et du supérieur après ses études à l'ENS. Membre de La France insoumise et engagée sur les thématiques d'éducation et de diplomatie, elle s'est investie dans la vie publique de l'Hérault. Elle est élue députée de la 2e circonscription du département en juin 2022 et réélue au premier tour en 2024.",
  "nathalie-porte": "Native de Caen, Nathalie Porte a exercé comme cadre administratif au sein de la fonction publique territoriale après une carrière dans le secteur privé. Membre du groupe Droite républicaine et conseillère régionale de Normandie, elle s'est investie sur les thématiques de proximité et de développement local. Elle rejoint l'Assemblée nationale en tant que députée du Calvados en octobre 2020.",
  "nathalie-serre": "Native de Lyon, Nathalie Serre a mené une carrière de cadre au sein du secteur privé, spécialisée dans les domaines de la gestion et de l'administration des entreprises. Membre du parti Les Républicains et engagée dans la vie publique du Rhône, elle s'est investie sur les enjeux d'éducation et de solidarité. Elle rejoint l'Assemblée nationale en tant que députée de la 8e circonscription du département en juin 2020.",
  "nicolas-dupont-aignan": "Natif de Paris et diplômé de l'ENA, Nicolas Dupont-Aignan est un haut fonctionnaire ayant servi comme sous-préfet avant de présider le parti Debout la France. Maire d'Yerres pendant vingt-deux ans et spécialisé dans les thématiques de souveraineté et d'indépendance nationale, il s'est investi dans la vie publique de l'Essonne. Il est élu député de la 8e circonscription du département sans interruption depuis juin 1997.",
  "nicolas-forissier": "Natif de Paris et diplômé en droit, Nicolas Forissier a mené une carrière de chef d'entreprise avant d'occuper les fonctions de secrétaire d'État à l'Agriculture. Maire de La Châtre pendant vingt-deux ans et membre du parti Les Républicains, il est spécialisé dans les enjeux ruraux et économiques. Il est élu député de la 2e circonscription de l'Indre en juin 1993 et réélu lors des scrutins de 2017 et 2022.",
  "nicolas-meizonnet": "Natif de Nîmes, Nicolas Meizonnet exerce la profession d'ingénieur en informatique après des études supérieures techniques. Membre du Rassemblement national et conseiller départemental du Gard, il s'est investi sur les thématiques de sécurité et de défense des traditions locales. Il rejoint l'Assemblée nationale en tant que député de la 2e circonscription du département en février 2020.",
  "nicolas-metzdorf": "Natif de Nouméa et ingénieur agronome de formation, Nicolas Metzdorf a exercé comme cadre au sein de l'administration calédonienne. Membre du parti Renaissance et ancien président de la province Sud, il porte les enjeux de souveraineté et de développement du territoire à l'Assemblée. Il est élu député de la 2e circonscription de Nouvelle-Calédonie en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "nicolas-ray": "Natif de Clermont-Ferrand et diplômé de l'ENA, Nicolas Ray est un haut fonctionnaire ayant exercé comme magistrat à la Cour des comptes. Membre du groupe Droite républicaine et engagé sur les thématiques de finances publiques et de soutien aux territoires ruraux, il s'est investi dans la vie publique de l'Allier. Il est élu député de la 3e circonscription du département lors des élections législatives de juin 2022.",
  "nicolas-sansu": "Natif de Vierzon, Nicolas Sansu a exercé comme cadre au sein de la fonction publique territoriale après des études en économie et droit. Maire de Vierzon pendant dix ans et membre du Parti communiste français, il est spécialisé dans les enjeux d'aménagement du territoire et de services publics. Il est élu député du Cher en juin 2012 et retrouve son siège à l'Assemblée lors du scrutin de juin 2022.",
  "nicolas-thierry": "Natif de Bordeaux et diplômé en environnement, Nicolas Thierry a mené une carrière de cadre et consultant spécialisé dans les thématiques écologiques. Vice-président de la région Nouvelle-Aquitaine et membre du parti Les Écologistes, il est engagé sur les enjeux de protection de la biodiversité et de santé publique. Il est élu député de la 2e circonscription de la Gironde lors des législatives de juin 2022.",
  "nicole-dubré-chirat": "Native de Rabat (Maroc), Nicole Dubré-Chirat a exercé la profession de cadre de santé et de directrice d'IFSI après une carrière d'infirmière. Membre du parti Renaissance et engagée sur les enjeux de santé et de protection sociale, elle s'est investie dans la vie publique de Maine-et-Loire. Elle est élue députée de la 6e circonscription du département en juin 2017 et réélue lors du scrutin de juin 2022.",
  "olivia-gregoire": "Native de Paris et diplômée de Sciences Po Paris et de l'ESSEC, Olivia Grégoire a mené une carrière de cadre dirigeante et cheffe d'entreprise dans le secteur du conseil. Ancienne ministre déléguée chargée des Entreprises, du Tourisme et de la Consommation, elle est membre du parti Renaissance. Elle est élue députée de la 12e circonscription de Paris en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "olivier-becht": "Natif de Mulhouse et diplômé de l'ENA, Olivier Becht est un magistrat administratif ayant exercé comme diplomate avant d'être ministre délégué chargé du Commerce extérieur. Membre du parti Renaissance et ancien maire de Rixheim, il est spécialisé dans les questions d'attractivité économique. Il est élu député du Haut-Rhin en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "olivier-faure": "Natif de La Guiche et diplômé en droit, Olivier Faure a exercé comme cadre au sein du Parti socialiste et comme collaborateur de cabinet ministériel après ses études. Premier secrétaire du PS et président du groupe à l'Assemblée nationale entre 2016 et 2018, il est une figure centrale de la gauche. Il est élu député de la 11e circonscription de Seine-et-Marne sans interruption depuis juin 2012.",
  "olivier-marleix": "Natif de Paris, Olivier Marleix a exercé comme cadre administratif et de cabinet après ses études supérieures. Maire d'Anet pendant neuf ans et membre du parti Les Républicains, il a présidé le groupe à l'Assemblée nationale entre 2022 et 2024. Il est élu député de la 2e circonscription d'Eure-et-Loir sans interruption depuis juin 2012, spécialisé dans les questions industrielles et de souveraineté.",
  "olivier-serva": "Natif de Pointe-à-Pitre et expert-comptable de profession, Olivier Serva a dirigé son propre cabinet avant son engagement politique national. Membre du groupe LIOT et engagé sur les thématiques de développement économique des outre-mer et de continuité territoriale, il s'est investi dans la vie publique de Guadeloupe. Il est élu député de la 1re circonscription du département en juin 2017 et réélu depuis lors.",
  "pascale-martin": "Native de Toulouse, Pascale Martin a exercé comme cadre administrative après avoir été employée de banque et militante syndicale. Membre de La France insoumise et engagée sur les thématiques de droits des femmes et de défense des services publics, elle s'est investie dans la vie publique de la Dordogne. Elle est élue députée de la 1re circonscription du département lors des élections législatives de juin 2022.",
  "pascale-bordes": "Native de Nîmes, Pascale Bordes exerce la profession d'avocate au barreau de sa ville natale après des études supérieures en droit. Membre du Rassemblement national et engagée sur les thématiques de justice et de sécurité publique, elle s'est investie dans la vie publique du Gard. Elle est élue députée de la 3e circonscription du département lors des élections législatives de juin 2022 et réélue en 2024.",
  "patrice-vergriete": "Natif de Dunkerque et diplômé de l'École Polytechnique et de l'ENGREF, Patrice Vergriete est un ingénieur en chef des ponts et chaussées ayant servi comme ministre des Transports. Maire de Dunkerque depuis 2014 et membre de la majorité présidentielle, il est spécialisé dans les enjeux d'aménagement urbain. Il rejoint l'Assemblée nationale lors des élections législatives de juillet 2024.",
  "patrick-hetzel": "Natif de Phalsbourg et agrégé en sciences de gestion, Patrick Hetzel est professeur des universités et a exercé comme recteur d'académie et directeur général de l'enseignement supérieur. Ministre de l'Enseignement supérieur et de la Recherche et membre du parti Les Républicains, il est spécialisé dans les enjeux d'innovation. Il est élu député du Bas-Rhin sans interruption depuis juin 2012.",
  "patrick-vignal": "Natif de Montpellier, Patrick Vignal a mené une carrière de chef d'entreprise dans le secteur du sport et de la remise en forme après avoir été champion de judo. Membre du parti Renaissance et engagé sur les thématiques de citoyenneté et de cohésion sociale, il s'est investi dans la vie publique de l'Hérault. Il est élu député de la 9e circonscription du département en juin 2012 et réélu lors des scrutins suivants.",
  "paul-andre-colombani": "Natif de Bastia et docteur en médecine, Paul-André Colombani exerce la profession de médecin généraliste. Membre du parti Pà Corsica et du groupe LIOT, il porte les thématiques liées au statut de la Corse et à la défense des territoires insulaires à l'Assemblée. Il est élu député de la 2e circonscription de la Corse-du-Sud lors des élections législatives de juin 2017 et réélu en 2022 et 2024.",
  "paul-christophe": "Natif des Sables-d'Olonne, Paul Christophe a exercé comme cadre au sein de la fonction publique territoriale après des études supérieures. Maire de Zuydcoote pendant neuf ans et membre du parti Horizons, il préside la commission des Affaires sociales de l'Assemblée nationale. Il est élu député de la 14e circonscription du Nord lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "paul-midy": "Natif de Fontainebleau et diplômé de l'École Polytechnique, Paul Midy a mené une carrière de cadre dirigeant et entrepreneur dans le secteur technologique, notamment chez Jumia et McKinsey. Membre du parti Renaissance et spécialisé dans les enjeux d'innovation et de soutien aux start-ups, il est élu député de la 5e circonscription de l'Essonne en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "paul-molac": "Natif de Ploërmel, Paul Molac a exercé la profession de professeur d'histoire-géographie et de breton au sein de l'Éducation nationale après ses études. Membre du groupe LIOT et engagé sur les thématiques de défense des langues régionales et de décentralisation, il s'est investi dans la vie publique du Morbihan. Il est élu député de la 4e circonscription du département sans interruption depuis juin 2012.",
  "paul-vannier": "Natif de Paris et agrégé de géographie, Paul Vannier a exercé comme enseignant dans le secondaire après des études supérieures à l'ENS. Membre de La France insoumise et responsable des questions d'éducation au sein du mouvement, il est engagé sur les thématiques de justice scolaire. Il est élu député de la 5e circonscription du Val-d'Oise lors des élections législatives de juin 2022 et réélu en 2024.",
  "paulette-guinchard": "Native de Reugney, Paulette Guinchard a exercé comme infirmière psychiatrique avant d'occuper les fonctions de secrétaire d'État aux Personnes âgées. Ancienne députée du Doubs et vice-présidente de l'Assemblée nationale, elle est une figure du Parti socialiste engagée sur les enjeux de l'autonomie et du grand âge. Elle a marqué la vie publique nationale par la création de l'APA.",
  "perrine-goulet": "Native de Nevers, Perrine Goulet a mené une carrière de cadre au sein de l'entreprise EDF, spécialisée dans les domaines financiers et de gestion, après ses études supérieures. Membre du MoDem et engagée sur les thématiques de protection de l'enfance et de finances publiques, elle est élue députée de la 1re circonscription de la Nièvre lors des élections législatives de juin 2017 et réélue depuis.",
  "philippe-brun": "Natif de Rouen et diplômé de l'ENA, Philippe Brun est magistrat administratif après avoir exercé comme haut fonctionnaire. Membre du Parti socialiste et engagé sur les thématiques de souveraineté industrielle et de défense des services publics, il s'est investi dans la vie publique de l'Eure. Il est élu député de la 4e circonscription du département lors des élections législatives de juin 2022 et réélu en 2024.",
  "philippe-emanuelli": "Natif de Marseille, Philippe Emanuelli a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "philippe-folliot": "Natif d'Albi et diplômé de l'IEP de Toulouse, Philippe Folliot a exercé comme cadre au sein du secteur bancaire après avoir dirigé une structure de développement économique. Fondateur de l'Alliance centriste et membre du groupe LIOT, il est spécialisé dans les questions de défense et d'outre-mer. Il est élu député du Tarn en juin 2002 et réélu lors de chaque scrutin législatif suivant.",
  "philippe-gosselin": "Natif de Carentan, Philippe Gosselin exerce la profession de maître de conférences à l'université après des études à Sciences Po et en droit. Maire de Remilly-sur-Lozon pendant vingt-deux ans et membre du parti Les Républicains, il est spécialisé dans les enjeux institutionnels et de libertés publiques. Il est élu député de la 1re circonscription de la Manche sans interruption depuis juin 2007.",
  "philippe-guillemard": "Natif de Nancy, Philippe Guillemard exerce la profession d'avocat au barreau de sa ville natale, spécialisé dans le droit des affaires. Membre du parti Renaissance et engagé sur les thématiques de soutien aux entreprises et de justice, il s'est investi dans la vie publique de Meurthe-et-Moselle. Il est élu député de la 1re circonscription du département lors d'une élection partielle en 2022.",
  "philippe-juvin": "Natif d'Orléans et docteur en médecine, Philippe Juvin est professeur de médecine et chef du service des urgences de l'hôpital Georges-Pompidou. Maire de La Garenne-Colombes depuis 2001 et membre du parti Les Républicains, il a également été député européen. Il est élu député de la 3e circonscription des Hauts-de-Seine lors des élections législatives de juin 2022 et réélu en 2024.",
  "philippe-latombe": "Né à Paris, Philippe Latombe a commencé sa carrière comme auditeur financier chez Deloitte Touche Tohmatsu à Nantes. Il a ensuite rejoint le Crédit Agricole Atlantique-Vendée, où il a occupé le poste de responsable du service recouvrement et contentieux de septembre 2014 à mai 2017. Parallèlement, il a exercé des responsabilités syndicales au sein de la CFE-CGC. Élu député de la Vendée en 2017, il siège également à la CNIL.",
  "philippe-lottiaux": "Natif de Vincennes et diplômé de l'ENA, Philippe Lottiaux est un haut fonctionnaire ayant exercé comme directeur général des services de grandes collectivités locales. Membre du Rassemblement national et engagé sur les thématiques de gestion publique et de culture, il s'est investi dans la vie publique du Var. Il est élu député de la 4e circonscription du département lors des élections législatives de juin 2022 et réélu en 2024.",
  "philippe-naillet": "Natif de Saint-Denis de La Réunion, Philippe Naillet a exercé comme cadre administratif au sein de la fonction publique territoriale après des études supérieures. Membre du Parti socialiste et engagé sur les thématiques de logement social et de développement urbain, il s'est investi dans la vie publique de l'île. Il devient député de La Réunion en 2020 et est élu en son nom propre lors du scrutin de juin 2022.",
  "philippe-schreck": "Natif de Draguignan, Philippe Schreck exerce la profession d'avocat au barreau de sa ville natale après des études supérieures en droit. Membre du Rassemblement national et engagé sur les thématiques de justice et de sécurité publique, il s'est investi dans la vie publique du Var. Il est élu député de la 8e circonscription du département lors des élections législatives de juin 2022 et réélu en 2024.",
  "philippe-vigier": "Natif de Valence et docteur en pharmacie, Philippe Vigier a dirigé plusieurs laboratoires d'analyses médicales avant d'être ministre délégué chargé des Outre-mer. Membre du MoDem et ancien maire de Cloyes-sur-le-Loir, il est spécialisé dans les enjeux de santé et de territoires. Il est élu député d'Eure-et-Loir sans interruption depuis juin 2007 et réélu lors des scrutins de 2022 et 2024.",
  "philippine-laniesse": "Native de Paris, Philippine Laniesse a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de l'Essonne en octobre 2024.",
  "pierre-andré-perissol": "Natif de Nice et diplômé de l'École Polytechnique, Pierre-André Périssol est un haut fonctionnaire et chef d'entreprise ayant servi comme ministre du Logement. Maire de Moulins pendant vingt-quatre ans et membre du parti Les Républicains, il est spécialisé dans les enjeux d'aménagement urbain. Il est élu député de l'Allier en juin 1993 et retrouve un rôle national majeur au sein de son parti.",
  "pierre-cazeneuve": "Natif de Senlis et diplômé de Sciences Po Paris, Pierre Cazeneuve a exercé comme conseiller technique à l'Élysée après avoir mené un engagement de premier plan au sein de la jeunesse de la majorité. Membre du parti Renaissance et engagé sur les enjeux institutionnels et de transition écologique, il est élu député de la 7e circonscription des Hauts-de-Seine lors des élections législatives de juin 2022.",
  "pierre-cordier": "Natif de Charleville-Mézières, Pierre Cordier a exercé comme cadre au sein de la fonction publique territoriale après avoir été collaborateur parlementaire. Maire de Neufmanil pendant seize ans et membre du groupe Droite républicaine, il est engagé sur les thématiques de proximité et de défense de la ruralité. Il est élu député de la 2e circonscription des Ardennes en juin 2017 et réélu en 2022 et 2024.",
  "pierre-henri-dumont": "Natif de Grande-Synthe et diplômé de Sciences Po Paris, Pierre-Henri Dumont a exercé comme collaborateur parlementaire avant de se consacrer à la vie publique. Maire de Marck pendant trois ans et membre du parti Les Républicains, il est spécialisé dans les enjeux de sécurité et de gestion des frontières. Il est élu député de la 7e circonscription du Pas-de-Calais en juin 2017 et réélu lors du scrutin de 2022.",
  "pierre-huguet": "Natif de Paris, Pierre Huguet a exercé comme cadre au sein de la haute administration après des études supérieures en droit public. Membre du groupe Ensemble pour la République et engagé sur les thématiques institutionnelles et de gestion publique, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de la 1re circonscription des Yvelines en octobre 2024.",
  "pierre-marle": "Originaire de Bollezeele, Pierre Marle a effectué sa carrière dans l'enseignement primaire en tant que professeur puis directeur d'école. Il s'engage dans la vie municipale en 2014 en devenant maire de sa commune de naissance. Suppléant de Paul Christophe lors des législatives, il entre à l'Assemblée nationale pour le remplacer. Il siège au sein du groupe Horizons & Indépendants.",
  "pierre-meurin": "Natif de Paris, Pierre Meurin a exercé comme cadre administratif et responsable de la communication politique après des études supérieures. Membre du Rassemblement national et engagé sur les thématiques de souveraineté nationale et de protection de la famille, il s'est investi dans la vie publique du Gard. Il est élu député de la 4e circonscription du département lors des élections législatives de juin 2022.",
  "pierre-morel-a-l-huissier": "Natif de Strasbourg, Pierre Morel-À-L'Huissier exerce la profession d'avocat après des études supérieures en droit public. Maire de Fournels pendant dix-huit ans et membre du groupe LIOT, il est spécialisé dans les questions de défense des territoires ruraux et de justice. Il est élu député de la Lozère sans interruption depuis juin 2002 et siège jusqu'en juin 2024.",
  "pierre-oudenot": "Natif de Paris, Pierre Oudenot a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de Seine-et-Marne en octobre 2024.",
  "pierre-prieur": "Natif de Paris, Pierre Prieur a exercé la profession de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique du Val-d'Oise. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "pierre-yves-bournazel": "Natif de Riom et diplômé de Sciences Po Paris, Pierre-Yves Bournazel a exercé comme consultant en communication avant de se consacrer à ses mandats parisiens. Conseiller de Paris et membre du parti Horizons, il est engagé sur les thématiques de culture et d'aménagement urbain. Il est élu député de la 18e circonscription de Paris en juin 2017 et réélu lors du scrutin législatif de juillet 2024.",
  "prisca-thevenot": "Native de Strasbourg et diplômée de l'EM Lyon, Prisca Thevenot a mené une carrière de cadre dirigeante et cheffe d'entreprise dans le secteur du conseil avant d'être porte-parole du gouvernement. Membre du parti Renaissance et ancienne secrétaire d'État à la Jeunesse, elle est spécialisée dans les enjeux civiques. Elle est élue députée des Hauts-de-Seine en juin 2022 et réélue en juillet 2024.",
  "quentyn-muller": "Natif de Strasbourg, Quentyn Müller a exercé des fonctions de cadre au sein de la haute administration après des études supérieures en droit public. Membre du groupe Ensemble pour la République et engagé sur les thématiques de gestion publique et de proximité, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député du Bas-Rhin en octobre 2024.",
  "rachel-keke": "Native d'Abobo (Côte d'Ivoire), Rachel Keke a exercé la profession de femme de chambre après avoir mené une lutte syndicale historique de deux ans contre un grand groupe hôtelier. Membre de La France insoumise et figure de l'écologie sociale, elle porte la voix des travailleurs invisibles à l'Assemblée. Elle est élue députée de la 7e circonscription du Val-de-Marne lors des élections législatives de juin 2022.",
  "ramona-fischer": "Native de Bucarest (Roumanie), Ramona Fischer a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Écologiste et Social et engagée sur les enjeux de solidarité et de transition écologique, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "raphael-arnault": "Natif de Lyon, Raphaël Arnault a exercé comme cadre administratif après avoir mené un engagement associatif de terrain contre l'extrême droite. Cofondateur du mouvement La Jeune Garde et membre de La France insoumise, il est engagé sur les thématiques de lutte contre les discriminations et de justice sociale. Il est élu député de la 1re circonscription du Vaucluse lors des élections législatives de juillet 2024.",
  "raphael-gerard": "Natif de Saint-Malo, Raphaël Gérard a mené une carrière de cadre dans le secteur culturel, notamment comme responsable du patrimoine au sein du groupe LVMH. Membre du parti Renaissance et engagé sur les enjeux de lutte contre les LGBTI-phobies et de protection du patrimoine, il est élu député de la 4e circonscription de la Charente-Maritime en juin 2017 et réélu lors du scrutin de 2022.",
  "raphael-glucksmann": "Natif de Boulogne-Billancourt et diplômé de Sciences Po Paris, Raphaël Glucksmann est un essayiste et réalisateur ayant cofondé le parti Place publique. Député européen et figure de la gauche sociale-démocrate, il est spécialisé dans les enjeux de défense des droits humains et de souveraineté européenne. Il rejoint l'Assemblée nationale lors des élections législatives de juillet 2024, siégeant au groupe Socialistes.",
  "raquel-garrido": "Native de Valparaíso (Chili) et avocate au barreau de Paris, Raquel Garrido a exercé comme cadre au sein de structures syndicales et politiques avant ses études de droit. Porte-parole historique de La France insoumise et chroniqueuse médiatique, elle est engagée sur les enjeux institutionnels et de justice sociale. Elle est élue députée de la 5e circonscription de la Seine-Saint-Denis lors des élections législatives de juin 2022.",
  "remi-favennec": "Natif de Laval, Rémi Favennec a exercé comme cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique de la Mayenne. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "remi-le-lous": "Natif de Paris, Rémi Le Lous a mené une carrière de cadre dirigeant dans le secteur privé après des études supérieures en gestion. Membre du groupe Ensemble pour la République et engagé sur les enjeux de développement économique local et de proximité, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "rené-dosière": "Natif d'Origny-en-Thiérache, René Dosière a exercé la profession de maître de conférences à l'université après des études en économie et sciences politiques. Ancien maire de Laon et député de l'Aisne, il est reconnu pour son expertise sur le contrôle des finances publiques et du budget de l'Élysée. Il a marqué la vie parlementaire par ses travaux sur la transparence démocratique.",
  "richard-ferrand": "Natif de Rodez, Richard Ferrand a mené une carrière de journaliste avant de diriger les Mutuelles de Bretagne pendant vingt ans. Ancien président de l'Assemblée nationale et ministre de la Cohésion des territoires, il est l'un des fondateurs du parti Renaissance. Il est élu député de la 6e circonscription du Finistère en juin 2012 et réélu lors des scrutins de 2017 et 2022.",
  "richard-ramos": "Natif de Blois, Richard Ramos a mené une carrière de chef d'entreprise et de consultant culinaire, engagé dans la défense de la gastronomie et des produits locaux. Membre du parti MoDem et spécialisé dans les enjeux de sécurité alimentaire et de lutte contre la malbouffe, il s'est investi dans la vie publique du Loiret. Il est élu député de la 6e circonscription du département en juin 2017 et réélu en 2022 et 2024.",
  "robin-redet": "Natif de Paris, Robin Redet a exercé des fonctions de cadre au sein de la haute administration après des études supérieures en droit public. Membre du groupe Ensemble pour la République et engagé sur les thématiques institutionnelles et de gestion publique, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de la 1re circonscription des Yvelines en octobre 2024.",
  "roger-vicot": "Natif de Valence et diplômé en droit public, Roger Vicot a exercé comme cadre administratif au sein de la fonction publique territoriale après une carrière de journaliste. Maire de Lambersart pendant trois ans et membre du Parti socialiste, il est spécialisé dans les enjeux de sécurité et de justice. Il est élu député de la 11e circonscription du Nord lors des élections législatives de juin 2022 et réélu en 2024.",
  "romain-baubry": "Natif de Saint-Quentin, Romain Baubry a exercé la profession de surveillant pénitentiaire après une carrière au sein de la gendarmerie nationale. Membre du Rassemblement national et conseiller municipal de Sénas, il est engagé sur les thématiques de sécurité intérieure et de souveraineté. Il est élu député de la 15e circonscription des Bouches-du-Rhône en juin 2022 et réélu au premier tour en juin 2024.",
  "romain-daubié": "Natif de Lyon, Romain Daubié exerce la profession d'avocat au barreau de l'Ain après des études supérieures en droit. Maire de Montluel depuis 2014 et membre de la majorité présidentielle (MoDem), il est engagé sur les thématiques de développement local et de proximité territoriale. Il est élu député de la 2e circonscription de l'Ain lors des élections législatives de juin 2022 et réélu en 2024.",
  "romain-esclapez": "Natif de Nice, Romain Esclapez a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique des Alpes-Maritimes. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "sacha-houlie": "Natif de Niort, Sacha Houlié exerce la profession d'avocat, spécialisé en droit de la construction. Co-fondateur des Jeunes avec Macron et membre de la commission des Lois, il a présidé cette dernière entre 2022 et 2024. Il est élu député de la 2e circonscription de la Vienne lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "salima-saa": "Native de Soissons et diplômée en droit et sciences politiques, Salima Saa a mené une carrière de cadre dirigeante et cheffe d'entreprise dans le secteur du conseil et de l'énergie. Membre du parti Les Républicains et ancienne présidente de l'ACSE, elle s'est investie dans la vie publique des Hauts-de-France. Elle rejoint l'Assemblée nationale en tant que députée du Nord lors des élections législatives de juillet 2024.",
  "samuel-azzopardi": "Natif de Victoria (Malte), Samuel Azzopardi a exercé la profession de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de solidarité et de développement local, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "sandrine-le-feur": "Native de Saint-Brieuc, Sandrine Le Feur exerce la profession d'agricultrice bio après des études supérieures en agronomie. Membre du parti Renaissance et engagée sur les thématiques de transition agroécologique et de circuit court, elle s'est investie dans la vie publique du Finistère. Elle est élue députée de la 4e circonscription du département en juin 2017 et réélue en 2022 et 2024.",
  "sandrine-rousseau": "Native de Maisons-Alfort et docteure en économie, Sandrine Rousseau est enseignante-chercheuse et a exercé comme vice-présidente de l'université de Lille. Figure majeure du parti Les Écologistes et engagée sur les thématiques d'éco-féminisme et de justice sociale, elle s'est investie dans la vie publique parisienne. Elle est élue députée de la 9e circonscription de Paris lors des élections législatives de juin 2022.",
  "sebastien-chenu": "Natif de Beauvais, Sébastien Chenu a exercé comme cadre dans la communication après avoir été collaborateur de cabinet ministériel. Vice-président de l'Assemblée nationale et porte-parole du Rassemblement national, il est spécialisé dans les enjeux institutionnels. Il est élu député de la 19e circonscription du Nord en juin 2017 et réélu au premier tour lors du scrutin de juin 2024.",
  "sebastien-delogu": "Natif de Marseille, Sébastien Delogu a exercé les professions de chauffeur de taxi et d'agent de sécurité après avoir été cadre administratif au sein du secteur privé. Membre de La France insoumise et engagé sur les thématiques de défense des quartiers populaires et de justice sociale, il est élu député de la 7e circonscription des Bouches-du-Rhône en juin 2022 et réélu au premier tour en 2024.",
  "sebastien-huyghe": "Natif de Béthune et diplômé en droit, Sébastien Huyghe exerce la profession de notaire après des études supérieures. Ancien membre du parti Les Républicains et engagé dans la vie publique du Nord, il est spécialisé dans les questions de justice et de sécurité. Il est élu député de la 5e circonscription du département en juin 2002 et réélu lors de chaque scrutin législatif suivant jusqu'en juin 2024.",
  "sebastien-jumel": "Natif de Sainte-Adresse, Sébastien Jumel a exercé comme cadre administratif après avoir été collaborateur parlementaire. Maire de Dieppe pendant neuf ans et membre du Parti communiste français, il est spécialisé dans les enjeux de décentralisation et d'industrie. Il est élu député de la 6e circonscription de la Seine-Maritime en juin 2017 et réélu lors du scrutin de 2022.",
  "sebastien-lecornu": "Natif d'Eaubonne, Sébastien Lecornu a exercé comme collaborateur parlementaire avant d'occuper plusieurs fonctions ministérielles (Outre-mer, Armées) entre 2017 et 2024. Président du conseil départemental de l'Eure et membre du parti Renaissance, il est spécialisé dans les enjeux de défense. Il est élu député de l'Eure lors des élections législatives de juillet 2024.",
  "sebastien-peyrane": "Natif de Paris, Sébastien Peyrane a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de l'Essonne en octobre 2024.",
  "sebastien-rome": "Natif de Lodève et diplômé en sciences de l'éducation, Sébastien Rome exerce la profession de directeur d'école après avoir été enseignant. Membre de La France insoumise et engagé sur les thématiques de ruralité et de défense des services publics, il s'est investi dans la vie publique de l'Hérault. Il est élu député de la 4e circonscription du département lors des élections législatives de juin 2022.",
  "segolene-amiot": "Native de Châtellerault, Ségolène Amiot a exercé comme chargée d'assistance technique au sein d'une entreprise de télécoms après des études de lettres. Membre de La France insoumise et engagée sur les thématiques de handicap et d'inclusion sociale, elle s'est investie dans la vie publique de Loire-Atlantique. Elle est élue députée de la 3e circonscription du département lors des élections législatives de juin 2022.",
  "simon-beausire": "Natif de Paris, Simon Beausire a exercé la profession de cadre au sein de la fonction publique d'État après des études supérieures. Membre du groupe Ensemble pour la République et engagé sur les enjeux de proximité et de développement local, il s'est investi dans la vie publique de Seine-Maritime. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "sophie-blanc": "Native de Perpignan, Sophie Blanc exerce la profession d'avocate au barreau de sa ville natale après des études supérieures en droit. Membre du Rassemblement national et conseillère régionale d'Occitanie, elle est engagée sur les thématiques de justice et de souveraineté nationale. Elle est élue députée de la 1re circonscription des Pyrénées-Orientales lors des élections législatives de juin 2022.",
  "sophie-mette": "Native de Paris, Sophie Mette a exercé comme cadre au sein du secteur médico-social après avoir été adjointe de direction dans le privé. Membre du parti MoDem et conseillère régionale de Nouvelle-Aquitaine, elle est engagée sur les enjeux de culture et de solidarité territoriale. Elle est élue députée de la 9e circonscription de la Gironde lors des élections législatives de juin 2017 et réélue en 2022 et 2024.",
  "sophie-pantel": "Native de Mende, Sophie Pantel a exercé comme cadre de la fonction publique territoriale après des études supérieures en droit. Présidente du conseil départemental de la Lozère depuis 2015 et membre du Parti socialiste, elle est engagée sur les thématiques de ruralité et de services publics. Elle est élue députée de la circonscription unique du département lors des législatives de juillet 2024.",
  "sophie-robert": "Native de Lyon, Sophie Robert a mené une carrière de cadre administratif et commercial au sein du secteur privé après des études supérieures. Membre du Rassemblement national et conseillère régionale d'Auvergne-Rhône-Alpes, elle s'est investie dans la vie publique de la Loire. Elle est élue députée de la 6e circonscription du département lors des élections législatives de juillet 2024.",
  "sophie-taille-polian": "Native de Paris et diplômée de l'IEP de Paris, Sophie Taillé-Polian est une haute fonctionnaire territoriale ayant exercé au sein de plusieurs collectivités locales. Ancienne sénatrice et cofondatrice du parti Génération.s, elle est spécialisée dans les enjeux de logement et de solidarité. Elle est élue députée de la 11e circonscription du Val-de-Marne en juin 2022 et réélue lors du scrutin de juillet 2024.",
  "soumya-bourouaha": "Native de Ghazaouet (Algérie), Soumya Bourouaha a mené une carrière de responsable de formation et de cadre administrative au sein du secteur privé. Adjointe au maire de La Courneuve et membre du Parti communiste français, elle est engagée sur les enjeux d'éducation et de citoyenneté. Elle est élue députée de la 4e circonscription de la Seine-Saint-Denis lors des élections législatives de juin 2022.",
  "steeve-briois": "Natif de Seclin, Steeve Briois a exercé comme cadre administratif après avoir été permanent politique de premier plan. Maire d'Hénin-Beaumont depuis 2014 et ancien député européen, il est une figure majeure du Rassemblement national. Il est spécialisé dans les questions de gestion municipale et de développement local, ayant marqué la vie publique du Pas-de-Calais.",
  "stella-dupont": "Native d'Angers, Stella Dupont a exercé la profession d'experte-comptable après des études supérieures en gestion et comptabilité. Maire de Chalonnes-sur-Loire pendant neuf ans et membre de la majorité présidentielle, elle est spécialisée dans les thématiques budgétaires et d'insertion. Elle est élue députée de la 2e circonscription du Maine-et-Loire en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "stephane-bouillon": "Natif de Cambrai et diplômé de l'ENA, Stéphane Bouillon est un haut fonctionnaire ayant exercé comme préfet de région et secrétaire général de la Défense et de la Sécurité nationale. Membre du groupe Ensemble pour la République et spécialisé dans les enjeux institutionnels et de sécurité, il rejoint l'Assemblée nationale en tant que député du département en octobre 2024.",
  "stephane-delautrette": "Natif de Limoges et diplômé en ingénierie territoriale, Stéphane Delautrette a exercé comme cadre au sein de la fonction publique territoriale après ses études. Maire de Saint-Genest-sur-Roselle et membre du Parti socialiste, il est spécialisé dans les enjeux d'aménagement durable et de ruralité. Il est élu député de la 2e circonscription de la Haute-Vienne lors des élections législatives de juin 2022.",
  "stephane-lenormand": "Natif de Saint-Pierre-et-Miquelon, Stéphane Lenormand a exercé comme cadre dirigeant au sein du secteur privé après des études supérieures. Ancien président du conseil territorial de l'archipel et membre du groupe LIOT, il porte les enjeux de souveraineté et de développement ultramarin à l'Assemblée. Il est élu député de la circonscription unique du territoire lors des élections législatives de juin 2022.",
  "stephane-mazars": "Natif de Rodez, Stéphane Mazars exerce la profession d'avocat au barreau de sa ville natale après des études supérieures en droit. Adjoint au maire de Rodez et membre du parti Renaissance, il s'est investi sur les thématiques de justice et de sécurité publique. Il est élu député de la 1re circonscription de l'Aveyron lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "stephane-peu": "Natif de Saint-Cloud, Stéphane Peu a exercé des fonctions de cadre au sein de la fonction publique territoriale après une carrière de militant. Adjoint au maire de Saint-Denis pendant de nombreuses années et membre du Parti communiste français, il est spécialisé dans les enjeux de logement et d'urbanisme. Il est élu député de la 2e circonscription de la Seine-Saint-Denis en juin 2017 et réélu depuis.",
  "stephane-rambour": "Natif d'Abbeville, Stéphane Rambour exerce la profession de cadre administratif au sein de la fonction publique d'État après une carrière de permanent politique. Membre du Rassemblement national et engagé sur les thématiques de sécurité et de défense des services publics ruraux, il s'est investi dans la vie publique du Pas-de-Calais. Il rejoint l'Assemblée nationale en tant que député du département en juin 2024.",
  "stephane-sejourne": "Natif de Versailles et diplômé en droit, Stéphane Séjourné a exercé comme conseiller politique et de cabinet ministériel avant de présider le groupe Renew au Parlement européen. Ministre de l'Europe et des Affaires étrangères et secrétaire général du parti Renaissance, il est spécialisé dans les enjeux diplomatiques. Il est élu député des Hauts-de-Seine lors des élections législatives de juillet 2024.",
  "stephane-travert": "Natif de Carentan, Stéphane Travert a exercé comme cadre commercial au sein du secteur privé avant d'occuper les fonctions de ministre de l'Agriculture et de l'Alimentation. Membre du parti Renaissance et engagé sur les thématiques de défense de la ruralité et de souveraineté alimentaire, il est élu député de la 3e circonscription de la Manche en juin 2012 et réélu depuis lors.",
  "stephane-vojetta": "Natif de Saint-Claude et diplômé de l'ESSEC, Stéphane Vojetta a mené une carrière de chef d'entreprise et de consultant en stratégie entre Madrid et Paris. Membre de la majorité présidentielle et spécialisé dans les thématiques de régulation numérique et d'influenceurs, il est élu député des Français établis hors de France (5e circonscription) en juin 2021 et réélu lors des scrutins de 2022 et 2024.",
  "stephanie-kocher": "Native de Lyon, Stéphanie Kocher a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de solidarité urbaine, elle s'est investie dans la vie publique du Rhône. Elle rejoint l'Assemblée nationale en tant que députée du département en octobre 2024.",
  "stephanie-rist": "Native de Paris et docteure en médecine, Stéphanie Rist exerce la profession de rhumatologue au sein du CHR d'Orléans après ses études. Membre du parti Renaissance et rapporteur générale de la commission des Affaires sociales, elle est spécialisée dans les questions de santé publique. Elle est élue députée de la 1re circonscription du Loiret en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "sylvain-berrios": "Natif de Saint-Maur-des-Fossés, Sylvain Berrios exerce la profession de cadre au sein du secteur privé après des études supérieures en droit. Maire de sa ville natale depuis 2012 et membre du parti Les Républicains, il est engagé sur les thématiques de développement local et de proximité urbaine. Il est élu député de la 1re circonscription du Val-de-Marne lors d'une partielle en 2012 et réélu en juillet 2024.",
  "sylvain-maillard": "Natif de Saint-Maur-des-Fossés, Sylvain Maillard est un chef d'entreprise ayant fondé Alantys Technology, société spécialisée dans la distribution de composants électroniques. Président du groupe Renaissance à l'Assemblée nationale entre 2023 et 2024, il est spécialisé dans les enjeux économiques. Il est élu député de la 1re circonscription de Paris lors des élections législatives de juin 2017 et réélu depuis.",
  "sylvie-ferreira": "Native de Paris, Sylvie Ferreira a mené une carrière de cadre administratif au sein du secteur privé après des études supérieures. Membre du groupe Ensemble pour la République et engagée sur les enjeux de proximité et de développement local, elle s'est investie dans la vie publique locale. Elle rejoint l'Assemblée nationale en tant que députée de Seine-et-Marne en octobre 2024.",
  "sylvie-ferrer": "Native de Tarbes, Sylvie Ferrer exerce la profession de cadre au sein du secteur médico-social après une carrière de militante associative. Membre de La France insoumise et engagée sur les thématiques de santé publique et de défense de l'environnement, elle s'est investie dans la vie publique des Hautes-Pyrénées. Elle est élue députée de la 1re circonscription du département lors des législatives de juin 2022.",
  "sylvie-marcilly": "Native de Rochefort, Sylvie Marcilly a exercé comme cadre administratif au sein de la fonction publique territoriale après une carrière dans le secteur privé. Présidente du conseil départemental de la Charente-Maritime depuis 2021 et membre du groupe Droite républicaine, elle est engagée sur les enjeux de ruralité. Elle est élue députée du département lors des élections législatives de juillet 2024.",
  "tanguy-nhan": "Natif de Paris, Tanguy Nhan a exercé des fonctions de cadre au sein de la haute administration après des études supérieures en droit public. Membre du groupe Ensemble pour la République et engagé sur les thématiques de gestion publique et de proximité, il s'est investi dans la vie publique locale. Il rejoint l'Assemblée nationale en tant que député de l'Essonne en octobre 2024.",
  "thibault-bazin": "Natif de Nancy et diplômé de Sciences Po Paris, Thibault Bazin a exercé comme cadre dans le secteur du logement social après des études supérieures en aménagement du territoire. Membre du groupe Droite républicaine et engagé sur les thématiques de famille et de cohésion sociale, il s'est investi dans la vie publique de Meurthe-et-Moselle. Il est élu député de la 4e circonscription du département en juin 2017 et réélu depuis.",
  "thierry-benoit": "Natif de Fougères, Thierry Benoit a exercé comme cadre commercial au sein du secteur privé avant de se consacrer à la vie publique. Maire de Lécousse pendant plusieurs années et membre du groupe Horizons, il est spécialisé dans les questions industrielles et de développement rural. Il est élu député de la 6e circonscription d'Ille-et-Vilaine sans interruption depuis juin 2007.",
  "thierry-frappe": "Natif de Forest-sur-Marque, Thierry Frappé exerce la profession de médecin généraliste, ayant pratiqué pendant plusieurs décennies. Conseiller municipal de sa commune d'adoption et membre du Rassemblement national, il s'est investi sur les thématiques d'accès aux soins et de déserts médicaux. Il est élu député de la 10e circonscription du Pas-de-Calais en juin 2022 et réélu au premier tour en juin 2024.",
  "thierry-perez": "Natif de Paris, Thierry Perez a mené une carrière de cadre dirigeant au sein de grands groupes industriels, notamment chez International Paper et Derichebourg. Conseiller régional d'Occitanie et membre du Rassemblement national, il s'est investi sur les thématiques de souveraineté économique et d'industrie. Il est élu député de la 10e circonscription de l'Isère lors des élections législatives de juillet 2024.",
  "thierry-sother": "Natif de Mulhouse, Thierry Sother a exercé les fonctions de cadre au sein de la fonction publique territoriale après des études supérieures. Premier secrétaire fédéral du Parti socialiste dans le Haut-Rhin, il s'est investi dans les politiques de développement local et de solidarité. Il est élu député de la 2e circonscription du département lors des élections législatives de juillet 2024, siégeant au sein du groupe SOC.",
  "thierry-tesson": "Natif des Sables-d'Olonne, Thierry Tesson a exercé comme inspecteur d'académie et sous-préfet après une carrière d'enseignant agrégé d'histoire. Membre du groupe Rassemblement national et engagé sur les enjeux d'éducation et de sécurité, il s'est investi dans la gestion publique de l'Amiénois. Il est élu député de la 3e circonscription de la Somme lors des élections législatives de juillet 2024.",
  "thomas-cazenave": "Natif de Bordeaux et inspecteur des finances, Thomas Cazenave a exercé des fonctions de direction chez Orange et Pôle emploi après des études à l'ENA. Ancien ministre délégué chargé des Comptes publics et membre du parti Renaissance, il est spécialisé dans les réformes de l'État et de l'administration. Il est élu député de la 1re circonscription de la Gironde en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "thomas-gassilloud": "Natif de Saint-Symphorien-sur-Coise, Thomas Gassilloud est entrepreneur, ayant fondé une société spécialisée dans les télécoms et l'Internet. Membre du parti Renaissance et ancien président de la commission de la Défense nationale, il est spécialisé dans les enjeux de souveraineté technologique. Il est élu député de la 10e circonscription du Rhône en juin 2017 et réélu lors des scrutins législatifs de 2022 et 2024.",
  "thomas-lam": "Natif de Villeurbanne, Thomas Lam est entrepreneur, ayant notamment créé et dirigé plusieurs sociétés de conseil et de services à la personne. Adjoint au maire de Courbevoie et membre du parti Horizons, il est engagé sur les thématiques de développement économique local. Il est élu député de la 2e circonscription des Hauts-de-Seine lors des élections législatives de juillet 2024.",
  "thomas-menage": "Natif de Blois, Thomas Ménagé a exercé comme cadre administratif et commercial au sein du secteur privé après des études supérieures en droit public. Membre du Rassemblement national et engagé sur les enjeux institutionnels et de défense des services publics ruraux, il s'est investi dans la vie publique du Loiret. Il est élu député de la 4e circonscription du département en juin 2022 et réélu en juin 2024.",
  "tiffany-joncour": "Native de Lyon, Tiffany Joncour a mené une carrière de cadre administratif et commercial au sein du secteur privé après des études supérieures. Membre du Rassemblement national et engagée dans la vie publique du Rhône, elle s'est investie sur les thématiques de proximité et de défense des services publics. Elle est élue députée de la 13e circonscription du département lors des élections législatives de juillet 2024.",
  "timothee-houssin": "Natif de Lille, Timothée Houssin a exercé comme cadre au sein d'une entreprise du secteur numérique après des études en marketing et communication. Membre du Rassemblement national et conseiller régional de Normandie, il est engagé sur les enjeux de souveraineté numérique et de développement local. Il est élu député de la 5e circonscription de l'Eure en juin 2022 et réélu lors du scrutin de juillet 2024.",
  "tristan-lahais": "Natif de Rennes, Tristan Lahais a exercé comme cadre administratif au sein du secteur privé après des études supérieures en sciences politiques. Membre du parti Génération.s et engagé dans la vie publique bretonne, il s'est investi sur les thématiques culturelles et de solidarité. Il est élu député de la 2e circonscription d'Ille-et-Vilaine lors des élections législatives de juillet 2024, siégeant au sein du groupe Écolo.",
  "ugo-bernalicis": "Natif d'Arras, Ugo Bernalicis a exercé comme fonctionnaire de catégorie A au sein du ministère de l'Intérieur après des études à l'IEP de Lille. Membre de La France insoumise et spécialisé dans les questions de sécurité intérieure et de justice, il porte les thématiques de libertés publiques à l'Assemblée nationale. Il est élu député de la 2e circonscription du Nord en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "valerie-bazin-malgras": "Native de Romilly-sur-Seine, Valérie Bazin-Malgras a exercé la profession de commerçante dans le secteur du prêt-à-porter après une carrière dans le secteur privé. Membre du parti Les Républicains et engagée dans la vie publique de l'Aube, elle s'est investie sur les enjeux de dynamisation des centres-villes. Elle est élue députée de la 2e circonscription du département en juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "valerie-letard": "Native d'Orchies, Valérie Létard a exercé comme cadre de la fonction publique territoriale après des études en travail social. Ancienne ministre et sénatrice, elle est une figure du parti UDI engagée sur les enjeux de logement et d'aménagement du territoire. Elle est élue députée de la 21e circonscription du Nord lors des élections législatives de juillet 2024, siégeant au sein du groupe LIOT.",
  "valerie-rossi": "Native de Marseille, Valérie Rossi a exercé comme cadre administrative au sein du secteur privé après des études supérieures. Maire de Puy-Sanières pendant seize ans et membre du Parti socialiste, elle s'est investie dans la vie publique des Hautes-Alpes, notamment sur les enjeux de ruralité. Elle est élue députée de la 2e circonscription du département lors des élections législatives de juillet 2024.",
  "veronique-besse": "Native de La Roche-sur-Yon, Véronique Besse a exercé la profession de journaliste au sein de la presse locale après des études supérieures. Maire des Herbiers depuis 2014 et engagée à droite, elle s'est investie sur les thématiques de souveraineté et de développement local. Elle est élue députée de la 4e circonscription de la Vendée lors des élections législatives de juin 2022 et réélu au premier tour en juin 2024.",
  "veronique-louwagie": "Native de Buis-sur-Damville, Véronique Louwagie exerce la profession d'expert-comptable après des études supérieures en gestion et comptabilité. Membre de la commission des Finances et élue sous l'étiquette de la Droite républicaine, elle est spécialisée dans les questions budgétaires et de fiscalité. Elle est élue députée de la 2e circonscription de l'Orne en juin 2012 et réélue lors de chaque scrutin législatif suivant.",
  "veronique-ludmann": "Native de La Bassée, Véronique Ludmann exerce la profession de directrice d'école au sein de l'Éducation nationale après une carrière d'enseignante. Membre du Rassemblement national et engagée dans la vie publique de la Meuse, elle s'est investie sur les thématiques d'éducation et de services publics ruraux. Elle est élue députée de la 2e circonscription du département lors des élections législatives de juillet 2024.",
  "veronique-riotton": "Native de Bonneville, Véronique Riotton a mené une carrière de consultante et coach spécialisée en Ressources Humaines après des études supérieures. Membre du parti Renaissance et engagée sur les enjeux de droits des femmes et de protection de l'enfance, elle s'est investie dans la vie publique de Haute-Savoie. Elle est élue députée de la 1re circonscription du département en juin 2017 et réélue depuis lors.",
  "vincent-caure": "Natif de Castres, Vincent Caure a exercé des fonctions de cadre au sein de la haute administration, ayant notamment été conseiller à l'Élysée après ses études. Membre du parti Renaissance et engagé sur les thématiques de transport et de transition écologique, il est une figure de la majorité présidentielle. Il est élu député de la 3e circonscription des Français établis hors de France lors des élections législatives de juillet 2024.",
  "vincent-descoeur": "Natif d'Aurillac, Vincent Descoeur exerce la profession de professeur agrégé de biologie après des études scientifiques supérieures. Ancien président du conseil départemental du Cantal et membre de la Droite républicaine, il est engagé sur les enjeux de montagne et de désenclavement des territoires. Il est élu député de la 1re circonscription du département en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "vincent-ledoux": "Natif de Watermael-Boitsfort (Belgique), Vincent Ledoux a exercé comme cadre au sein de la fonction publique territoriale après des études supérieures. Maire de Roncq pendant onze ans et membre du parti Renaissance, il est engagé sur les thématiques de solidarité et de justice sociale. Il est élu député de la 10e circonscription du Nord lors des élections législatives de juin 2017 et réélu lors du scrutin de juillet 2024.",
  "vincent-rolland": "Natif de Moûtiers, Vincent Rolland a exercé comme collaborateur parlementaire après des études supérieures en gestion. Membre du parti Les Républicains et engagé dans la vie publique savoyarde, il est spécialisé dans les enjeux liés au tourisme et à l'économie de montagne. Il est élu député de la 2e circonscription de la Savoie lors des élections législatives de juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "vincent-thiebaut": "Natif de Toulouse, Vincent Thiébaut a exercé comme cadre au sein du secteur privé, spécialisé dans les domaines techniques et industriels. Membre du parti Horizons et engagé sur les thématiques de transition énergétique et de coopération transfrontalière, il s'est investi dans la vie publique du Bas-Rhin. Il est élu député de la 9e circonscription du département en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "vincent-trebuchet": "Natif de Paris, Vincent Trébuchet a mené une carrière de cadre administratif et commercial au sein du secteur privé après des études supérieures. Membre du groupe Rassemblement national et engagé sur les enjeux de souveraineté économique et de ruralité, il s'est investi dans la vie publique de l'Ardèche. Il est élu député de la 2e circonscription du département lors des élections législatives de juillet 2024.",
  "violette-spillebout": "Native de Lyon, Violette Spillebout a mené une carrière de cadre au sein de la SNCF, occupant notamment des fonctions de directrice de projet après des études supérieures. Membre du parti Renaissance et conseillère municipale de Lille, elle est engagée sur les thématiques de sécurité publique et de santé environnementale. Elle est élue députée de la 9e circonscription du Nord en juin 2022 et réélue en juillet 2024.",
  "xavier-albertini": "Natif de Royan, Xavier Albertini a exercé la profession de juriste au sein du secteur privé après des études supérieures en droit. Adjoint au maire de Reims pendant huit ans et membre du parti Horizons, il est engagé sur les thématiques de sécurité intérieure et de libertés publiques. Il est élu député de la 1re circonscription de la Marne lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "xavier-breton": "Natif de Darney, Xavier Breton a exercé comme cadre au sein de la fonction publique territoriale après des études à Sciences Po Paris. Membre du parti Les Républicains et ancien adjoint au maire de Bourg-en-Bresse, il est engagé sur les enjeux de famille et de valeurs républicaines. Il est élu député de la 1re circonscription de l'Ain lors des élections législatives de juin 2007 et réélu lors de chaque scrutin suivant.",
  "xavier-roseren": "Natif de Chamonix-Mont-Blanc, Xavier Roseren exerce la profession de commerçant spécialisé dans les articles de sport après une carrière dans le secteur privé. Membre du parti Renaissance et maire des Houches pendant treize ans, il est engagé sur les thématiques de protection de l'environnement montagnard. Il est élu député de la 6e circonscription de Haute-Savoie en juin 2017 et réélu lors des scrutins de 2022 et 2024.",
  "yael-braun-pivet": "Native de Nancy, Yaël Braun-Pivet exerce la profession d'avocate au barreau de Paris puis de Nanterre après des études de droit. Présidente de l'Assemblée nationale depuis 2022 et membre du parti Renaissance, elle est la première femme à occuper cette fonction. Elle est élue députée de la 5e circonscription des Yvelines lors des élections législatives de juin 2017 et réélue lors des scrutins de 2022 et 2024.",
  "yael-menache": "Native de Péronne, Yaël Ménaché a exercé comme commerciale au sein du secteur privé, notamment dans l'industrie de la bijouterie. Membre du Rassemblement national et engagée sur les thématiques de pouvoir d'achat et de défense de l'industrie locale, elle s'est investie dans la vie publique de la Somme. Elle est élue députée de la 5e circonscription du département en juin 2022 et réélue au premier tour en juin 2024.",
  "yannick-chenevard": "Natif de Toulon, Yannick Chenevard a exercé comme consultant spécialisé dans la gestion de crise après une carrière au sein de la sécurité civile. Adjoint au maire de Toulon et membre de la majorité présidentielle, il est engagé sur les enjeux de défense et de protection des populations. Il est élu député de la 1re circonscription du Var lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "yannick-favennec-becot": "Natif de Chaudron-en-Mauges, Yannick Favennec-Bécot a exercé les fonctions de directeur de cabinet après une carrière au sein du secteur privé. Membre du groupe Horizons et engagé dans la vie publique de la Mayenne, il est spécialisé dans les questions de santé en milieu rural et de services publics. Il est élu député de la 3e circonscription du département en juin 2002 et réélu lors de chaque scrutin législatif suivant.",
  "yannick-monnet": "Natif de Moulins, Yannick Monnet a exercé comme cadre au sein de la fonction publique après avoir mené des études supérieures. Membre du Parti communiste français et conseiller régional d'Auvergne-Rhône-Alpes, il est engagé sur les thématiques de défense de l'industrie et des services publics. Il est élu député de la 1re circonscription de l'Allier lors des élections législatives de juin 2022 et réélu lors du scrutin de juillet 2024.",
  "yannick-neuder": "Natif de Tullins, Yannick Neuder exerce la profession de cardiologue au sein du CHU de Grenoble après des études de médecine. Vice-président de la région Auvergne-Rhône-Alpes et membre du parti Les Républicains, il est spécialisé dans les questions de santé et d'innovation médicale. Il est élu député de la 7e circonscription de l'Isère lors des élections législatives de juin 2022 et réélu en 2024.",
  "yoann-gillet": "Natif de Rennes, Yoann Gillet a exercé des fonctions de cadre au sein de la fonction publique territoriale après des études supérieures en gestion. Conseiller régional d'Occitanie et membre du Rassemblement national, il est engagé sur les thématiques de sécurité et de gestion des deniers publics. Il est élu député de la 1re circonscription du Gard lors des élections législatives de juin 2022 et réélu en 2024.",
  "zahia-hamdane": "Native d'Amiens, Zahia Hamdane exerce la profession d'éducatrice spécialisée au sein du secteur médico-social après des études supérieures. Conseillère régionale des Hauts-de-France et membre de La France insoumise, elle est engagée sur les thématiques de protection de l'enfance et de justice sociale. Elle est élue députée de la 2e circonscription de la Somme lors des élections législatives de juillet 2024."
};

async function main() {
  console.log("--- INJECTION DES PORTRAITS ---");
  let updated = 0;

  for (const [slug, bio] of Object.entries(portraits)) {
    const { error } = await supabase
      .from('deputies')
      .update({ biography: bio })
      .eq('slug', slug);
    
    if (!error) updated++;
    else console.error(`Erreur pour ${slug}:`, error.message);
  }

  console.log(`\nTERMINE : ${updated} portraits injectés.`);
}

main().catch(console.error);
